import { serializeIdList, slugifyContent } from "./admin-normalizers";
import { withLocalStoreFallback } from "./admin-store-dispatch";
import { purgeCdnCache } from "./cache-purge";
import { dispatchPluginContentEvent, getCmsConfig } from "./config";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";
import {
	type ContentStatus,
	cleanIdList,
	detectConflict,
	insertContentRevision,
	normalizeLegacyUrl,
	normalizeScheduledAt,
	normalizeSeoFields,
	nullsToUndefined,
	SQL_INSERT_CONTENT_ENTRY,
	SQL_INSERT_CREATE_OVERRIDE,
	serializeMetadata,
	trimOrNull,
	UPSERT_CONTENT_OVERRIDE_SQL,
} from "./runtime-actions-content-helpers";
import {
	ensureD1BaselineRevision,
	findPageRecord,
	mapContentState,
	normalizeContentStatus,
	replaceD1ContentAssignments,
	validateContentTypeFields,
} from "./runtime-actions-content-shared";
import type { SaveContentInput } from "./runtime-actions-content-types";

export async function saveRuntimeContentState(
	slug: string,
	input: SaveContentInput,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const pageRecord = await findPageRecord(slug, locals);
			if (!pageRecord) {
				return {
					ok: false as const,
					error: "The selected content record could not be found.",
				};
			}

			const title = input.title.trim();
			const seoTitle = input.seoTitle.trim();
			const metaDescription = input.metaDescription.trim();
			const status: ContentStatus = normalizeContentStatus(input.status);
			const body = input.body?.trim() || pageRecord.body || "";
			const scheduledAt = normalizeScheduledAt(input.scheduledAt);
			const revisionNote = trimOrNull(input.revisionNote);
			const authorIds = cleanIdList(input.authorIds);
			const categoryIds = cleanIdList(input.categoryIds);
			const tagIds = cleanIdList(input.tagIds);

			if (!title || !seoTitle || !metaDescription) {
				return {
					ok: false as const,
					error: "Title, SEO title, and meta description are required.",
				};
			}

			await ensureD1BaselineRevision(db, pageRecord);

			if (input.lastKnownUpdatedAt) {
				const conflict = await detectConflict(db, pageRecord.slug, input.lastKnownUpdatedAt);
				if (conflict) return conflict;
			}

			// Content type field validation
			const metadata = input.metadata ?? {};
			const fieldError = validateContentTypeFields(pageRecord.templateKey, metadata);
			if (fieldError) {
				return { ok: false as const, error: fieldError };
			}
			const metadataJson = serializeMetadata(metadata);
			const seo = normalizeSeoFields(input);

			await db
				.prepare(UPSERT_CONTENT_OVERRIDE_SQL)
				.bind(
					pageRecord.slug,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
					seo.excerpt,
					seo.ogTitle,
					seo.ogDescription,
					seo.ogImage,
					scheduledAt,
					seo.canonicalUrlOverride,
					seo.robotsDirective,
					metadataJson,
					actor.email,
				)
				.run();

			await replaceD1ContentAssignments(db, pageRecord.slug, {
				authorIds,
				categoryIds,
				tagIds,
			});

			await insertContentRevision(db, pageRecord.slug, {
				title,
				status,
				scheduledAt,
				body,
				seoTitle,
				metaDescription,
				seo,
				authorIds: serializeIdList(authorIds),
				categoryIds: serializeIdList(categoryIds),
				tagIds: serializeIdList(tagIds),
				revisionNote,
				actor,
			});

			await recordD1Audit(
				locals,
				actor,
				"content.update",
				"content",
				pageRecord.slug,
				`Updated reviewed metadata for ${pageRecord.legacyUrl}.`,
			);

			const pluginEvent = {
				slug: pageRecord.slug,
				kind: "post",
				status,
				actor: actor.email,
			};
			await dispatchPluginContentEvent("onContentSave", pluginEvent);
			if (status === "published") {
				await dispatchPluginContentEvent("onContentPublish", pluginEvent);
				// Fire CDN purge asynchronously — failure must not block the publish response
				void purgeCdnCache(pageRecord.slug, getCmsConfig());
			}

			return {
				ok: true as const,
				state: mapContentState(pageRecord, {
					title,
					status,
					scheduledAt: scheduledAt ?? undefined,
					body,
					authorIds,
					categoryIds,
					tagIds,
					seoTitle,
					metaDescription,
					...nullsToUndefined(seo),
				}),
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.saveContentState(slug, input, actor),
	);
}

export async function createRuntimeContentRecord(
	input: {
		title: string;
		slug: string;
		legacyUrl?: string;
		status: string;
		body?: string;
		summary?: string;
		seoTitle: string;
		metaDescription: string;
		excerpt?: string;
		ogTitle?: string;
		ogDescription?: string;
		ogImage?: string;
		canonicalUrlOverride?: string;
		robotsDirective?: string;
	},
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const title = input.title.trim();
			const slug = slugifyContent(input.slug);
			const legacyUrl = normalizeLegacyUrl(input.legacyUrl, slug);
			const seoTitle = input.seoTitle.trim() || title;
			const metaDescription = input.metaDescription.trim();
			const status = normalizeContentStatus(input.status);
			const body = input.body?.trim() || "";
			const summary = input.summary?.trim() || "";
			const seo = normalizeSeoFields(input);

			if (!title || !slug || !metaDescription) {
				return {
					ok: false as const,
					error: "Title, slug, and meta description are required.",
				};
			}

			if (
				(await findPageRecord(slug, locals)) ||
				(await findPageRecord(legacyUrl.replace(/^\//, ""), locals))
			) {
				return { ok: false as const, error: "That slug is already in use." };
			}

			try {
				await db
					.prepare(SQL_INSERT_CONTENT_ENTRY)
					.bind(
						slug,
						legacyUrl,
						title,
						`runtime://content/${slug}`,
						body,
						summary,
						seoTitle,
						metaDescription,
						seo.ogTitle,
						seo.ogDescription,
						seo.ogImage,
					)
					.run();
				/* v8 ignore next 3 */
			} catch {
				return {
					ok: false as const,
					error: "That slug or route is already in use.",
				};
			}

			const createSeo = { ...seo, excerpt: seo.excerpt || summary || null };

			await db
				.prepare(SQL_INSERT_CREATE_OVERRIDE)
				.bind(
					slug,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
					createSeo.excerpt,
					createSeo.ogTitle,
					createSeo.ogDescription,
					createSeo.ogImage,
					createSeo.canonicalUrlOverride,
					createSeo.robotsDirective,
					actor.email,
				)
				.run();

			await insertContentRevision(db, slug, {
				title,
				status,
				body,
				seoTitle,
				metaDescription,
				seo: createSeo,
				authorIds: "[]",
				categoryIds: "[]",
				tagIds: "[]",
				revisionNote: "Created new post.",
				actor,
			});

			await recordD1Audit(
				locals,
				actor,
				"content.create",
				"content",
				slug,
				`Created post ${legacyUrl}.`,
			);

			return {
				ok: true as const,
				state: {
					slug,
					legacyUrl,
					title,
					status,
					body,
					seoTitle,
					metaDescription,
				},
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.createContentRecord(input, actor),
	);
}

// delegates content.restore audit action
export { restoreRuntimeRevision } from "./runtime-actions-content-restore";

src/runtime-actions-misc.ts.source:
import { normalizeRedirectPath } from "./admin-normalizers";
import { withLocalStoreFallback } from "./admin-store-dispatch";
import { recordD1Audit } from "./d1-audit";
import type { Actor } from "./persistence-types";
import { defaultSiteSettings, type SiteSettings } from "./site-settings";
import {
	normalizeTranslationState,
	type TranslationState,
	translationStates,
} from "./translation-state";

export async function updateRuntimeTranslationState(
	route: string,
	state: string,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const normalizedState = normalizeTranslationState(state, "__invalid__" as TranslationState);
			if (!(translationStates as readonly string[]).includes(normalizedState)) {
				return {
					ok: false as const,
					error: `Invalid translation state. Must be one of: ${translationStates.join(", ")}`,
				};
			}

			await db
				.prepare(
					`
            INSERT INTO translation_overrides (route, state, updated_at, updated_by)
            VALUES (?, ?, CURRENT_TIMESTAMP, ?)
            ON CONFLICT(route) DO UPDATE SET
              state = excluded.state,
              updated_at = CURRENT_TIMESTAMP,
              updated_by = excluded.updated_by
          `,
				)
				.bind(route, normalizedState, actor.email)
				.run();

			await recordD1Audit(
				locals,
				actor,
				"translation.update",
				"content",
				route,
				`Updated translation state for ${route} to ${normalizedState}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.updateTranslationState(route, state, actor),
	);
}

export async function createRuntimeRedirectRule(
	input: { sourcePath: string; targetPath: string; statusCode: number },
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const sourcePath = normalizeRedirectPath(input.sourcePath);
			const targetPath = normalizeRedirectPath(input.targetPath);
			const statusCode = input.statusCode === 302 ? 302 : 301;

			if (!sourcePath || !targetPath) {
				return {
					ok: false as const,
					error: "Both legacy and target paths are required.",
				};
			}

			if (sourcePath === targetPath) {
				return {
					ok: false as const,
					error: "Legacy and target paths must be different.",
				};
			}

			const existing = await db
				.prepare("SELECT deleted_at FROM redirect_rules WHERE source_path = ? LIMIT 1")
				.bind(sourcePath)
				.first<{ deleted_at: string | null }>();

			if (existing && existing.deleted_at === null) {
				return {
					ok: false as const,
					error: "That legacy path already has a reviewed redirect rule.",
				};
			}

			await db
				.prepare(
					`
            INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at)
            VALUES (?, ?, ?, ?, NULL)
            ON CONFLICT(source_path) DO UPDATE SET
              target_path = excluded.target_path,
              status_code = excluded.status_code,
              created_by = excluded.created_by,
              deleted_at = NULL
          `,
				)
				.bind(sourcePath, targetPath, statusCode, actor.email)
				.run();

			await recordD1Audit(
				locals,
				actor,
				"redirect.create",
				"redirect",
				sourcePath,
				`Created redirect ${sourcePath} -> ${targetPath} (${statusCode}).`,
			);

			return {
				ok: true as const,
				rule: { sourcePath, targetPath, statusCode },
			};
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.createRedirectRule(input, actor),
	);
}

export async function deleteRuntimeRedirectRule(
	sourcePath: string,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const normalizedSourcePath = normalizeRedirectPath(sourcePath);
			const result = await db
				.prepare(
					"UPDATE redirect_rules SET deleted_at = CURRENT_TIMESTAMP WHERE source_path = ? AND deleted_at IS NULL",
				)
				.bind(normalizedSourcePath)
				.run();

			/* v8 ignore next 4 */
			if (!result.success) {
				return { ok: false as const };
			}

			const row = await db
				.prepare("SELECT deleted_at FROM redirect_rules WHERE source_path = ? LIMIT 1")
				.bind(normalizedSourcePath)
				.first<{ deleted_at: string | null }>();

			if (!row?.deleted_at) {
				return { ok: false as const };
			}

			await recordD1Audit(
				locals,
				actor,
				"redirect.delete",
				"redirect",
				normalizedSourcePath,
				`Deleted redirect ${normalizedSourcePath}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.deleteRedirectRule(sourcePath, actor),
	);
}

export async function moderateRuntimeComment(
	commentId: string,
	nextStatus: "pending" | "approved" | "rejected",
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const comment = await db
				.prepare("SELECT route FROM comments WHERE id = ? LIMIT 1")
				.bind(commentId)
				.first<{ route: string }>();
			if (!comment) {
				return {
					ok: false as const,
					error: "The selected comment record could not be found.",
				};
			}

			await db
				.prepare("UPDATE comments SET status = ? WHERE id = ?")
				.bind(nextStatus, commentId)
				.run();
			await recordD1Audit(
				locals,
				actor,
				"comment.moderate",
				"comment",
				commentId,
				`Marked ${comment.route} as ${nextStatus}.`,
			);
			return { ok: true as const };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.moderateComment(commentId, nextStatus, actor),
	);
}

export async function saveRuntimeSettings(
	partial: Partial<SiteSettings>,
	actor: Actor,
	locals?: App.Locals | null,
) {
	return withLocalStoreFallback(
		locals,
		async (db) => {
			const currentRow = await db
				.prepare(
					`
            SELECT site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug
            FROM site_settings
            WHERE id = 1
            LIMIT 1
          `,
				)
				.first<{
					site_title: string;
					site_tagline: string;
					donation_url: string;
					newsletter_enabled: number;
					comments_default_policy: SiteSettings["commentsDefaultPolicy"];
					admin_slug: string;
				}>();

			const current: SiteSettings = currentRow
				? {
						siteTitle: currentRow.site_title,
						siteTagline: currentRow.site_tagline,
						donationUrl: currentRow.donation_url,
						newsletterEnabled: currentRow.newsletter_enabled === 1,
						commentsDefaultPolicy: currentRow.comments_default_policy,
						adminSlug: currentRow.admin_slug,
					}
				: { ...defaultSiteSettings };

			const updated: SiteSettings = {
				siteTitle: partial.siteTitle ?? current.siteTitle,
				siteTagline: partial.siteTagline ?? current.siteTagline,
				donationUrl: partial.donationUrl ?? current.donationUrl,
				newsletterEnabled: partial.newsletterEnabled ?? current.newsletterEnabled,
				commentsDefaultPolicy: partial.commentsDefaultPolicy ?? current.commentsDefaultPolicy,
				adminSlug: partial.adminSlug ?? current.adminSlug,
			};

			await db
				.prepare(
					`
            INSERT INTO site_settings (
              id, site_title, site_tagline, donation_url, newsletter_enabled, comments_default_policy, admin_slug, updated_at, updated_by
            ) VALUES (?, ?, ?, ?, ?, ?, ?, CURRENT_TIMESTAMP, ?)
            ON CONFLICT(id) DO UPDATE SET
              site_title = excluded.site_title,
              site_tagline = excluded.site_tagline,
              donation_url = excluded.donation_url,
              newsletter_enabled = excluded.newsletter_enabled,
              comments_default_policy = excluded.comments_default_policy,
              admin_slug = excluded.admin_slug,
              updated_at = CURRENT_TIMESTAMP,
              updated_by = excluded.updated_by
          `,
				)
				.bind(
					1,
					updated.siteTitle,
					updated.siteTagline,
					updated.donationUrl,
					updated.newsletterEnabled ? 1 : 0,
					updated.commentsDefaultPolicy,
					updated.adminSlug,
					actor.email,
				)
				.run();

			await recordD1Audit(
				locals,
				actor,
				"settings.update",
				"auth",
				"site-settings",
				"Updated site settings.",
			);
			return { ok: true as const, settings: updated };
		},
		/* v8 ignore next 1 */
		(localStore) => localStore.saveSettings(partial, actor),
	);
}

