src/sitemap.ts.source:
/**
 * Sitemap generator for Astropress sites.
 *
 * Generates a sitemap.xml string from published content records.
 * In SSR mode call this from a `/sitemap.xml` Astro endpoint.
 * In static mode the same endpoint runs at build time.
 */

import { stripTrailingSlashes } from "./path-helpers";
import type { AstropressPlatformAdapter } from "./platform-contracts";

export interface SitemapEntry {
	url: string;
	lastmod?: string;
	changefreq?: "always" | "hourly" | "daily" | "weekly" | "monthly" | "yearly" | "never";
	priority?: number;
}

/**
 * Generate a sitemap.xml body from the platform adapter's published content.
 *
 * @param adapter  The platform adapter (read-only ContentStore is sufficient).
 * @param baseUrl  The canonical origin, e.g. "https://example.com".
 * @returns        A UTF-8 sitemap XML string.
 */
export async function generateAstropressSitemap(
	adapter: Pick<AstropressPlatformAdapter, "content">,
	baseUrl: string,
): Promise<string> {
	const origin = stripTrailingSlashes(baseUrl);

	// Fetch published posts and pages
	const [posts, pages] = await Promise.all([
		adapter.content.list("post", { status: "published" }),
		adapter.content.list("page", { status: "published" }),
	]);

	const entries: SitemapEntry[] = [
		// Homepage
		{ url: `${origin}/`, priority: 1.0, changefreq: "weekly" },
	];

	for (const post of posts) {
		entries.push({
			url: `${origin}/blog/${post.slug}/`,
			lastmod:
				typeof post.metadata?.updatedAt === "string"
					? post.metadata.updatedAt.slice(0, 10)
					: undefined,
			changefreq: "monthly",
			priority: 0.7,
		});
	}

	for (const page of pages) {
		entries.push({
			url: `${origin}/${page.slug}/`,
			lastmod:
				typeof page.metadata?.updatedAt === "string"
					? page.metadata.updatedAt.slice(0, 10)
					: undefined,
			changefreq: "monthly",
			priority: 0.8,
		});
	}

	return buildSitemapXml(entries);
}

function buildSitemapXml(entries: SitemapEntry[]): string {
	const urlElements = entries
		.map((entry) => {
			const parts = ["  <url>", `    <loc>${escapeXml(entry.url)}</loc>`];
			if (entry.lastmod) parts.push(`    <lastmod>${entry.lastmod}</lastmod>`);
			if (entry.changefreq) parts.push(`    <changefreq>${entry.changefreq}</changefreq>`);
			if (entry.priority !== undefined)
				parts.push(`    <priority>${entry.priority.toFixed(1)}</priority>`);
			parts.push("  </url>");
			return parts.join("\n");
		})
		.join("\n");

	return [
		`<?xml version="1.0" encoding="UTF-8"?>`,
		`<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">`,
		urlElements,
		"</urlset>",
	].join("\n");
}

function escapeXml(str: string): string {
	return str
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&apos;");
}

src/sqlite-bootstrap-migrations.ts.source:
import { existsSync, readdirSync, readFileSync } from "node:fs";
import path from "node:path";
import type { AstropressRollbackResult, SqliteDatabaseLike } from "./sqlite-bootstrap-helpers";

/**
 * Run incremental SQL migrations from a directory against a live SQLite database.
 *
 * Migration files must be named with a numeric prefix (e.g. `0001_add_column.sql`).
 * They are applied in lexicographic order. Applied migrations are recorded in
 * `schema_migrations` so they are never re-run.
 */
export function runAstropressMigrations(
	db: SqliteDatabaseLike,
	migrationsDir: string,
): { applied: string[]; skipped: string[] } {
	const applied: string[] = [];
	const skipped: string[] = [];

	db.exec(`CREATE TABLE IF NOT EXISTS schema_migrations (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL UNIQUE,
    applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
    rollback_sql TEXT
  )`);

	const migrationCols = new Set(
		(
			db.prepare("PRAGMA table_info(schema_migrations)").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);
	if (!migrationCols.has("rollback_sql")) {
		db.exec("ALTER TABLE schema_migrations ADD COLUMN rollback_sql TEXT");
	}

	const alreadyApplied = new Set(
		(
			db.prepare("SELECT name FROM schema_migrations").all() as Array<{
				name: string;
			}>
		).map((r) => r.name),
	);

	if (!existsSync(migrationsDir)) return { applied, skipped };

	for (const file of readdirSync(migrationsDir)
		.filter((f) => f.endsWith(".sql"))
		.sort()) {
		if (alreadyApplied.has(file)) {
			skipped.push(file);
			continue;
		}
		const sql = readFileSync(path.join(migrationsDir, file), "utf8");
		db.exec(sql);

		const downFilePath = path.join(migrationsDir, file.replace(/\.sql$/, ".down.sql"));
		const rollbackSql = existsSync(downFilePath) ? readFileSync(downFilePath, "utf8") : null;
		db.prepare("INSERT INTO schema_migrations (name, rollback_sql) VALUES (?, ?)").run(
			file,
			rollbackSql,
		);
		applied.push(file);
	}

	return { applied, skipped };
}

/**
 * The number of framework-owned migrations Astropress applies during bootstrapping.
 * Used by `checkSchemaVersionAhead` to detect host-app migrations.
 */
export const ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE = 1;

/**
 * Checks whether the database `schema_migrations` table has more entries than the
 * framework's known baseline.
 */
export function checkSchemaVersionAhead(
	db: SqliteDatabaseLike,
	frameworkBaseline = ASTROPRESS_FRAMEWORK_MIGRATION_BASELINE,
): { isAhead: boolean; dbCount: number; frameworkCount: number } | null {
	try {
		const row = db.prepare("SELECT COUNT(*) as count FROM schema_migrations").get() as
			| { count: number }
			| undefined;
		if (!row) return null;
		return {
			isAhead: row.count > frameworkBaseline,
			dbCount: row.count,
			frameworkCount: frameworkBaseline,
		};
	} catch {
		return null;
	}
}

/**
 * Rolls back the most recently applied migration by executing its `rollback_sql` and
 * removing its record from `schema_migrations`. Returns the name of the rolled-back
 * migration, or `null` if there are no applied migrations or the last one has no rollback SQL.
 */
export function rollbackAstropressLastMigration(db: SqliteDatabaseLike): string | null {
	const last = db
		.prepare("SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1")
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!last) return null;
	if (last.rollback_sql) {
		db.exec(last.rollback_sql);
	}
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(last.name);
	return last.name;
}

export function rollbackAstropressLastMigrationWithOptions(
	db: SqliteDatabaseLike,
	options: { dryRun?: boolean } = {},
): AstropressRollbackResult {
	const dryRun = options.dryRun ?? false;
	const row = db
		.prepare("SELECT name, rollback_sql FROM schema_migrations ORDER BY id DESC LIMIT 1")
		.get() as { name: string; rollback_sql: string | null } | undefined;

	if (!row) {
		return { migrationName: null, status: "no_migrations", dryRun };
	}
	if (!row.rollback_sql) {
		return { migrationName: row.name, status: "no_rollback_sql", dryRun };
	}
	if (dryRun) {
		return { migrationName: row.name, status: "dry_run", dryRun: true };
	}

	db.exec(row.rollback_sql);
	db.prepare("DELETE FROM schema_migrations WHERE name = ?").run(row.name);
	return { migrationName: row.name, status: "rolled_back", dryRun: false };
}

src/sqlite-bootstrap-seeders.ts.source:
import { getCmsConfig } from "./config.js";
import type {
	ArchiveSeedRecord,
	AstropressSqliteSeedToolkitOptions,
	MarketingRouteSeedRecord,
	SqliteDatabaseLike,
	SystemRouteSeed,
} from "./sqlite-bootstrap.js";
import {
	SQL_SEED_ARCHIVE_GROUP,
	SQL_SEED_ARCHIVE_VARIANT,
	SQL_SEED_MARKETING_GROUP,
	SQL_SEED_MARKETING_VARIANT,
	SQL_SEED_SITE_SETTINGS,
	SQL_SEED_SYSTEM_GROUP,
	SQL_SEED_SYSTEM_REVISION,
	SQL_SEED_SYSTEM_VARIANT,
} from "./sqlite-bootstrap-seed-sql.js";
import { guessMimeType, hashPasswordSync } from "./sqlite-seed-helpers.js";

/** Build bind params for a system route variant insert. */
function systemRouteVariantParams(route: SystemRouteSeed) {
	return [
		route.variantId,
		route.groupId,
		route.path,
		route.title,
		route.summary ?? null,
		route.bodyHtml ?? null,
		route.settingsJson ?? null,
		route.title,
		route.metaDescription ?? route.summary ?? route.title,
		route.robotsDirective ?? null,
		"seed-import",
	];
}

/** Build the revision snapshot JSON for a system route. */
function systemRouteSnapshot(route: SystemRouteSeed) {
	return JSON.stringify({
		path: route.path,
		title: route.title,
		summary: route.summary ?? "",
		bodyHtml: route.bodyHtml ?? "",
		settings: route.settingsJson ? JSON.parse(route.settingsJson) : null,
		renderStrategy: route.renderStrategy,
	});
}

/** Build bind params for an archive route variant insert. */
function archiveVariantParams(archive: ArchiveSeedRecord, variantId: string, groupId: string) {
	return [
		variantId,
		groupId,
		archive.legacyUrl,
		archive.title,
		archive.summary ?? null,
		archive.seoTitle ?? archive.title,
		archive.metaDescription ?? archive.summary ?? "",
		archive.canonicalUrlOverride ?? null,
		archive.robotsDirective ?? null,
		"seed-import",
	];
}

/** Resolve a marketing route's locale from config or fallback. */
function resolveMarketingLocale(pagePath: string): string {
	let configLocales: readonly string[];
	try {
		configLocales = getCmsConfig().locales ?? ["en", "es"];
	} catch {
		configLocales = ["en", "es"];
	}
	return configLocales.find((l) => pagePath.startsWith(`/${l}/`)) ?? configLocales[0] ?? "en";
}

/** Build bind params for a marketing route variant insert. */
function marketingVariantParams(
	page: MarketingRouteSeedRecord,
	variantId: string,
	groupId: string,
	locale: string,
) {
	return [
		variantId,
		groupId,
		locale,
		page.path,
		page.title,
		page.summary,
		JSON.stringify(page.sections),
		JSON.stringify({
			templateKey: page.templateKey,
			alternateLinks: page.alternateLinks ?? [],
		}),
		page.seoTitle,
		page.metaDescription,
		page.ogImage ?? null,
		page.canonicalUrlOverride ?? null,
		page.robotsDirective ?? null,
		"seed-import",
	];
}

export function seedBootstrapUsers(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const upsert = db.prepare(`
    INSERT INTO admin_users (email, password_hash, name, active, is_admin)
    VALUES (?, ?, ?, 1, ?)
    ON CONFLICT(email) DO UPDATE SET
      password_hash = excluded.password_hash,
      name = excluded.name,
      active = 1,
      is_admin = excluded.is_admin
  `);
	let count = 0;
	for (const user of options.loadBootstrapUsers()) {
		const result = upsert.run(
			user.email.toLowerCase(),
			hashPasswordSync(user.password),
			user.name,
			user.role === "admin" ? 1 : 0,
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedMediaAssets(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
	workspaceRoot: string,
) {
	const insert = db.prepare(`
    INSERT INTO media_assets (
      id, source_url, local_path, r2_key, mime_type, file_size, alt_text, title, uploaded_by
    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
    ON CONFLICT(id) DO UPDATE SET
      source_url = excluded.source_url,
      local_path = excluded.local_path,
      r2_key = excluded.r2_key,
      mime_type = excluded.mime_type,
      uploaded_by = excluded.uploaded_by,
      deleted_at = NULL
  `);
	let count = 0;
	for (const asset of options.loadMediaSeeds(workspaceRoot)) {
		const result = insert.run(
			asset.id,
			asset.sourceUrl ?? null,
			asset.localPath ?? `/images/legacy/${asset.id}`,
			asset.r2Key ?? null,
			guessMimeType(asset.localPath ?? asset.sourceUrl ?? asset.id),
			null,
			"",
			asset.id,
			"seed-import",
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

export function seedRedirects(options: AstropressSqliteSeedToolkitOptions, db: SqliteDatabaseLike) {
	const insert = db.prepare(`
    INSERT INTO redirect_rules (source_path, target_path, status_code, created_by, deleted_at)
    VALUES (?, ?, ?, ?, NULL)
    ON CONFLICT(source_path) DO UPDATE SET
      target_path = excluded.target_path,
      status_code = excluded.status_code,
      created_by = excluded.created_by,
      deleted_at = NULL
  `);
	let count = 0;
	for (const rule of options.redirectRules) {
		const result = insert.run(rule.sourcePath, rule.targetPath, rule.statusCode, "seed-import") as {
			changes?: number;
		};
		count += result.changes ?? 1;
	}
	return count;
}

export function seedComments(options: AstropressSqliteSeedToolkitOptions, db: SqliteDatabaseLike) {
	const insert = db.prepare(`
    INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP))
    ON CONFLICT(id) DO NOTHING
  `);
	let count = 0;
	for (const comment of options.comments) {
		const result = insert.run(
			comment.id,
			comment.author,
			comment.email ?? null,
			comment.body ?? null,
			comment.route,
			comment.status,
			comment.policy,
			comment.submittedAt ?? null,
		) as { changes?: number };
		count += result.changes ?? 0;
	}
	return count;
}

export function seedSiteSettings(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const result = db
		.prepare(SQL_SEED_SITE_SETTINGS)
		.run(
			1,
			options.siteSettings.siteTitle,
			options.siteSettings.siteTagline,
			options.siteSettings.donationUrl,
			options.siteSettings.newsletterEnabled ? 1 : 0,
			options.siteSettings.commentsDefaultPolicy,
			"seed-import",
		) as { changes?: number };
	return result.changes ?? 0;
}

export function seedSystemRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_SYSTEM_GROUP);
	const insertVariant = db.prepare(SQL_SEED_SYSTEM_VARIANT);
	const insertRevision = db.prepare(SQL_SEED_SYSTEM_REVISION);

	let count = 0;
	for (const route of options.systemRoutes) {
		insertGroup.run(route.groupId, route.renderStrategy, route.path);
		const result = insertVariant.run(...systemRouteVariantParams(route)) as {
			changes?: number;
		};
		count += result.changes ?? 1;
		insertRevision.run(
			`revision:${route.variantId}:seed`,
			route.variantId,
			route.path,
			systemRouteSnapshot(route),
			"Imported baseline",
			"seed-import",
		);
	}
	return count;
}

export function seedArchiveRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_ARCHIVE_GROUP);
	const insertVariant = db.prepare(SQL_SEED_ARCHIVE_VARIANT);

	let count = 0;
	for (const archive of options.archiveRoutes) {
		const baseId = archive.legacyUrl.replace(/^\//, "").replaceAll("/", ":") || "root";
		const groupId = `archive:${baseId}`;
		const variantId = `variant:archive:${baseId}:en`;
		insertGroup.run(groupId, archive.legacyUrl);
		const result = insertVariant.run(...archiveVariantParams(archive, variantId, groupId)) as {
			changes?: number;
		};
		count += result.changes ?? 1;
	}
	return count;
}

export function seedMarketingRoutes(
	options: AstropressSqliteSeedToolkitOptions,
	db: SqliteDatabaseLike,
) {
	const insertGroup = db.prepare(SQL_SEED_MARKETING_GROUP);
	const insertVariant = db.prepare(SQL_SEED_MARKETING_VARIANT);

	let count = 0;
	for (const page of options.marketingRoutes) {
		const locale = resolveMarketingLocale(page.path);
		const baseId = page.path.replace(/^\//, "").replaceAll("/", ":");
		const groupId = `page:${baseId}`;
		const variantId = `variant:page:${baseId}:${locale}`;
		insertGroup.run(groupId, locale, page.path);
		const result = insertVariant.run(
			...marketingVariantParams(page, variantId, groupId, locale),
		) as { changes?: number };
		count += result.changes ?? 1;
	}
	return count;
}

