import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import {
	ADMIN_USERS_DROP_ROLE_HEAD,
	ADMIN_USERS_DROP_ROLE_TAIL,
	CONTENT_LOCKS_DDL,
	FTS5_INDEX_DDL,
	REBUILD_OVERRIDES_HEAD,
	REBUILD_OVERRIDES_TAIL,
	REBUILD_REVISIONS_FOOTER,
	REBUILD_REVISIONS_MID_AFTER_TAGS,
	REBUILD_REVISIONS_MID_BEFORE_AUTHORS,
} from "./sqlite-schema-compat-data.js";

export function getTableColumns(db: SqliteDatabaseLike, table: string) {
	return (db.prepare(`PRAGMA table_info(${table})`).all() as Array<{ name: string }>).map(
		(column) => column.name,
	);
}

export function getTableSql(db: SqliteDatabaseLike, table: string) {
	return (
		db.prepare("SELECT sql FROM sqlite_master WHERE type = 'table' AND name = ?").get(table) as
			| { sql: string | null }
			| undefined
	)?.sql;
}

export function rebuildContentTablesForCompatibility(
	db: SqliteDatabaseLike,
	options: {
		hasRevisionAuthorIds: boolean;
		hasRevisionCategoryIds: boolean;
		hasRevisionTagIds: boolean;
		hasOverrideScheduledAt: boolean;
		hasRevisionScheduledAt: boolean;
		hasRevisionNote: boolean;
	},
) {
	const authorIdsSelect = options.hasRevisionAuthorIds ? "COALESCE(author_ids, '[]')" : "'[]'";
	const categoryIdsSelect = options.hasRevisionCategoryIds
		? "COALESCE(category_ids, '[]')"
		: "'[]'";
	const tagIdsSelect = options.hasRevisionTagIds ? "COALESCE(tag_ids, '[]')" : "'[]'";
	const overrideScheduledAtSelect = options.hasOverrideScheduledAt ? "scheduled_at" : "NULL";
	const revisionScheduledAtSelect = options.hasRevisionScheduledAt ? "scheduled_at" : "NULL";
	const revisionNoteSelect = options.hasRevisionNote ? "revision_note" : "NULL";

	db.exec(
		REBUILD_OVERRIDES_HEAD +
			overrideScheduledAtSelect +
			REBUILD_OVERRIDES_TAIL +
			revisionScheduledAtSelect +
			REBUILD_REVISIONS_MID_BEFORE_AUTHORS +
			authorIdsSelect +
			",\n      " +
			categoryIdsSelect +
			",\n      " +
			tagIdsSelect +
			REBUILD_REVISIONS_MID_AFTER_TAGS +
			revisionNoteSelect +
			REBUILD_REVISIONS_FOOTER,
	);
}

export function ensureFts5SearchIndex(db: SqliteDatabaseLike) {
	const existing = db
		.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'content_fts'")
		.get() as { name: string } | undefined;
	if (existing) {
		return;
	}
	db.exec(FTS5_INDEX_DDL);
}

export function ensureLegacySchemaCompatibility(db: SqliteDatabaseLike) {
	const revisionColumns = new Set(getTableColumns(db, "content_revisions"));
	const overrideColumns = new Set(getTableColumns(db, "content_overrides"));
	const needsRevisionColumns =
		!revisionColumns.has("author_ids") ||
		!revisionColumns.has("category_ids") ||
		!revisionColumns.has("tag_ids") ||
		!revisionColumns.has("scheduled_at") ||
		!revisionColumns.has("revision_note");
	const needsOverrideColumns = !overrideColumns.has("scheduled_at");

	if (!overrideColumns.has("metadata")) {
		db.exec("ALTER TABLE content_overrides ADD COLUMN metadata TEXT");
	}

	const mediaColumns = new Set(getTableColumns(db, "media_assets"));
	if (!mediaColumns.has("thumbnail_url")) {
		db.exec("ALTER TABLE media_assets ADD COLUMN thumbnail_url TEXT");
	}
	if (!mediaColumns.has("srcset")) {
		db.exec("ALTER TABLE media_assets ADD COLUMN srcset TEXT");
	}

	const migrationColumns = new Set(getTableColumns(db, "schema_migrations"));
	if (!migrationColumns.has("rollback_sql")) {
		db.exec("ALTER TABLE schema_migrations ADD COLUMN rollback_sql TEXT");
	}

	// ABAC migration: legacy admin_users may lack is_admin. Add the column
	// with a DEFAULT 0; the terminal rebuild below re-derives the actual
	// value from role (where present) via a CASE in its INSERT...SELECT,
	// so a separate UPDATE backfill here would be redundant.
	const adminUserColumns = new Set(getTableColumns(db, "admin_users"));
	if (adminUserColumns.size > 0 && !adminUserColumns.has("is_admin")) {
		db.exec("ALTER TABLE admin_users ADD COLUMN is_admin INTEGER NOT NULL DEFAULT 0");
	}

	// Terminal access-PR migration: rebuild admin_users without the legacy
	// `role` column. Fires when the column is still present. Idempotent:
	// only runs when role exists.
	const refreshedAdminColumns = new Set(getTableColumns(db, "admin_users"));
	if (refreshedAdminColumns.has("role")) {
		const activeExpr = refreshedAdminColumns.has("active") ? "active" : "1";
		const createdAtExpr = refreshedAdminColumns.has("created_at")
			? "created_at"
			: "CURRENT_TIMESTAMP";
		const nameExpr = refreshedAdminColumns.has("name") ? "name" : "email";
		db.exec(
			ADMIN_USERS_DROP_ROLE_HEAD +
				nameExpr +
				", " +
				activeExpr +
				", " +
				createdAtExpr +
				ADMIN_USERS_DROP_ROLE_TAIL,
		);
	}

	db.exec(CONTENT_LOCKS_DDL);

	const overrideSql = getTableSql(db, "content_overrides") ?? "";
	const revisionSql = getTableSql(db, "content_revisions") ?? "";
	const needsExpandedStatuses =
		!overrideSql.includes("'review'") ||
		!overrideSql.includes("'archived'") ||
		!revisionSql.includes("'review'") ||
		!revisionSql.includes("'archived'");

	if (!needsRevisionColumns && !needsOverrideColumns && !needsExpandedStatuses) {
		return;
	}

	rebuildContentTablesForCompatibility(db, {
		hasRevisionAuthorIds: revisionColumns.has("author_ids"),
		hasRevisionCategoryIds: revisionColumns.has("category_ids"),
		hasRevisionTagIds: revisionColumns.has("tag_ids"),
		hasOverrideScheduledAt: overrideColumns.has("scheduled_at"),
		hasRevisionScheduledAt: revisionColumns.has("scheduled_at"),
		hasRevisionNote: revisionColumns.has("revision_note"),
	});
}

src/sqlite-runtime/integrations-d1.ts.source:
/**
 * D1 sibling of `integrations.ts`. Mirrors the sqlite repository's
 * status + secret surface, but every method is async (D1's SDK
 * exposes only promise-returning calls) and `connect` is a single
 * `db.batch([...])` so the status row and the sealed-secret row land
 * atomically — important because the operator-visible "connected"
 * badge in the admin UI is keyed off the status row, and we never
 * want a window where it shows "connected" while the secret is still
 * missing (or, worse, vice-versa).
 *
 * Schema parity with the sqlite version is enforced by
 * `tooling/scripts/audit-integration-secrets-schema-parity.ts` — both
 * files share the same column names, kid values, and ON CONFLICT
 * shapes. A drift between the two raw SQL bodies fails CI.
 *
 * Why a separate file rather than parameterising the sqlite one:
 *   * the sqlite repo's sync surface (findStatus, listStatuses,
 *     updateStatus, disconnect, listPreviousKidContexts) is used
 *     transitively by code that is itself sync; making them async
 *     would force a Promise.all sweep through unrelated call sites.
 *     The D1 repo is async-only; the dispatch layer
 *     (`runtime-actions-integrations.ts`, the OAuth seal helper) is
 *     the place that bridges the two surfaces.
 *   * `db.batch()` is a D1-only primitive — there's no clean way to
 *     express it through the sqlite `prepare().run()` shape used by
 *     `node:sqlite` / `better-sqlite3`.
 */

import type { D1DatabaseLike } from "../d1-database";
import type {
	RootSecretCandidates,
	SealedSecret,
	SecretContext,
} from "../integration-secret-envelope";
import { openIntegrationSecret, sealIntegrationSecret } from "../integration-secret-envelope";
import type {
	ConnectIntegrationInput,
	IntegrationStatusRow,
	IntegrationStatusValue,
} from "./integrations";

// Shared SQL bodies — kept in sync with the sqlite file by the
// schema-parity audit. The exact whitespace + ON CONFLICT shape is
// what the audit checks, so do not "tidy" these without updating the
// parity audit's expectation in lockstep.
export const D1_SQL_FIND_STATUS = `
  SELECT domain, provider, status, config_json, connected_at,
         last_check_at, last_error
    FROM connected_integrations
   WHERE domain = ? AND provider = ?`;

export const D1_SQL_LIST_STATUSES = `
  SELECT domain, provider, status, config_json, connected_at,
         last_check_at, last_error
    FROM connected_integrations
   ORDER BY domain, provider`;

export const D1_SQL_UPSERT_STATUS = `
  INSERT INTO connected_integrations (
    domain, provider, status, config_json, connected_at,
    last_check_at, last_error
  ) VALUES (?, ?, ?, ?, ?, NULL, NULL)
  ON CONFLICT(domain, provider) DO UPDATE SET
    status = excluded.status,
    config_json = excluded.config_json,
    connected_at = excluded.connected_at,
    last_check_at = NULL,
    last_error = NULL`;

export const D1_SQL_UPDATE_STATUS = `
  UPDATE connected_integrations
     SET status = ?, last_check_at = ?, last_error = ?
   WHERE domain = ? AND provider = ?`;

export const D1_SQL_DISCONNECT = `
  DELETE FROM connected_integrations
   WHERE domain = ? AND provider = ?`;

export const D1_SQL_FIND_SECRET = `
  SELECT domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
         dek_wrap, data_iv, ciphertext, rotated_at
    FROM integration_secrets
   WHERE domain = ? AND provider = ?`;

export const D1_SQL_UPSERT_SECRET = `
  INSERT INTO integration_secrets (
    domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
    dek_wrap, data_iv, ciphertext, rotated_at
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  ON CONFLICT(domain, provider) DO UPDATE SET
    envelope_v = excluded.envelope_v,
    kid = excluded.kid,
    wrap_salt = excluded.wrap_salt,
    wrap_iv = excluded.wrap_iv,
    dek_wrap = excluded.dek_wrap,
    data_iv = excluded.data_iv,
    ciphertext = excluded.ciphertext,
    rotated_at = excluded.rotated_at`;

export const D1_SQL_RESEAL_GUARDED = `
  UPDATE integration_secrets
     SET envelope_v = ?, kid = ?, wrap_salt = ?, wrap_iv = ?,
         dek_wrap = ?, data_iv = ?, ciphertext = ?, rotated_at = ?
   WHERE domain = ? AND provider = ?
     AND ciphertext = ?
     AND kid = ?`;

export const D1_SQL_LIST_PREVIOUS_SECRETS = `
  SELECT domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
         dek_wrap, data_iv, ciphertext, rotated_at
    FROM integration_secrets
   WHERE kid = 'previous'`;

interface RawStatusRow {
	readonly domain: string;
	readonly provider: string;
	readonly status: string;
	readonly config_json: string;
	readonly connected_at: string;
	readonly last_check_at: string | null;
	readonly last_error: string | null;
}

interface RawSecretRow {
	readonly domain: string;
	readonly provider: string;
	readonly envelope_v: number;
	readonly kid: string;
	readonly wrap_salt: string;
	readonly wrap_iv: string;
	readonly dek_wrap: string;
	readonly data_iv: string;
	readonly ciphertext: string;
	readonly rotated_at: string;
}

function rowToStatus(row: RawStatusRow): IntegrationStatusRow {
	return {
		domain: row.domain,
		provider: row.provider,
		status: row.status as IntegrationStatusValue,
		configJson: row.config_json,
		connectedAt: row.connected_at,
		lastCheckAt: row.last_check_at,
		lastError: row.last_error,
	};
}

function rowToSealed(row: RawSecretRow): SealedSecret {
	return {
		v: row.envelope_v as 1,
		kid: row.kid as "current" | "previous",
		wrap_salt: row.wrap_salt,
		wrap_iv: row.wrap_iv,
		dek_wrap: row.dek_wrap,
		data_iv: row.data_iv,
		ciphertext: row.ciphertext,
	};
}

export interface D1IntegrationsRepository {
	findStatus(domain: string, provider: string): Promise<IntegrationStatusRow | undefined>;
	listStatuses(): Promise<IntegrationStatusRow[]>;
	updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): Promise<boolean>;
	disconnect(domain: string, provider: string): Promise<boolean>;

	connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void>;

	findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined>;

	listPreviousKidContexts(): Promise<SecretContext[]>;
}

export interface D1IntegrationsRepositoryOptions {
	getDb: () => D1DatabaseLike;
	/**
	 * Timestamp source for `findSecret`'s reseal-on-read UPDATE. Accepts
	 * either a literal ISO-8601 string (good enough for short-lived
	 * action handlers — connect/reverify/disconnect — that pass the
	 * caller's `now` directly) or a callable (used by long-lived hosts
	 * that mint a fresh timestamp per reseal). Other methods do not
	 * consult this field.
	 */
	now: string | (() => string);
}

export function createD1IntegrationsRepository(
	options: D1IntegrationsRepositoryOptions,
): D1IntegrationsRepository {
	const { getDb } = options;
	const now: () => string =
		typeof options.now === "function" ? options.now : () => options.now as string;

	async function findStatus(
		domain: string,
		provider: string,
	): Promise<IntegrationStatusRow | undefined> {
		const row = await getDb()
			.prepare(D1_SQL_FIND_STATUS)
			.bind(domain, provider)
			.first<RawStatusRow>();
		return row ? rowToStatus(row) : undefined;
	}

	async function listStatuses(): Promise<IntegrationStatusRow[]> {
		const result = await getDb().prepare(D1_SQL_LIST_STATUSES).all<RawStatusRow>();
		return result.results.map(rowToStatus);
	}

	async function updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): Promise<boolean> {
		const result = await getDb()
			.prepare(D1_SQL_UPDATE_STATUS)
			.bind(input.status, input.lastCheckAt, input.lastError ?? null, input.domain, input.provider)
			.run();
		// Stryker disable next-line all: defensive `?.` + `?? 0` cover a D1 SDK shape where `meta` is absent on a 0-row write; exercised by the "tolerates a D1 result without `meta`" test below but the equivalent-mutant pair survives stryker.
		return Number(result.meta?.changes ?? 0) > 0;
	}

	async function disconnect(domain: string, provider: string): Promise<boolean> {
		const result = await getDb().prepare(D1_SQL_DISCONNECT).bind(domain, provider).run();
		// Stryker disable next-line all: defensive `?.` + `?? 0` cover a D1 SDK shape where `meta` is absent on a 0-row write; exercised by the "tolerates a D1 result without `meta`" test below but the equivalent-mutant pair survives stryker.
		return Number(result.meta?.changes ?? 0) > 0;
	}

	async function connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void> {
		const sealed = await sealIntegrationSecret(
			input.secretFields,
			{ domain: input.domain, provider: input.provider },
			rootSecret,
		);
		const db = getDb();
		// Atomic batch — the operator never sees a half-applied
		// connect (status row written but secret missing, or vice
		// versa). D1 rolls back the entire batch on any failure.
		await db.batch([
			db
				.prepare(D1_SQL_UPSERT_STATUS)
				.bind(input.domain, input.provider, "connected", input.configJson, input.now),
			db
				.prepare(D1_SQL_UPSERT_SECRET)
				.bind(
					input.domain,
					input.provider,
					sealed.v,
					sealed.kid,
					sealed.wrap_salt,
					sealed.wrap_iv,
					sealed.dek_wrap,
					sealed.data_iv,
					sealed.ciphertext,
					input.now,
				),
		]);
	}

	async function findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined> {
		const row = await getDb()
			.prepare(D1_SQL_FIND_SECRET)
			.bind(domain, provider)
			.first<RawSecretRow>();
		if (!row) return undefined;
		const sealed = rowToSealed(row);
		const ctx: SecretContext = { domain, provider };
		const opened = await openIntegrationSecret<TFields>(sealed, ctx, rootSecrets);
		// Reseal-on-read: same predicate as the sqlite repo. The
		// guarded UPDATE matches on the *prior* ciphertext + kid, so
		// a concurrent reseal racing ahead silently loses with zero
		// rows affected — safe.
		if (opened.usedKid === "previous" && rootSecrets.previous) {
			const resealed = await sealIntegrationSecret(opened.fields, ctx, rootSecrets.current);
			await getDb()
				.prepare(D1_SQL_RESEAL_GUARDED)
				.bind(
					resealed.v,
					resealed.kid,
					resealed.wrap_salt,
					resealed.wrap_iv,
					resealed.dek_wrap,
					resealed.data_iv,
					resealed.ciphertext,
					now(),
					domain,
					provider,
					row.ciphertext,
					row.kid,
				)
				.run();
		}
		return opened.fields;
	}

	async function listPreviousKidContexts(): Promise<SecretContext[]> {
		const result = await getDb().prepare(D1_SQL_LIST_PREVIOUS_SECRETS).all<RawSecretRow>();
		return result.results.map((row) => ({
			domain: row.domain,
			provider: row.provider,
		}));
	}

	return {
		findStatus,
		listStatuses,
		updateStatus,
		disconnect,
		connect,
		findSecret,
		listPreviousKidContexts,
	};
}

src/sqlite-runtime/routes-helpers.ts.source:
import type { Actor } from "../persistence-types";
import { normalizeStructuredTemplateKey, parseSystemSettings } from "./utils";

export interface SystemRouteRecord {
	path: string;
	title: string;
	summary?: string;
	bodyHtml?: string;
	renderStrategy: "structured_sections" | "generated_text" | "generated_xml";
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	settings: Record<string, unknown> | null;
	updatedAt?: string;
}
export interface ArchiveRouteRecord {
	path: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	updatedAt?: string;
}
export interface StructuredPageRouteRecord {
	path: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	sections: Record<string, unknown> | null;
	updatedAt?: string;
}

export type SystemRouteRow = {
	path: string;
	title: string;
	summary: string | null;
	body_html: string | null;
	settings_json: string | null;
	updated_at: string | null;
	render_strategy: SystemRouteRecord["renderStrategy"];
};
export type ArchiveRouteRow = {
	path: string;
	title: string;
	summary: string | null;
	seo_title: string | null;
	meta_description: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	updated_at: string | null;
};
export type StructuredPageRow = {
	path: string;
	title: string;
	summary: string | null;
	seo_title: string | null;
	meta_description: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	og_image: string | null;
	sections_json: string | null;
	settings_json: string | null;
	updated_at: string | null;
};

// Stryker disable StringLiteral: SQL keywords inside these constants are
// data, not control flow — a String mutation on `SELECT` or `FROM` produces
// invalid SQL that the database rejects, and the test suite already asserts
// behavior end-to-end against a real SQLite instance. Mutating individual
// keywords adds ~30 noise mutants per file with no signal. The strings
// themselves are still covered indirectly by every routes test that runs.
export const SQL_LIST_SYSTEM = `SELECT v.path, v.title, v.summary, v.body_html, v.settings_json, v.updated_at, g.render_strategy FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'system' ORDER BY v.path ASC`;
export const SQL_LIST_STRUCTURED = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.og_image, v.sections_json, v.settings_json, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' ORDER BY v.path ASC`;
export const SQL_GET_ARCHIVE = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' AND v.path = ? LIMIT 1`;
export const SQL_LIST_ARCHIVES = `SELECT v.path, v.title, v.summary, v.seo_title, v.meta_description, v.canonical_url_override, v.robots_directive, v.updated_at FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' ORDER BY v.path ASC`;
export const SQL_FIND_SYSTEM_FOR_UPDATE = `SELECT v.id, g.render_strategy FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'system' AND v.path = ? LIMIT 1`;
export const SQL_PERSIST_SYSTEM =
	"UPDATE cms_route_variants SET title = ?, summary = ?, body_html = ?, settings_json = ?, seo_title = ?, meta_description = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_INSERT_REVISION =
	"INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by) VALUES (?, ?, ?, ?, ?, ?, ?)";
export const SQL_IS_PATH_TAKEN =
	"SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE v.path = ? LIMIT 1";
export const SQL_FIND_STRUCTURED_FOR_UPDATE = `SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'page' AND g.render_strategy = 'structured_sections' AND v.path = ? LIMIT 1`;
export const SQL_INSERT_ROUTE_GROUP = `INSERT INTO cms_route_groups (id, kind, render_strategy, canonical_locale, canonical_path) VALUES (?, 'page', 'structured_sections', ?, ?)`;
export const SQL_INSERT_ROUTE_VARIANT = `INSERT INTO cms_route_variants (id, group_id, locale, path, status, title, summary, sections_json, settings_json, seo_title, meta_description, og_image, canonical_url_override, robots_directive, updated_by) VALUES (?, ?, ?, ?, 'published', ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`;
export const SQL_PERSIST_STRUCTURED =
	"UPDATE cms_route_variants SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?, og_image = ?, sections_json = ?, settings_json = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_FIND_ARCHIVE_FOR_UPDATE = `SELECT v.id FROM cms_route_variants v INNER JOIN cms_route_groups g ON g.id = v.group_id WHERE g.kind = 'archive' AND v.path = ? LIMIT 1`;
export const SQL_PERSIST_ARCHIVE =
	"UPDATE cms_route_variants SET title = ?, summary = ?, seo_title = ?, meta_description = ?, canonical_url_override = ?, robots_directive = ?, updated_at = CURRENT_TIMESTAMP, updated_by = ? WHERE id = ?";
export const SQL_INSERT_ARCHIVE_REVISION = `INSERT INTO cms_route_revisions (id, variant_id, route_path, locale, snapshot_json, revision_note, created_by) VALUES (?, ?, ?, 'en', ?, ?, ?)`;
// Stryker restore StringLiteral

export interface InsertStructuredInput {
	pathname: string;
	locale: string;
	title: string;
	summary: string;
	seoTitle: string;
	metaDescription: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	sections: Record<string, unknown> | null;
	actor: Actor;
}
export interface PersistStructuredInput {
	routeId: string;
	title: string;
	summary: string;
	seoTitle: string;
	metaDescription: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	ogImage?: string;
	templateKey: string;
	alternateLinks: Array<{ hreflang: string; href: string }>;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	sections: Record<string, unknown> | null;
	actor: Actor;
}
export interface AppendStructuredRevisionInput extends InsertStructuredInput {
	routeId: string;
	revisionNote: string;
}
export interface PersistArchiveInput {
	routeId: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	actor: Actor;
}
export interface AppendArchiveRevisionInput {
	routeId: string;
	pathname: string;
	title: string;
	summary?: string;
	seoTitle?: string;
	metaDescription?: string;
	canonicalUrlOverride?: string;
	robotsDirective?: string;
	revisionNote: string;
	actor: Actor;
}

export function mapArchiveRow(row: ArchiveRouteRow): ArchiveRouteRecord {
	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		updatedAt: row.updated_at ?? undefined,
	};
}

export function mapStructuredPageRow(row: StructuredPageRow): StructuredPageRouteRecord | null {
	const settings = parseSystemSettings(row.settings_json) ?? {};
	const templateKey = normalizeStructuredTemplateKey(settings.templateKey);
	if (!templateKey) return null;
	return {
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		seoTitle: row.seo_title ?? undefined,
		metaDescription: row.meta_description ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		ogImage: row.og_image ?? undefined,
		templateKey,
		alternateLinks: Array.isArray(settings.alternateLinks)
			? (settings.alternateLinks as Array<{ hreflang: string; href: string }>)
			: [],
		sections: parseSystemSettings(row.sections_json),
		updatedAt: row.updated_at ?? undefined,
	} satisfies StructuredPageRouteRecord;
}

