import { createAstropressLocalMediaRepository } from "../local-media-repository-factory";
import type { Actor } from "../persistence-types";
import { createAstropressRateLimitRepository } from "../rate-limit-repository-factory";
import {
	SQL_GET_MEDIA_FOR_DELETE,
	SQL_INC_RATE_LIMIT,
	SQL_INSERT_MEDIA,
	SQL_READ_RATE_LIMIT,
	SQL_RESET_RATE_LIMIT,
	SQL_SOFT_DELETE_MEDIA,
	SQL_UPDATE_MEDIA,
} from "./assets-data.js";
import { recordAudit } from "./audit-log";
import type { AstropressSqliteDatabaseLike } from "./utils";

export function createSqliteAssetsStore(
	getDb: () => AstropressSqliteDatabaseLike,
	now: () => number,
) {
	const sqliteRateLimitRepository = createAstropressRateLimitRepository({
		now,
		readRateLimitWindow(key: string) {
			const row = getDb().prepare(SQL_READ_RATE_LIMIT).get(key) as
				| { count: number; window_start_ms: number; window_ms: number }
				| undefined;
			if (!row) return null;
			return {
				count: row.count,
				windowStartMs: row.window_start_ms,
				windowMs: row.window_ms,
			};
		},
		resetRateLimitWindow(key: string, currentTime: number, windowMs: number) {
			getDb().prepare(SQL_RESET_RATE_LIMIT).run(key, currentTime, windowMs);
		},
		incrementRateLimitWindow(key: string) {
			getDb().prepare(SQL_INC_RATE_LIMIT).run(key);
		},
	});

	function listMediaAssets() {
		const rows = getDb()
			.prepare(
				`
          SELECT id, source_url, local_path, r2_key, mime_type, width, height, file_size, alt_text, title, uploaded_at, uploaded_by
          FROM media_assets
          WHERE deleted_at IS NULL
          ORDER BY datetime(uploaded_at) DESC, id DESC
        `,
			)
			.all() as Array<{
			id: string;
			source_url: string | null;
			local_path: string;
			r2_key: string | null;
			mime_type: string | null;
			width: number | null;
			height: number | null;
			file_size: number | null;
			alt_text: string | null;
			title: string | null;
			uploaded_at: string;
			uploaded_by: string | null;
		}>;

		return rows.map((row) => ({
			id: row.id,
			sourceUrl: row.source_url,
			localPath: row.local_path,
			r2Key: row.r2_key,
			mimeType: row.mime_type,
			width: row.width,
			height: row.height,
			fileSize: row.file_size,
			altText: row.alt_text ?? "",
			title: row.title ?? "",
			uploadedAt: row.uploaded_at,
			uploadedBy: row.uploaded_by ?? "",
		}));
	}

	function updateMediaAsset(
		input: {
			id: string;
			title?: string;
			altText?: string;
		},
		actor: Actor,
	) {
		const id = input.id.trim();
		if (!id) {
			return { ok: false as const, error: "Media asset id is required." };
		}

		const result = getDb()
			.prepare(SQL_UPDATE_MEDIA)
			.run(input.title?.trim() ?? "", input.altText?.trim() ?? "", id);

		if (result.changes === 0) {
			return {
				ok: false as const,
				error: "The selected media asset could not be updated.",
			};
		}

		recordAudit(getDb(), actor, "media.update", `Updated media metadata for ${id}.`, "content", id);
		return { ok: true as const };
	}

	const sqliteMediaRepository = createAstropressLocalMediaRepository({
		listMediaAssets,
		updateMediaAsset,
		insertStoredMediaAsset({
			asset,
			actor,
		}: {
			asset: {
				id: string;
				publicPath: string;
				r2Key: string | null;
				mimeType: string | null;
				fileSize: number | null;
				altText: string;
				title: string;
				storedFilename?: string;
			};
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_INSERT_MEDIA)
				.run(
					asset.id,
					null,
					asset.publicPath,
					asset.r2Key,
					asset.mimeType,
					asset.fileSize,
					asset.altText,
					asset.title,
					actor.email,
				);
		},
		getStoredMediaDeletionCandidate(id: string) {
			const row = getDb().prepare(SQL_GET_MEDIA_FOR_DELETE).get(id) as
				| { local_path: string }
				| undefined;
			return row ? { localPath: row.local_path } : null;
		},
		markStoredMediaDeleted(id: string) {
			return getDb().prepare(SQL_SOFT_DELETE_MEDIA).run(id).changes > 0;
		},
		recordMediaAudit({
			actor,
			action,
			summary,
			targetId,
		}: {
			actor: Actor;
			action: string;
			summary: string;
			targetId: string;
		}) {
			recordAudit(getDb(), actor, action, summary, "content", targetId);
		},
	});

	return { sqliteRateLimitRepository, sqliteMediaRepository };
}

src/sqlite-runtime/audit-log.ts.source:
import { peekCmsConfig } from "../config";
import { buildAuditEntry } from "../persistence-commons";
import type { AstropressSqliteDatabaseLike } from "./utils";

// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
type AuditDetails = Record<string, unknown>;

function parseDetailsJson(value: string | null): AuditDetails | null {
	if (!value) return null;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	return JSON.parse(value) as Record<string, unknown>;
}

export interface AuditEventRecord {
	id: number;
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details: Record<string, unknown> | null;
	createdAt: string;
}

export interface RecordAuditEventInput {
	userEmail: string;
	action: string;
	resourceType: string;
	resourceId?: string | null;
	summary: string;
	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	details?: Record<string, unknown> | null;
}

export function recordAudit(
	db: AstropressSqliteDatabaseLike,
	actor: { email: string },
	action: string,
	summary: string,
	resourceType: string,
	resourceId: string,
): void {
	recordAuditEvent(db, {
		userEmail: actor.email,
		action,
		resourceType,
		resourceId,
		summary,
	});
}

export function recordAuditEvent(
	db: AstropressSqliteDatabaseLike,
	input: RecordAuditEventInput,
): void {
	const entry = buildAuditEntry({
		actor: { email: input.userEmail },
		action: input.action,
		resourceType: input.resourceType,
		resourceId: input.resourceId,
		summary: input.summary,
		details: input.details,
	});
	db.prepare(
		`INSERT INTO audit_events (user_email, action, resource_type, resource_id, summary, details)
     VALUES (?, ?, ?, ?, ?, ?)`,
	).run(
		entry.userEmail,
		entry.action,
		entry.resourceType,
		entry.resourceId,
		entry.summary,
		entry.details,
	);

	const retentionDays = peekCmsConfig()?.auditRetentionDays ?? 90;
	if (retentionDays > 0) {
		db.prepare(
			`DELETE FROM audit_events WHERE created_at < datetime('now', '-' || ? || ' days')`,
		).run(retentionDays);
	}
}

export function listAuditEvents(
	db: AstropressSqliteDatabaseLike,
	options: { limit?: number; offset?: number; resourceId?: string } = {},
): AuditEventRecord[] {
	const limit = options.limit ?? 50;
	const offset = options.offset ?? 0;

	// audit-boundary: opaque-passthrough -- raw rows from driver; mapped below at row-shape boundary
	let rows: unknown[];
	if (options.resourceId) {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         WHERE resource_id = ?
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(options.resourceId, limit, offset);
	} else {
		rows = db
			.prepare(
				`SELECT id, user_email, action, resource_type, resource_id, summary, details, created_at
         FROM audit_events
         ORDER BY created_at DESC
         LIMIT ? OFFSET ?`,
			)
			.all(limit, offset);
	}

	return (
		rows as Array<{
			id: number;
			user_email: string;
			action: string;
			resource_type: string;
			resource_id: string | null;
			summary: string;
			details: string | null;
			created_at: string;
		}>
	).map((row) => ({
		id: row.id,
		userEmail: row.user_email,
		action: row.action,
		resourceType: row.resource_type,
		resourceId: row.resource_id,
		summary: row.summary,
		details: parseDetailsJson(row.details),
		createdAt: row.created_at,
	}));
}

src/sqlite-runtime/content-helpers.ts.source:
import { mapPersistedOverrideRow as mapPersistedOverrideRowCommon } from "../persistence-commons";
import type { ContentRecord } from "../persistence-types";
import {
	type AstropressSqliteDatabaseLike,
	type PageRecord,
	parseIdList,
	serializeIdList,
} from "./utils";

export type ContentStatus = "draft" | "review" | "published" | "archived";

export interface ContentEntryRow {
	slug: string;
	legacy_url: string;
	title: string;
	kind: string;
	template_key: string;
	source_html_path: string;
	updated_at: string;
	body: string | null;
	summary: string | null;
	seo_title: string | null;
	meta_description: string | null;
	og_title: string | null;
	og_description: string | null;
	og_image: string | null;
}

export interface ContentOverrideRow {
	title: string;
	status: ContentStatus;
	scheduled_at: string | null;
	body: string | null;
	seo_title: string;
	meta_description: string;
	excerpt: string | null;
	og_title: string | null;
	og_description: string | null;
	og_image: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	metadata: string | null;
}

export interface RevisionRow {
	id: string;
	slug: string;
	title: string;
	status: ContentStatus;
	scheduled_at: string | null;
	body: string | null;
	seo_title: string;
	meta_description: string;
	excerpt: string | null;
	og_title: string | null;
	og_description: string | null;
	og_image: string | null;
	author_ids: string | null;
	category_ids: string | null;
	tag_ids: string | null;
	canonical_url_override: string | null;
	robots_directive: string | null;
	revision_note: string | null;
	source: "imported" | "reviewed";
	created_at: string;
	created_by: string | null;
}

export function mapContentEntryRow(row: ContentEntryRow): PageRecord {
	return {
		slug: row.slug,
		legacyUrl: row.legacy_url,
		title: row.title,
		templateKey: row.template_key,
		listingItems: [],
		paginationLinks: [],
		sourceHtmlPath: row.source_html_path,
		updatedAt: row.updated_at,
		body: row.body ?? "",
		summary: row.summary ?? "",
		seoTitle: row.seo_title ?? row.title,
		metaDescription: row.meta_description ?? row.summary ?? "",
		ogTitle: row.og_title ?? undefined,
		ogDescription: row.og_description ?? undefined,
		ogImage: row.og_image ?? undefined,
		kind: row.kind,
		status: "draft",
	};
}

export function pageRecordToContentRecord(pageRecord: PageRecord): ContentRecord {
	return {
		...pageRecord,
		status: pageRecord.status ?? "published",
		seoTitle: pageRecord.seoTitle ?? pageRecord.title,
		metaDescription: pageRecord.metaDescription ?? pageRecord.summary ?? "",
	};
}

export function mapPersistedOverrideRow(row: ContentOverrideRow | undefined) {
	const mapped = mapPersistedOverrideRowCommon(row ?? null);
	if (!mapped) return null;
	// Preserve the prior shape where `metadata` is always present (possibly undefined).
	return { ...mapped, metadata: mapped.metadata };
}

export function mapRevisionRow(row: RevisionRow) {
	return {
		id: row.id,
		slug: row.slug,
		title: row.title,
		status: row.status,
		scheduledAt: row.scheduled_at ?? undefined,
		body: row.body ?? undefined,
		authorIds: parseIdList(row.author_ids),
		categoryIds: parseIdList(row.category_ids),
		tagIds: parseIdList(row.tag_ids),
		seoTitle: row.seo_title,
		metaDescription: row.meta_description,
		excerpt: row.excerpt ?? undefined,
		ogTitle: row.og_title ?? undefined,
		ogDescription: row.og_description ?? undefined,
		ogImage: row.og_image ?? undefined,
		canonicalUrlOverride: row.canonical_url_override ?? undefined,
		robotsDirective: row.robots_directive ?? undefined,
		source: row.source,
		createdAt: row.created_at,
		revisionNote: row.revision_note ?? undefined,
		createdBy: row.created_by ?? undefined,
	};
}

/* ── SQL constants, RevisionInput, and baseline helpers ── */

export {
	buildBaselineOverrideParams,
	buildBaselineRevisionParams,
	ensureBaselineRevisionImpl,
	type RevisionInput,
	SQL_LIST_REVISIONS_FOR_SLUG,
} from "./content-sql";

import {
	type RevisionInput,
	SQL_INSERT_ENTRY,
	SQL_INSERT_REVISION_CONTENT,
	SQL_UPSERT_OVERRIDE,
} from "./content-sql";

export function queryCustomContentEntries(getDb: () => AstropressSqliteDatabaseLike) {
	return getDb()
		.prepare(
			`
        SELECT slug, legacy_url, title, kind, template_key, source_html_path, updated_at, body, summary,
               seo_title, meta_description, og_title, og_description, og_image
        FROM content_entries
        ORDER BY datetime(updated_at) DESC, slug ASC
      `,
		)
		.all() as ContentEntryRow[];
}

export function queryContentAssignmentIds(getDb: () => AstropressSqliteDatabaseLike, slug: string) {
	const db = getDb();
	const authorIds = (
		db
			.prepare("SELECT author_id FROM content_authors WHERE slug = ? ORDER BY author_id ASC")
			.all(slug) as Array<{ author_id: number }>
	).map((row) => row.author_id);
	const categoryIds = (
		db
			.prepare("SELECT category_id FROM content_categories WHERE slug = ? ORDER BY category_id ASC")
			.all(slug) as Array<{ category_id: number }>
	).map((row) => row.category_id);
	const tagIds = (
		db
			.prepare("SELECT tag_id FROM content_tags WHERE slug = ? ORDER BY tag_id ASC")
			.all(slug) as Array<{ tag_id: number }>
	).map((row) => row.tag_id);
	return { authorIds, categoryIds, tagIds };
}

export function replaceAssignments(
	getDb: () => AstropressSqliteDatabaseLike,
	slug: string,
	input: { authorIds?: number[]; categoryIds?: number[]; tagIds?: number[] },
) {
	const db = getDb();
	db.prepare("DELETE FROM content_authors WHERE slug = ?").run(slug);
	db.prepare("DELETE FROM content_categories WHERE slug = ?").run(slug);
	db.prepare("DELETE FROM content_tags WHERE slug = ?").run(slug);

	for (const authorId of input.authorIds ?? []) {
		db.prepare("INSERT OR IGNORE INTO content_authors (slug, author_id) VALUES (?, ?)").run(
			slug,
			authorId,
		);
	}
	for (const categoryId of input.categoryIds ?? []) {
		db.prepare("INSERT OR IGNORE INTO content_categories (slug, category_id) VALUES (?, ?)").run(
			slug,
			categoryId,
		);
	}
	for (const tagId of input.tagIds ?? []) {
		db.prepare("INSERT OR IGNORE INTO content_tags (slug, tag_id) VALUES (?, ?)").run(slug, tagId);
	}
}

export function upsertOverride(
	getDb: () => AstropressSqliteDatabaseLike,
	slug: string,
	override: {
		title: string;
		status: string;
		body?: string | null;
		seoTitle: string;
		metaDescription: string;
		excerpt?: string | null;
		ogTitle?: string | null;
		ogDescription?: string | null;
		ogImage?: string | null;
		scheduledAt?: string | null;
		canonicalUrlOverride?: string | null;
		robotsDirective?: string | null;
		// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
		metadata?: Record<string, unknown> | null;
	},
	actor: { email: string },
) {
	getDb()
		.prepare(SQL_UPSERT_OVERRIDE)
		.run(
			slug,
			override.title,
			override.status,
			override.body ?? null,
			override.seoTitle,
			override.metaDescription,
			override.excerpt ?? null,
			override.ogTitle ?? null,
			override.ogDescription ?? null,
			override.ogImage ?? null,
			override.scheduledAt ?? null,
			override.canonicalUrlOverride ?? null,
			override.robotsDirective ?? null,
			override.metadata ? JSON.stringify(override.metadata) : null,
			actor.email,
		);
}

export function insertRevision(
	getDb: () => AstropressSqliteDatabaseLike,
	randomId: () => string,
	slug: string,
	revision: RevisionInput,
	actor: { email: string },
) {
	getDb()
		.prepare(SQL_INSERT_REVISION_CONTENT)
		.run(
			`revision-${randomId()}`,
			slug,
			revision.title,
			revision.status,
			revision.scheduledAt ?? null,
			revision.body ?? null,
			revision.seoTitle,
			revision.metaDescription,
			revision.excerpt ?? null,
			revision.ogTitle ?? null,
			revision.ogDescription ?? null,
			revision.ogImage ?? null,
			serializeIdList(revision.authorIds),
			serializeIdList(revision.categoryIds),
			serializeIdList(revision.tagIds),
			revision.canonicalUrlOverride ?? null,
			revision.robotsDirective ?? null,
			revision.revisionNote ?? null,
			actor.email,
		);
}

export function tryInsertContentEntry(
	getDb: () => AstropressSqliteDatabaseLike,
	entry: {
		slug: string;
		legacyUrl: string;
		title: string;
		body: string;
		summary: string;
		seoTitle: string;
		metaDescription: string;
		ogTitle?: string | null;
		ogDescription?: string | null;
		ogImage?: string | null;
	},
): boolean {
	try {
		getDb()
			.prepare(SQL_INSERT_ENTRY)
			.run(
				entry.slug,
				entry.legacyUrl,
				entry.title,
				`runtime://content/${entry.slug}`,
				entry.body,
				entry.summary,
				entry.seoTitle,
				entry.metaDescription,
				entry.ogTitle ?? null,
				entry.ogDescription ?? null,
				entry.ogImage ?? null,
			);
		return true;
	} catch {
		return false;
	}
}

