import { createAstropressContentRepository } from "../content-repository-factory";
import { recordAudit } from "./audit-log";
import {
	ensureBaselineRevisionImpl,
	insertRevision,
	mapContentEntryRow,
	mapPersistedOverrideRow,
	mapRevisionRow,
	pageRecordToContentRecord,
	queryContentAssignmentIds,
	queryCustomContentEntries,
	type RevisionRow,
	replaceAssignments,
	SQL_LIST_REVISIONS_FOR_SLUG,
	tryInsertContentEntry,
	upsertOverride,
} from "./content-helpers";
import { createSqliteSubmissionStore } from "./content-submissions";
import {
	type AstropressSqliteDatabaseLike,
	getSeedPageRecords,
	normalizeContentStatus,
	normalizePath,
	type PageRecord,
	slugifyTerm,
} from "./utils";

export function createSqliteContentStore(
	getDb: () => AstropressSqliteDatabaseLike,
	randomId: () => string,
) {
	function getCustomContentEntries() {
		return queryCustomContentEntries(getDb);
	}

	function getAllContentRecords() {
		return [
			...getSeedPageRecords(),
			...getCustomContentEntries().map((row) => mapContentEntryRow(row)),
		];
	}

	function findPageRecord(slug: string) {
		return (
			getAllContentRecords().find(
				(entry) => entry.slug === slug || entry.legacyUrl === `/${slug}`,
			) ?? null
		);
	}

	function getPersistedContentOverride(slug: string) {
		const row = getDb()
			.prepare(
				`
          SELECT title, status, body, seo_title, meta_description, excerpt, og_title, og_description, og_image,
                 scheduled_at, canonical_url_override, robots_directive, metadata
          FROM content_overrides
          WHERE slug = ?
          LIMIT 1
        `,
			)
			.get(slug) as Parameters<typeof mapPersistedOverrideRow>[0];

		return mapPersistedOverrideRow(row);
	}

	function ensureBaselineRevision(pageRecord: PageRecord) {
		ensureBaselineRevisionImpl(getDb, randomId, pageRecord);
	}

	const sqliteContentRepository = createAstropressContentRepository({
		normalizePath,
		slugifyTerm,
		normalizeContentStatus,
		findContentRecord(slug) {
			const record = findPageRecord(slug);
			return record ? pageRecordToContentRecord(record) : null;
		},
		listContentRecords() {
			return getAllContentRecords().map((record) => pageRecordToContentRecord(record));
		},
		getPersistedOverride: getPersistedContentOverride,
		getContentAssignments(slug) {
			return queryContentAssignmentIds(getDb, slug);
		},
		ensureBaselineRevision(record) {
			ensureBaselineRevision(record as PageRecord);
		},
		listPersistedRevisions(slug) {
			const rows = getDb().prepare(SQL_LIST_REVISIONS_FOR_SLUG).all(slug) as RevisionRow[];
			return rows.map(mapRevisionRow);
		},
		getPersistedRevision(slug, revisionId) {
			return (
				this.listPersistedRevisions(slug).find((revision) => revision.id === revisionId) ?? null
			);
		},
		upsertContentOverride(slug, override, actor) {
			upsertOverride(getDb, slug, override, actor);
		},
		replaceContentAssignments(slug, assignments) {
			replaceAssignments(getDb, slug, assignments);
		},
		insertReviewedRevision(slug, revision, actor) {
			insertRevision(getDb, randomId, slug, revision, actor);
		},
		insertContentEntry(entry) {
			return tryInsertContentEntry(getDb, entry);
		},
		recordContentAudit({ actor, action, summary, targetId }) {
			recordAudit(getDb(), actor, action, summary, "content", targetId);
		},
	});
	const { sqliteSubmissionRepository, sqliteSchedulingRepository } =
		createSqliteSubmissionStore(getDb);
	return {
		sqliteContentRepository,
		sqliteSubmissionRepository,
		sqliteSchedulingRepository,
	};
}

src/sqlite-runtime/integrations.ts.source:
/**
 * Repository over the connected_integrations + integration_secrets
 * tables. Two halves with deliberately separated surfaces:
 *
 *   - Status surface (findStatus, listStatuses, updateStatus,
 *     disconnect): never reads from `integration_secrets`. Sidebar
 *     status badges and dashboards must call only these methods, so
 *     ciphertext stays off the read path.
 *
 *   - Secret surface (findSecret, upsertSecret): explicit
 *     `rootSecrets` argument gates every plaintext access. After a
 *     successful previous-key decrypt, opportunistically reseals
 *     under current with a guarded UPDATE so a concurrent admin
 *     write isn't clobbered.
 *
 * Design doc: tooling/docs/phase-2-secret-store-design.md
 */

import type {
	RootSecretCandidates,
	SealedSecret,
	SecretContext,
} from "../integration-secret-envelope";
import { openIntegrationSecret, sealIntegrationSecret } from "../integration-secret-envelope";
import type { AstropressSqliteDatabaseLike } from "./utils";

export type IntegrationStatusValue = "connected" | "error" | "paused";

export interface IntegrationStatusRow {
	domain: string;
	provider: string;
	status: IntegrationStatusValue;
	configJson: string;
	connectedAt: string;
	lastCheckAt: string | null;
	lastError: string | null;
}

export interface ConnectIntegrationInput<
	TFields extends Record<string, string> = Record<string, string>,
> {
	domain: string;
	provider: string;
	configJson: string;
	secretFields: TFields;
	now: string; // ISO 8601
}

export interface IntegrationsRepositoryOptions {
	getDb: () => AstropressSqliteDatabaseLike;
	now: () => string;
}

interface RawStatusRow {
	domain: string;
	provider: string;
	status: string;
	config_json: string;
	connected_at: string;
	last_check_at: string | null;
	last_error: string | null;
}

interface RawSecretRow {
	domain: string;
	provider: string;
	envelope_v: number;
	kid: string;
	wrap_salt: string;
	wrap_iv: string;
	dek_wrap: string;
	data_iv: string;
	ciphertext: string;
	rotated_at: string;
}

const SQL_FIND_STATUS = `
  SELECT domain, provider, status, config_json, connected_at,
         last_check_at, last_error
    FROM connected_integrations
   WHERE domain = ? AND provider = ?`;

const SQL_LIST_STATUSES = `
  SELECT domain, provider, status, config_json, connected_at,
         last_check_at, last_error
    FROM connected_integrations
   ORDER BY domain, provider`;

const SQL_UPSERT_STATUS = `
  INSERT INTO connected_integrations (
    domain, provider, status, config_json, connected_at,
    last_check_at, last_error
  ) VALUES (?, ?, ?, ?, ?, NULL, NULL)
  ON CONFLICT(domain, provider) DO UPDATE SET
    status = excluded.status,
    config_json = excluded.config_json,
    connected_at = excluded.connected_at,
    last_check_at = NULL,
    last_error = NULL`;

const SQL_UPDATE_STATUS = `
  UPDATE connected_integrations
     SET status = ?, last_check_at = ?, last_error = ?
   WHERE domain = ? AND provider = ?`;

const SQL_DISCONNECT = `
  DELETE FROM connected_integrations
   WHERE domain = ? AND provider = ?`;

const SQL_FIND_SECRET = `
  SELECT domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
         dek_wrap, data_iv, ciphertext, rotated_at
    FROM integration_secrets
   WHERE domain = ? AND provider = ?`;

const SQL_UPSERT_SECRET = `
  INSERT INTO integration_secrets (
    domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
    dek_wrap, data_iv, ciphertext, rotated_at
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  ON CONFLICT(domain, provider) DO UPDATE SET
    envelope_v = excluded.envelope_v,
    kid = excluded.kid,
    wrap_salt = excluded.wrap_salt,
    wrap_iv = excluded.wrap_iv,
    dek_wrap = excluded.dek_wrap,
    data_iv = excluded.data_iv,
    ciphertext = excluded.ciphertext,
    rotated_at = excluded.rotated_at`;

/**
 * Update only when the row still matches the ciphertext we just
 * decrypted. If a concurrent reseal raced ahead, our update is a
 * no-op and the running record stays consistent.
 */
const SQL_RESEAL_GUARDED = `
  UPDATE integration_secrets
     SET envelope_v = ?, kid = ?, wrap_salt = ?, wrap_iv = ?,
         dek_wrap = ?, data_iv = ?, ciphertext = ?, rotated_at = ?
   WHERE domain = ? AND provider = ?
     AND ciphertext = ?
     AND kid = ?`;

const SQL_LIST_PREVIOUS_SECRETS = `
  SELECT domain, provider, envelope_v, kid, wrap_salt, wrap_iv,
         dek_wrap, data_iv, ciphertext, rotated_at
    FROM integration_secrets
   WHERE kid = 'previous'`;

function rowToStatus(row: RawStatusRow): IntegrationStatusRow {
	return {
		domain: row.domain,
		provider: row.provider,
		status: row.status as IntegrationStatusValue,
		configJson: row.config_json,
		connectedAt: row.connected_at,
		lastCheckAt: row.last_check_at,
		lastError: row.last_error,
	};
}

function rowToSealed(row: RawSecretRow): SealedSecret {
	return {
		v: row.envelope_v as 1,
		kid: row.kid as "current" | "previous",
		wrap_salt: row.wrap_salt,
		wrap_iv: row.wrap_iv,
		dek_wrap: row.dek_wrap,
		data_iv: row.data_iv,
		ciphertext: row.ciphertext,
	};
}

export interface IntegrationsRepository {
	findStatus(domain: string, provider: string): IntegrationStatusRow | undefined;
	listStatuses(): IntegrationStatusRow[];
	updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): boolean;
	disconnect(domain: string, provider: string): boolean;

	connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void>;

	findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined>;

	listPreviousKidContexts(): SecretContext[];
}

export function createIntegrationsRepository(
	options: IntegrationsRepositoryOptions,
): IntegrationsRepository {
	const { getDb, now } = options;

	function findStatus(domain: string, provider: string): IntegrationStatusRow | undefined {
		const row = getDb().prepare(SQL_FIND_STATUS).get(domain, provider) as RawStatusRow | undefined;
		return row ? rowToStatus(row) : undefined;
	}

	function listStatuses(): IntegrationStatusRow[] {
		const rows = getDb().prepare(SQL_LIST_STATUSES).all() as RawStatusRow[];
		return rows.map(rowToStatus);
	}

	function updateStatus(input: {
		domain: string;
		provider: string;
		status: IntegrationStatusValue;
		lastCheckAt: string;
		lastError?: string | null;
	}): boolean {
		const result = getDb()
			.prepare(SQL_UPDATE_STATUS)
			.run(input.status, input.lastCheckAt, input.lastError ?? null, input.domain, input.provider);
		return Number(result.changes ?? 0) > 0;
	}

	function disconnect(domain: string, provider: string): boolean {
		const result = getDb().prepare(SQL_DISCONNECT).run(domain, provider);
		return Number(result.changes ?? 0) > 0;
	}

	async function connect<TFields extends Record<string, string> = Record<string, string>>(
		input: ConnectIntegrationInput<TFields>,
		rootSecret: string,
	): Promise<void> {
		const sealed = await sealIntegrationSecret(
			input.secretFields,
			{ domain: input.domain, provider: input.provider },
			rootSecret,
		);
		const db = getDb();
		db.prepare(SQL_UPSERT_STATUS).run(
			input.domain,
			input.provider,
			"connected",
			input.configJson,
			input.now,
		);
		db.prepare(SQL_UPSERT_SECRET).run(
			input.domain,
			input.provider,
			sealed.v,
			sealed.kid,
			sealed.wrap_salt,
			sealed.wrap_iv,
			sealed.dek_wrap,
			sealed.data_iv,
			sealed.ciphertext,
			input.now,
		);
	}

	async function findSecret<TFields extends Record<string, string> = Record<string, string>>(
		domain: string,
		provider: string,
		rootSecrets: RootSecretCandidates,
	): Promise<TFields | undefined> {
		const row = getDb().prepare(SQL_FIND_SECRET).get(domain, provider) as RawSecretRow | undefined;
		if (!row) return undefined;
		const sealed = rowToSealed(row);
		const ctx: SecretContext = { domain, provider };
		const opened = await openIntegrationSecret<TFields>(sealed, ctx, rootSecrets);
		// Reseal-on-read: when we just decrypted with the previous key, push
		// the record forward under current in a guarded UPDATE.
		if (opened.usedKid === "previous" && rootSecrets.previous) {
			const resealed = await sealIntegrationSecret(opened.fields, ctx, rootSecrets.current);
			getDb()
				.prepare(SQL_RESEAL_GUARDED)
				.run(
					resealed.v,
					resealed.kid,
					resealed.wrap_salt,
					resealed.wrap_iv,
					resealed.dek_wrap,
					resealed.data_iv,
					resealed.ciphertext,
					now(),
					domain,
					provider,
					row.ciphertext,
					row.kid,
				);
		}
		return opened.fields;
	}

	function listPreviousKidContexts(): SecretContext[] {
		const rows = getDb().prepare(SQL_LIST_PREVIOUS_SECRETS).all() as RawSecretRow[];
		return rows.map((row) => ({
			domain: row.domain,
			provider: row.provider,
		}));
	}

	return {
		findStatus,
		listStatuses,
		updateStatus,
		disconnect,
		connect,
		findSecret,
		listPreviousKidContexts,
	};
}

src/sqlite-runtime/purge.ts.source:
import type { UserPurgeResult } from "../admin-action-user-purge";
import type { AstropressSqliteDatabaseLike } from "./utils";

export function createSqlitePurgeOps(getDb: () => AstropressSqliteDatabaseLike) {
	return {
		purgeUserData(email: string, options: { deleteAccount?: boolean } = {}): UserPurgeResult {
			const db = getDb();

			const userRow = db.prepare("SELECT id FROM admin_users WHERE email = ? LIMIT 1").get(email) as
				| { id: number }
				| undefined;

			// Revoke sessions (delete all sessions for this user)
			let revokedSessions = 0;
			if (userRow) {
				const result = db.prepare("DELETE FROM admin_sessions WHERE user_id = ?").run(userRow.id);
				revokedSessions = result.changes as number;
			}

			// Anonymise audit events
			const auditResult = db
				.prepare("UPDATE audit_events SET user_email = '[deleted]' WHERE user_email = ?")
				.run(email);
			const anonymisedAuditEvents = auditResult.changes as number;

			// Delete comments
			const commentsResult = db.prepare("DELETE FROM comments WHERE email = ?").run(email);
			const deletedComments = commentsResult.changes as number;

			// Delete contact submissions
			const submissionsResult = db
				.prepare("DELETE FROM contact_submissions WHERE email = ?")
				.run(email);
			const deletedContactSubmissions = submissionsResult.changes as number;

			// Suspend or delete the admin user
			let adminUserAction: UserPurgeResult["adminUserAction"];
			if (!userRow) {
				adminUserAction = "not_found";
			} else if (options.deleteAccount) {
				db.prepare("DELETE FROM admin_users WHERE email = ?").run(email);
				adminUserAction = "deleted";
			} else {
				db.prepare("UPDATE admin_users SET active = 0 WHERE email = ?").run(email);
				adminUserAction = "suspended";
			}

			return {
				ok: true,
				email,
				revokedSessions,
				anonymisedAuditEvents,
				deletedComments,
				deletedContactSubmissions,
				adminUserAction,
			};
		},
	};
}

src/sqlite-runtime/routes.ts.source:
import { createAstropressCmsRouteRegistry } from "../cms-route-registry-factory";
import { createAstropressCmsRegistryModule } from "../host-runtime-factories";
import type { Actor } from "../persistence-types";
import { recordAudit } from "./audit-log";
import {
	type AppendArchiveRevisionInput,
	type AppendStructuredRevisionInput,
	type ArchiveRouteRow,
	type InsertStructuredInput,
	mapArchiveRow,
	mapStructuredPageRow,
	type PersistArchiveInput,
	type PersistStructuredInput,
	SQL_FIND_ARCHIVE_FOR_UPDATE,
	SQL_FIND_STRUCTURED_FOR_UPDATE,
	SQL_FIND_SYSTEM_FOR_UPDATE,
	SQL_GET_ARCHIVE,
	SQL_INSERT_ARCHIVE_REVISION,
	SQL_INSERT_REVISION,
	SQL_INSERT_ROUTE_GROUP,
	SQL_INSERT_ROUTE_VARIANT,
	SQL_IS_PATH_TAKEN,
	SQL_LIST_ARCHIVES,
	SQL_LIST_STRUCTURED,
	SQL_LIST_SYSTEM,
	SQL_PERSIST_ARCHIVE,
	SQL_PERSIST_STRUCTURED,
	SQL_PERSIST_SYSTEM,
	type StructuredPageRow,
	type SystemRouteRecord,
	type SystemRouteRow,
} from "./routes-helpers";
import {
	type AstropressSqliteDatabaseLike,
	localeFromPath,
	normalizeSystemRoutePath,
	parseSystemSettings,
} from "./utils";

function querySystemRoutes(getDb: () => AstropressSqliteDatabaseLike): SystemRouteRecord[] {
	const rows = getDb().prepare(SQL_LIST_SYSTEM).all() as SystemRouteRow[];
	return rows.map((row) => ({
		path: row.path,
		title: row.title,
		summary: row.summary ?? undefined,
		bodyHtml: row.body_html ?? undefined,
		settings: parseSystemSettings(row.settings_json),
		updatedAt: row.updated_at ?? undefined,
		renderStrategy: row.render_strategy,
	}));
}

function queryStructuredPageRoutes(getDb: () => AstropressSqliteDatabaseLike) {
	const rows = getDb().prepare(SQL_LIST_STRUCTURED).all() as StructuredPageRow[];
	return rows.map(mapStructuredPageRow).filter(Boolean) as ReturnType<
		typeof mapStructuredPageRow
	>[];
}

export function createSqliteRoutesStore(
	getDb: () => AstropressSqliteDatabaseLike,
	randomId: () => string,
) {
	function listSystemRoutes() {
		return querySystemRoutes(getDb);
	}

	function getSystemRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		return listSystemRoutes().find((route) => route.path === normalizedPath) ?? null;
	}

	function listStructuredPageRoutes() {
		return queryStructuredPageRoutes(getDb).filter((r): r is NonNullable<typeof r> => r !== null);
	}

	function getStructuredPageRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		return listStructuredPageRoutes().find((route) => route.path === normalizedPath) ?? null;
	}

	function getArchiveRoute(pathname: string) {
		const normalizedPath = normalizeSystemRoutePath(pathname);
		const row = getDb().prepare(SQL_GET_ARCHIVE).get(normalizedPath) as ArchiveRouteRow | undefined;
		if (!row) return null;
		return mapArchiveRow(row);
	}

	function listArchiveRoutes() {
		const rows = getDb().prepare(SQL_LIST_ARCHIVES).all() as ArchiveRouteRow[];
		return rows.map(mapArchiveRow);
	}

	const sqliteCmsRouteRegistry = createAstropressCmsRouteRegistry({
		normalizePath: normalizeSystemRoutePath,
		localeFromPath,
		listSystemRoutes,
		getSystemRoute,
		listStructuredPageRoutes,
		getStructuredPageRoute,
		getArchiveRoute,
		listArchiveRoutes,
		findSystemRouteForUpdate(pathname) {
			const row = getDb().prepare(SQL_FIND_SYSTEM_FOR_UPDATE).get(pathname) as
				| { id: string; render_strategy: SystemRouteRecord["renderStrategy"] }
				| undefined;
			return row ? { id: row.id, renderStrategy: row.render_strategy } : null;
		},
		persistSystemRoute({
			routeId,
			title,
			summary,
			bodyHtml,
			settingsJson,
			actor,
		}: {
			routeId: string;
			title: string;
			summary: string;
			bodyHtml: string;
			settingsJson: string;
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_PERSIST_SYSTEM)
				.run(title, summary, bodyHtml, settingsJson, title, summary ?? title, actor.email, routeId);
		},
		appendSystemRouteRevision({
			routeId,
			pathname,
			locale,
			title,
			summary,
			bodyHtml,
			settings,
			renderStrategy,
			revisionNote,
			actor,
		}: {
			routeId: string;
			pathname: string;
			locale: string;
			title: string;
			summary: string;
			bodyHtml: string;
			// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
			settings: Record<string, unknown> | null;
			renderStrategy: string;
			revisionNote: string;
			actor: Actor;
		}) {
			getDb()
				.prepare(SQL_INSERT_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					locale,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						bodyHtml,
						settings: settings ?? null,
						renderStrategy,
					}),
					revisionNote,
					actor.email,
				);
		},
		isRoutePathTaken(pathname) {
			return Boolean(getDb().prepare(SQL_IS_PATH_TAKEN).get(pathname));
		},
		findStructuredRouteForUpdate(pathname) {
			return (
				(getDb().prepare(SQL_FIND_STRUCTURED_FOR_UPDATE).get(pathname) as
					| { id: string }
					| undefined) ?? null
			);
		},
		insertStructuredRoute({
			pathname,
			locale,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			actor,
		}: InsertStructuredInput) {
			const groupId = `route-group:${randomId()}`;
			const variantId = `route-variant:${randomId()}`;
			getDb().prepare(SQL_INSERT_ROUTE_GROUP).run(groupId, locale, pathname);
			getDb()
				.prepare(SQL_INSERT_ROUTE_VARIANT)
				.run(
					variantId,
					groupId,
					locale,
					pathname,
					title,
					summary,
					sections ? JSON.stringify(sections) : null,
					JSON.stringify({ templateKey, alternateLinks }),
					seoTitle,
					metaDescription,
					ogImage,
					canonicalUrlOverride,
					robotsDirective,
					actor.email,
				);
		},
		persistStructuredRoute({
			routeId,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			actor,
		}: PersistStructuredInput) {
			getDb()
				.prepare(SQL_PERSIST_STRUCTURED)
				.run(
					title,
					summary,
					seoTitle,
					metaDescription,
					canonicalUrlOverride,
					robotsDirective,
					ogImage,
					sections ? JSON.stringify(sections) : null,
					JSON.stringify({ templateKey, alternateLinks }),
					actor.email,
					routeId,
				);
		},
		appendStructuredRouteRevision({
			routeId,
			pathname,
			locale,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			ogImage,
			templateKey,
			alternateLinks,
			sections,
			revisionNote,
			actor,
		}: AppendStructuredRevisionInput) {
			getDb()
				.prepare(SQL_INSERT_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					locale,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						seoTitle,
						metaDescription,
						canonicalUrlOverride,
						robotsDirective,
						ogImage,
						templateKey,
						alternateLinks,
						sections,
					}),
					revisionNote,
					actor.email,
				);
		},
		findArchiveRouteForUpdate(pathname) {
			return (
				(getDb().prepare(SQL_FIND_ARCHIVE_FOR_UPDATE).get(pathname) as
					| { id: string }
					| undefined) ?? null
			);
		},
		persistArchiveRoute({
			routeId,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			actor,
		}: PersistArchiveInput) {
			getDb()
				.prepare(SQL_PERSIST_ARCHIVE)
				.run(
					title,
					summary,
					seoTitle,
					metaDescription,
					canonicalUrlOverride,
					robotsDirective,
					actor.email,
					routeId,
				);
		},
		appendArchiveRouteRevision({
			routeId,
			pathname,
			title,
			summary,
			seoTitle,
			metaDescription,
			canonicalUrlOverride,
			robotsDirective,
			revisionNote,
			actor,
		}: AppendArchiveRevisionInput) {
			getDb()
				.prepare(SQL_INSERT_ARCHIVE_REVISION)
				.run(
					`revision:${routeId}:${randomId()}`,
					routeId,
					pathname,
					JSON.stringify({
						path: pathname,
						title,
						summary,
						seoTitle,
						metaDescription,
						canonicalUrlOverride,
						robotsDirective,
					}),
					revisionNote,
					actor.email,
				);
		},
		recordRouteAudit({
			actor,
			action,
			summary,
			targetId,
		}: {
			actor: Actor;
			action: string;
			summary: string;
			targetId: string;
		}) {
			recordAudit(getDb(), actor, action, summary, "content", targetId);
		},
	});

	const sqliteCmsRegistryModule = createAstropressCmsRegistryModule({
		listSystemRoutes: sqliteCmsRouteRegistry.listSystemRoutes,
		getSystemRoute: sqliteCmsRouteRegistry.getSystemRoute,
		saveSystemRoute: sqliteCmsRouteRegistry.saveSystemRoute,
		listStructuredPageRoutes: sqliteCmsRouteRegistry.listStructuredPageRoutes,
		getStructuredPageRoute: sqliteCmsRouteRegistry.getStructuredPageRoute,
		saveStructuredPageRoute: sqliteCmsRouteRegistry.saveStructuredPageRoute,
		createStructuredPageRoute: sqliteCmsRouteRegistry.createStructuredPageRoute,
		getArchiveRoute: sqliteCmsRouteRegistry.getArchiveRoute,
		listArchiveRoutes: sqliteCmsRouteRegistry.listArchiveRoutes,
		saveArchiveRoute: sqliteCmsRouteRegistry.saveArchiveRoute,
	});

	return { sqliteCmsRouteRegistry, sqliteCmsRegistryModule };
}

