import { randomBytes } from "node:crypto";
import { createMlDsaKeyPair, secretKeyToBase64, signMlDsaMessage } from "../crypto-primitives";
import type { WebhookEvent, WebhookRecord, WebhookStore } from "../platform-contracts";
import { createLogger } from "../runtime-logger";
import type { AstropressSqliteDatabaseLike } from "./utils";

const logger = createLogger("Webhook");

// The historical secret_hash column stores the ML-DSA-65 private signing key
// in base64 form. The verification key is returned once at creation time.

interface WebhookRow {
	id: string;
	url: string;
	events: string;
	secret_hash: string; // stores the ML-DSA secret key (field naming is historical)
	active: number;
	created_at: string;
	last_fired_at: string | null;
}

function rowToRecord(row: WebhookRow): WebhookRecord {
	return {
		id: row.id,
		url: row.url,
		events: JSON.parse(row.events) as WebhookEvent[],
		active: row.active === 1,
		createdAt: row.created_at,
		lastFiredAt: row.last_fired_at ?? null,
	};
}

export function createWebhookStore(
	db: AstropressSqliteDatabaseLike,
	fetchImpl: typeof fetch = fetch,
): WebhookStore {
	return {
		async list() {
			const rows = db
				.prepare(
					"SELECT id, url, events, secret_hash, active, created_at, last_fired_at FROM webhooks WHERE deleted_at IS NULL ORDER BY created_at DESC",
				)
				.all() as WebhookRow[];
			return rows.map(rowToRecord);
		},

		async create({ url, events }) {
			const id = `wh_${randomBytes(12).toString("hex")}`;
			const keyPair = createMlDsaKeyPair(id, randomBytes(32));
			const now = new Date().toISOString();

			db.prepare(
				"INSERT INTO webhooks (id, url, events, secret_hash, active, created_at) VALUES (?, ?, ?, ?, 1, ?)",
			).run(id, url, JSON.stringify(events), secretKeyToBase64(keyPair.secretKey), now);

			const record: WebhookRecord = {
				id,
				url,
				events,
				active: true,
				createdAt: now,
				lastFiredAt: null,
			};

			return { record, verification: keyPair.verification };
		},

		async delete(id) {
			const now = new Date().toISOString();
			db.prepare("UPDATE webhooks SET deleted_at = ?, active = 0 WHERE id = ?").run(now, id);
		},

		async dispatch(event, payload) {
			const rows = db
				.prepare(
					"SELECT id, url, events, secret_hash, active, created_at, last_fired_at FROM webhooks WHERE deleted_at IS NULL AND active = 1",
				)
				.all() as WebhookRow[];

			const subscribers = rows.filter((row) => {
				const events = JSON.parse(row.events) as WebhookEvent[];
				return events.includes(event);
			});

			if (subscribers.length === 0) return;

			const bodyText = JSON.stringify({
				event,
				payload,
				timestamp: new Date().toISOString(),
			});
			const now = new Date().toISOString();

			await Promise.allSettled(
				subscribers.map(async (row) => {
					const signature = signMlDsaMessage(bodyText, row.secret_hash);
					try {
						await fetchImpl(
							new Request(row.url, {
								method: "POST",
								headers: {
									"Content-Type": "application/json",
									"X-Astropress-Event": event,
									"X-Astropress-Signature": signature,
									"X-Astropress-Signature-Alg": "ML-DSA-65",
									"X-Astropress-Key-Id": row.id,
								},
								body: bodyText,
							}),
						);
					} catch (err) {
						logger.error(`Failed to dispatch ${event} to ${row.url}`, {
							error: err,
						});
						return;
					}

					db.prepare("UPDATE webhooks SET last_fired_at = ? WHERE id = ?").run(now, row.id);
				}),
			);
		},
	};
}

src/sqlite-seed-helpers.ts.source:
import { hashPasswordArgon2id } from "./crypto-primitives";
import type { SqliteDatabaseLike } from "./sqlite-bootstrap.js";
import { getTableColumns } from "./sqlite-schema-compat.js";

export function hashPasswordSync(password: string, iterations = 2) {
	return hashPasswordArgon2id(password, { iterations });
}

export function guessMimeType(pathname: string) {
	const lower = pathname.toLowerCase();
	if (lower.endsWith(".png")) return "image/png";
	if (lower.endsWith(".webp")) return "image/webp";
	if (lower.endsWith(".gif")) return "image/gif";
	return "image/jpeg";
}

export function toSqlLiteral(value: unknown): string {
	if (value === null || value === undefined) return "NULL";
	if (typeof value === "number" || typeof value === "bigint") return String(value);
	if (typeof value === "boolean") return value ? "1" : "0";
	if (value instanceof Uint8Array) return `X'${Buffer.from(value).toString("hex")}'`;
	return `'${String(value).replaceAll("'", "''")}'`;
}

export function buildTableImportStatements(db: SqliteDatabaseLike, table: string) {
	const columns = getTableColumns(db, table);
	if (columns.length === 0) return [] as string[];

	// audit-boundary: opaque-passthrough -- SQL row-shape mirror; columns narrowed at row-mapper boundary
	const rows = db.prepare(`SELECT * FROM ${table}`).all() as Record<string, unknown>[];
	const statements = [`DELETE FROM ${table};`];
	for (const row of rows) {
		const serializedValues = columns.map((column) => toSqlLiteral(row[column]));
		statements.push(
			`INSERT INTO ${table} (${columns.join(", ")}) VALUES (${serializedValues.join(", ")});`,
		);
	}
	return statements;
}

export function buildTableImportSql(db: SqliteDatabaseLike, table: string) {
	return buildTableImportStatements(db, table).join("\n");
}

src/submission-repository-factory.ts.source:
import type {
	ContactSubmission,
	SubmissionRepository,
	TestimonialSource,
	TestimonialStatus,
	TestimonialSubmission,
	TestimonialSubmissionInput,
} from "./persistence-types";

export interface AstropressSubmissionRepositoryInput {
	getContactSubmissions: SubmissionRepository["getContactSubmissions"];
	insertContactSubmission(submission: ContactSubmission): void;
	getTestimonials(status?: TestimonialStatus): TestimonialSubmission[];
	insertTestimonial(submission: TestimonialSubmission): void;
	updateTestimonialStatus(
		id: string,
		status: TestimonialStatus,
	): { ok: true } | { ok: false; error: string };
}

export function createAstropressSubmissionRepository(
	input: AstropressSubmissionRepositoryInput,
): SubmissionRepository {
	return {
		getContactSubmissions: (...args) => input.getContactSubmissions(...args),
		submitContact(rawInput) {
			const submission: ContactSubmission = {
				id: `contact-${crypto.randomUUID()}`,
				name: rawInput.name,
				email: rawInput.email,
				message: rawInput.message,
				submittedAt: rawInput.submittedAt,
			};

			input.insertContactSubmission(submission);
			return { ok: true as const, submission };
		},
		getTestimonials: (...args) => input.getTestimonials(...args),
		submitTestimonial(rawInput: TestimonialSubmissionInput) {
			const id = `testimonial-${crypto.randomUUID()}`;
			const submission: TestimonialSubmission = {
				id,
				name: rawInput.name,
				email: rawInput.email,
				company: rawInput.company,
				role: rawInput.role,
				beforeState: rawInput.beforeState,
				transformation: rawInput.transformation,
				specificResult: rawInput.specificResult,
				consentToPublish: rawInput.consentToPublish,
				status: "pending",
				source: rawInput.source as TestimonialSource,
				submittedAt: rawInput.submittedAt,
			};
			input.insertTestimonial(submission);
			return { ok: true as const, id };
		},
		moderateTestimonial(id: string, status: TestimonialStatus) {
			return input.updateTestimonialStatus(id, status);
		},
	};
}

src/sync/git.ts.source:
import { constants, copyFile, mkdir, readdir, rm, stat } from "node:fs/promises";
import { dirname, join, resolve } from "node:path";
import type { GitSyncAdapter } from "../platform-contracts";
import { checkpointSqliteWal } from "../sqlite-bootstrap-helpers";
import { runIntegrityCheck } from "../sqlite-integrity";
import { defaultEntries } from "./git-data";

export interface AstropressGitSyncAdapterOptions {
	projectDir: string;
	include?: string[];
	logger?: { info: (msg: string) => void; warn: (msg: string) => void };
}

async function pathExists(pathname: string) {
	try {
		await stat(pathname);
		return true;
	} catch {
		return false;
	}
}

async function copyFileWithReflink(src: string, dest: string): Promise<boolean> {
	try {
		await copyFile(src, dest, constants.COPYFILE_FICLONE);
		return true;
	} catch (err: unknown) {
		const code = (err as NodeJS.ErrnoException).code;
		if (code === "ENOTSUP" || code === "EOPNOTSUPP" || code === "EXDEV") {
			await copyFile(src, dest);
			return false;
		}
		throw err;
	}
}

// Recursive directory copy using COPYFILE_FICLONE (reflink) per file.
// For .sqlite files, checkpoints WAL first so the main file is self-contained.
async function copyTreeWithReflink(
	src: string,
	dest: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; usedReflink: boolean }> {
	const metadata = await stat(src);

	if (!metadata.isDirectory()) {
		if (src.endsWith(".sqlite")) {
			if (options.preCheckIntegrity) {
				const check = await runIntegrityCheck(src, { mode: "quick" });
				if (check.status === "corrupt") {
					throw new Error(
						`Refusing to back up corrupt SQLite database at ${src}: ${check.messages.join("; ")}`,
					);
				}
				if (check.status === "unavailable") {
					warn(`SQLite integrity check unavailable for ${src} before backup: ${check.error}`);
				}
			}
			await checkpointSqliteWal(src, warn);
		}
		const usedReflink = await copyFileWithReflink(src, dest);
		if (options.postCheckIntegrity && dest.endsWith(".sqlite")) {
			const check = await runIntegrityCheck(dest, { mode: "quick" });
			if (check.status !== "ok") {
				warn(
					`Restored SQLite database at ${dest} failed integrity check (${check.status}): ${
						check.messages.join("; ") || check.error || ""
					}`,
				);
			}
		}
		return { fileCount: 1, usedReflink };
	}

	await mkdir(dest, { recursive: true });
	const entries = await readdir(src, { withFileTypes: true });
	let fileCount = 0;
	let usedReflink = false;

	for (const entry of entries) {
		const r = await copyTreeWithReflink(
			join(src, entry.name),
			join(dest, entry.name),
			warn,
			options,
		);
		fileCount += r.fileCount;
		usedReflink = usedReflink || r.usedReflink;
	}

	return { fileCount, usedReflink };
}

async function processIncludes(
	includes: string[],
	srcBase: string,
	destBase: string,
	warn: (msg: string) => void,
	options: { preCheckIntegrity?: boolean; postCheckIntegrity?: boolean } = {},
): Promise<{ fileCount: number; anyReflink: boolean }> {
	let fileCount = 0;
	let anyReflink = false;
	for (const entry of includes) {
		const src = resolve(srcBase, entry);
		if (!(await pathExists(src))) continue;
		const dest = resolve(destBase, entry);
		await mkdir(dirname(dest), { recursive: true });
		const r = await copyTreeWithReflink(src, dest, warn, options);
		fileCount += r.fileCount;
		anyReflink = anyReflink || r.usedReflink;
	}
	return { fileCount, anyReflink };
}

export function createAstropressGitSyncAdapter(
	options: AstropressGitSyncAdapterOptions,
): GitSyncAdapter {
	const projectDir = resolve(options.projectDir);
	const include = options.include ?? defaultEntries;
	const log = options.logger?.info ?? (() => {});
	const warn = options.logger?.warn ?? (() => {});

	return {
		async exportSnapshot(targetDir) {
			const outputDir = resolve(targetDir);
			await rm(outputDir, { recursive: true, force: true });
			await mkdir(outputDir, { recursive: true });
			const { fileCount, anyReflink } = await processIncludes(
				include,
				projectDir,
				outputDir,
				warn,
				{ preCheckIntegrity: true },
			);
			log(
				anyReflink
					? `Snapshot exported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot exported using standard copy: ${fileCount} file(s)`,
			);
			return { targetDir: outputDir, fileCount };
		},
		async importSnapshot(sourceDir) {
			const inputDir = resolve(sourceDir);
			// Remove existing entries before restoring, unlike export which starts fresh.
			for (const entry of include) {
				await rm(resolve(projectDir, entry), { recursive: true, force: true });
			}
			const { fileCount, anyReflink } = await processIncludes(include, inputDir, projectDir, warn, {
				postCheckIntegrity: true,
			});
			log(
				anyReflink
					? `Snapshot imported using copy-on-write (reflink): ${fileCount} file(s)`
					: `Snapshot imported using standard copy: ${fileCount} file(s)`,
			);
			return { sourceDir: inputDir, fileCount };
		},
	};
}

src/taxonomy-repository-factory.ts.source:
import type { Actor, TaxonomyKind, TaxonomyRepository } from "./persistence-types";

type TaxonomyTable = "categories" | "tags";

export interface AstropressTaxonomyRepositoryInput {
	listCategories: TaxonomyRepository["listCategories"];
	listTags: TaxonomyRepository["listTags"];
	slugifyTerm(value: string): string;
	createTaxonomyTerm(input: {
		table: TaxonomyTable;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	updateTaxonomyTerm(input: {
		table: TaxonomyTable;
		id: number;
		slug: string;
		name: string;
		description: string;
	}): boolean;
	deleteTaxonomyTerm(input: { table: TaxonomyTable; id: number }): boolean;
	recordTaxonomyAudit(input: {
		actor: Actor;
		action: `${TaxonomyKind}.create` | `${TaxonomyKind}.update` | `${TaxonomyKind}.delete`;
		summary: string;
		targetId: string;
	}): void;
}

function createTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!name || !slug) {
		return { ok: false as const, error: `${kind} name and slug are required.` };
	}

	const created = input.createTaxonomyTerm({
		table,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!created) {
		return {
			ok: false as const,
			error: `That ${kind} name or slug is already in use.`,
		};
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.create`,
		summary: `Created ${kind} ${name}.`,
		targetId: slug,
	});
	return { ok: true as const };
}

function updateTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	rawInput: { id: number; name: string; slug?: string; description?: string },
	actor: Actor,
) {
	const name = rawInput.name.trim();
	const slug = input.slugifyTerm(rawInput.slug?.trim() || name);
	if (!rawInput.id || !name || !slug) {
		return {
			ok: false as const,
			error: `${kind} id, name, and slug are required.`,
		};
	}

	const updated = input.updateTaxonomyTerm({
		table,
		id: rawInput.id,
		slug,
		name,
		description: rawInput.description?.trim() ?? "",
	});
	if (!updated) {
		return { ok: false as const, error: `That ${kind} could not be updated.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.update`,
		summary: `Updated ${kind} ${name}.`,
		targetId: String(rawInput.id),
	});
	return { ok: true as const };
}

function deleteTerm(
	input: AstropressTaxonomyRepositoryInput,
	table: TaxonomyTable,
	kind: TaxonomyKind,
	id: number,
	actor: Actor,
) {
	const deleted = input.deleteTaxonomyTerm({ table, id });
	if (!deleted) {
		return { ok: false as const, error: `That ${kind} could not be deleted.` };
	}

	input.recordTaxonomyAudit({
		actor,
		action: `${kind}.delete`,
		summary: `Deleted ${kind} ${id}.`,
		targetId: String(id),
	});
	return { ok: true as const };
}

export function createAstropressTaxonomyRepository(
	input: AstropressTaxonomyRepositoryInput,
): TaxonomyRepository {
	return {
		listCategories: (...args) => input.listCategories(...args),
		listTags: (...args) => input.listTags(...args),
		createCategory: (rawInput, actor) =>
			createTerm(input, "categories", "category", rawInput, actor),
		updateCategory: (rawInput, actor) =>
			updateTerm(input, "categories", "category", rawInput, actor),
		deleteCategory: (id, actor) => deleteTerm(input, "categories", "category", id, actor),
		createTag: (rawInput, actor) => createTerm(input, "tags", "tag", rawInput, actor),
		updateTag: (rawInput, actor) => updateTerm(input, "tags", "tag", rawInput, actor),
		deleteTag: (id, actor) => deleteTerm(input, "tags", "tag", id, actor),
	};
}

src/transactional-email.ts.source:
interface EmailResult {
	ok: boolean;
	/** true only when the email was actually transmitted to the delivery provider */
	delivered: boolean;
	error?: string;
	preview?: {
		to: string;
		subject: string;
		html: string;
	};
}

interface EmailMessage {
	to: string;
	subject: string;
	html: string;
	text?: string;
}

import nodemailer from "nodemailer";
import { peekCmsConfig } from "./config";
import { getTransactionalEmailConfig, isProductionRuntime } from "./runtime-env";

function escapeHtml(str: string): string {
	return str
		.replace(/&/g, "&amp;")
		.replace(/</g, "&lt;")
		.replace(/>/g, "&gt;")
		.replace(/"/g, "&quot;")
		.replace(/'/g, "&#39;");
}

function isMockMode(locals?: App.Locals | null) {
	return getTransactionalEmailConfig(locals).mode === "mock";
}

async function sendResendEmail(
	message: EmailMessage,
	locals?: App.Locals | null,
): Promise<EmailResult> {
	const { resendApiKey: apiKey, resendFrom: from } = getTransactionalEmailConfig(locals);

	if (!apiKey || !from) {
		if (isProductionRuntime()) {
			return {
				ok: false,
				delivered: false,
				error: "Transactional email is not configured.",
			};
		}

		return {
			ok: true,
			delivered: false,
			preview: {
				to: message.to,
				subject: message.subject,
				html: message.html,
			},
		};
	}

	const response = await fetch("https://api.resend.com/emails", {
		method: "POST",
		headers: {
			Authorization: `Bearer ${apiKey}`,
			"Content-Type": "application/json",
		},
		body: JSON.stringify({
			from,
			to: [message.to],
			subject: message.subject,
			html: message.html,
			text: message.text,
		}),
	});

	if (!response.ok) {
		const errorBody = await response.text();
		return {
			ok: false,
			delivered: false,
			error: `Resend error: ${errorBody || response.statusText}`,
		};
	}

	return { ok: true, delivered: true };
}

async function sendSmtpEmail(
	message: EmailMessage,
	locals?: App.Locals | null,
): Promise<EmailResult> {
	const config = getTransactionalEmailConfig(locals);
	const host = config.smtpHost;
	const from = config.smtpFrom;
	const port = Number.parseInt(config.smtpPort ?? "587", 10);

	if (!host || !from || !port) {
		if (isProductionRuntime()) {
			return {
				ok: false,
				delivered: false,
				error: "SMTP transactional email is not configured.",
			};
		}

		return {
			ok: true,
			delivered: false,
			preview: {
				to: message.to,
				subject: message.subject,
				html: message.html,
			},
		};
	}

	try {
		const transporter = nodemailer.createTransport({
			host,
			port,
			secure: port === 465,
			auth:
				config.smtpUsername || config.smtpPassword
					? {
							user: config.smtpUsername,
							pass: config.smtpPassword,
						}
					: undefined,
		});

		await transporter.sendMail({
			from,
			to: message.to,
			subject: message.subject,
			html: message.html,
			text: message.text,
		});

		return { ok: true, delivered: true };
	} catch (error) {
		return {
			ok: false,
			delivered: false,
			error: error instanceof Error ? error.message : "SMTP delivery failed.",
		};
	}
}

export async function sendTransactionalEmail(
	message: EmailMessage,
	locals?: App.Locals | null,
): Promise<EmailResult> {
	if (isMockMode(locals)) {
		return {
			ok: true,
			delivered: false,
			preview: {
				to: message.to,
				subject: message.subject,
				html: message.html,
			},
		};
	}

	if (getTransactionalEmailConfig(locals).mode === "smtp") {
		return sendSmtpEmail(message, locals);
	}

	return sendResendEmail(message, locals);
}

export async function sendPasswordResetEmail(
	email: string,
	resetUrl: string,
	locals?: App.Locals | null,
): Promise<EmailResult> {
	const siteName = escapeHtml(peekCmsConfig()?.siteName ?? "Astropress");
	return sendTransactionalEmail(
		{
			to: email,
			subject: `Reset your ${siteName} admin password`,
			text: `Use this link to reset your ${siteName} admin password: ${resetUrl}`,
			html: `<p>Use the link below to reset your ${siteName} admin password.</p><p><a href="${escapeHtml(resetUrl)}">${escapeHtml(resetUrl)}</a></p>`,
		},
		locals,
	);
}

export async function sendUserInviteEmail(
	email: string,
	inviteUrl: string,
	locals?: App.Locals | null,
): Promise<EmailResult> {
	const siteName = escapeHtml(peekCmsConfig()?.siteName ?? "Astropress");
	return sendTransactionalEmail(
		{
			to: email,
			subject: `Accept your ${siteName} admin invitation`,
			text: `Use this link to accept your ${siteName} admin invitation and set your password: ${inviteUrl}`,
			html: `<p>You have been invited to the ${siteName} admin.</p><p>Use the link below to accept the invitation and set your password.</p><p><a href="${escapeHtml(inviteUrl)}">${escapeHtml(inviteUrl)}</a></p>`,
		},
		locals,
	);
}

export async function sendContactNotification(
	input: {
		name: string;
		email: string;
		message: string;
		submittedAt: string;
	},
	locals?: App.Locals | null,
): Promise<EmailResult> {
	const { contactDestination: destination } = getTransactionalEmailConfig(locals);
	const safeName = escapeHtml(input.name);
	const safeEmail = escapeHtml(input.email);
	const safeMessage = escapeHtml(input.message);
	const safeSubmittedAt = escapeHtml(input.submittedAt);

	if (!destination) {
		if (isProductionRuntime()) {
			return {
				ok: false,
				delivered: false,
				error: "Contact notification email is not configured.",
			};
		}

		return {
			ok: true,
			delivered: false,
			preview: {
				to: "admin-preview@example.local",
				subject: `Preview contact submission from ${safeName}`,
				html: `<p>${safeName} (${safeEmail}) submitted a contact request.</p><p>${safeMessage}</p>`,
			},
		};
	}

	return sendTransactionalEmail(
		{
			to: destination,
			subject: `${escapeHtml(peekCmsConfig()?.siteName ?? "Astropress")} contact submission from ${safeName}`,
			text: `${input.name} <${input.email}> submitted a contact request at ${input.submittedAt}\n\n${input.message}`,
			html: `<p><strong>${safeName}</strong> &lt;${safeEmail}&gt; submitted a contact request at ${safeSubmittedAt}.</p><p>${safeMessage}</p>`,
		},
		locals,
	);
}

