import type { Actor, TranslationRepository } from "./persistence-types";
import {
	normalizeTranslationState,
	type TranslationState,
	translationStates,
} from "./translation-state";

export interface AstropressTranslationRepositoryInput {
	readTranslationState(route: string): string | null | undefined;
	persistTranslationState(route: string, state: TranslationState, actor: Actor): void;
	recordTranslationAudit(input: { actor: Actor; route: string; state: TranslationState }): void;
}

export function createAstropressTranslationRepository(
	input: AstropressTranslationRepositoryInput,
): TranslationRepository {
	return {
		updateTranslationState(route, state, actor) {
			const normalizedState = normalizeTranslationState(state, "__invalid__" as TranslationState);
			if (!(translationStates as readonly string[]).includes(normalizedState)) {
				return {
					ok: false as const,
					error: `Invalid translation state. Must be one of: ${translationStates.join(", ")}`,
				};
			}

			input.persistTranslationState(route, normalizedState, actor);
			input.recordTranslationAudit({
				actor,
				route,
				state: normalizedState,
			});

			return { ok: true as const };
		},
		getEffectiveTranslationState(route, fallback) {
			// normalizeTranslationState's own fallback is "not_started"; pass
			// the caller-supplied fallback through only if provided, otherwise
			// let normalize use its default to avoid an equivalent default-arg
			// string literal.
			const normalized = fallback === undefined ? undefined : normalizeTranslationState(fallback);
			return normalizeTranslationState(input.readTranslationState(route), normalized);
		},
	};
}

src/translation-state.ts.source:
export const translationStates = [
	"not_started",
	"partial",
	"fallback_en",
	"translated",
	"reviewed",
	"published",
] as const;

export type TranslationState = (typeof translationStates)[number];

const legacyStateMap: Record<string, TranslationState> = {
	original: "not_started",
	"in-progress": "partial",
	"pending-review": "translated",
	approved: "reviewed",
	"needs-revision": "partial",
	archived: "fallback_en",
	complete: "published",
};

export function normalizeTranslationState(
	value: string | null | undefined,
	fallback: TranslationState = "not_started",
): TranslationState {
	if (!value) {
		return fallback;
	}

	const normalized = value.trim().toLowerCase();
	if ((translationStates as readonly string[]).includes(normalized)) {
		return normalized as TranslationState;
	}

	return legacyStateMap[normalized] ?? fallback;
}

export function isPublishedTranslationState(value: string | null | undefined) {
	return normalizeTranslationState(value) === "published";
}

src/turnstile.ts.source:
import { getLoginSecurityConfig, isProductionRuntime } from "./runtime-env";

interface TurnstileVerificationResult {
	ok: boolean;
	error?: string;
}

interface TurnstileResponsePayload {
	success?: boolean;
	"error-codes"?: string[];
}

export function isTurnstileEnabled(locals?: App.Locals | null) {
	return Boolean(getLoginSecurityConfig(locals).turnstileSecretKey);
}

export async function verifyTurnstileToken(input: {
	token: string | null | undefined;
	ipAddress?: string | null;
	locals?: App.Locals | null;
	requireConfigured?: boolean;
}): Promise<TurnstileVerificationResult> {
	const { turnstileSecretKey } = getLoginSecurityConfig(input.locals);
	if (!turnstileSecretKey) {
		if (input.requireConfigured && isProductionRuntime()) {
			return { ok: false, error: "Security challenge is not configured." };
		}

		return { ok: true };
	}

	const token = input.token?.trim();
	if (!token) {
		return { ok: false, error: "Security challenge is required." };
	}

	const payload = new URLSearchParams({
		secret: turnstileSecretKey,
		response: token,
	});

	if (input.ipAddress) {
		payload.set("remoteip", input.ipAddress);
	}

	try {
		const response = await fetch("https://challenges.cloudflare.com/turnstile/v0/siteverify", {
			method: "POST",
			headers: {
				"Content-Type": "application/x-www-form-urlencoded",
			},
			body: payload,
		});

		if (!response.ok) {
			return { ok: false, error: "Security challenge could not be verified." };
		}

		const result = (await response.json()) as TurnstileResponsePayload;
		if (!result.success) {
			return {
				ok: false,
				error: result["error-codes"]?.join(", ") || "Security challenge failed.",
			};
		}

		return { ok: true };
	} catch {
		return { ok: false, error: "Security challenge could not be verified." };
	}
}

src/user-repository-factory.ts.source:
import type { Actor, UserRepository } from "./persistence-types";

export interface AstropressUserRepositoryInput {
	listAdminUsers: UserRepository["listAdminUsers"];
	hashPassword(value: string): string;
	hashOpaqueToken(value: string): string;
	findAdminUserByEmail(email: string): { id: number } | null | undefined;
	createInvitedAdminUser(input: {
		email: string;
		passwordHash: string;
		role: "admin" | "editor";
		name: string;
	}): boolean;
	getAdminUserIdByEmail(email: string): number | null | undefined;
	insertUserInvite(input: {
		inviteId: string;
		userId: number;
		tokenHash: string;
		expiresAt: string;
		invitedBy: string;
	}): boolean;
	setAdminUserActiveState(email: string, nextActive: boolean): boolean;
	revokeAdminSessionsForEmail(email: string): void;
	recordUserAudit(input: {
		actor: Actor;
		action: "user.invite" | "user.suspend" | "user.restore";
		summary: string;
		targetId: string;
	}): void;
}

function isValidEmailAddress(email: string): boolean {
	if (email.length > 254) return false;
	return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
}

export function createAstropressUserRepository(
	input: AstropressUserRepositoryInput,
): UserRepository {
	return {
		listAdminUsers: (...args) => input.listAdminUsers(...args),
		inviteAdminUser(rawInput, actor) {
			const name = rawInput.name.trim();
			const email = rawInput.email.trim().toLowerCase();
			const role = rawInput.role === "admin" ? "admin" : rawInput.role === "editor" ? "editor" : "";

			if (!name || !email || !role) {
				return {
					ok: false as const,
					error: "Name, email, and role are required.",
				};
			}

			if (!isValidEmailAddress(email)) {
				return { ok: false as const, error: "Enter a valid email address." };
			}

			const existing = input.findAdminUserByEmail(email);
			if (existing) {
				return {
					ok: false as const,
					error: "That email address already belongs to an admin user.",
				};
			}

			const created = input.createInvitedAdminUser({
				email,
				passwordHash: input.hashPassword(crypto.randomUUID()),
				role,
				name,
			});
			if (!created) {
				return {
					ok: false as const,
					error: "The invited user could not be created.",
				};
			}

			const userId = input.getAdminUserIdByEmail(email);
			if (!userId) {
				return {
					ok: false as const,
					error: "The invited user could not be created.",
				};
			}

			const rawToken = crypto.randomUUID();
			const inviteId = `invite-${crypto.randomUUID()}`;
			const expiresAt = new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString();

			const insertedInvite = input.insertUserInvite({
				inviteId,
				userId,
				tokenHash: input.hashOpaqueToken(rawToken),
				expiresAt,
				invitedBy: actor.email,
			});
			if (!insertedInvite) {
				return {
					ok: false as const,
					error: "The invitation link could not be created.",
				};
			}

			input.recordUserAudit({
				actor,
				action: "user.invite",
				summary: `Invited ${email} as an ${role} user.`,
				targetId: email,
			});
			return {
				ok: true as const,
				inviteUrl: `/ap-admin/accept-invite?token=${encodeURIComponent(rawToken)}`,
			};
		},
		suspendAdminUser(email, actor) {
			const normalizedEmail = email.trim().toLowerCase();
			if (!normalizedEmail) {
				return { ok: false as const, error: "Email is required." };
			}

			if (normalizedEmail === actor.email.toLowerCase()) {
				return {
					ok: false as const,
					error: "You cannot suspend the account you are currently using.",
				};
			}

			const suspended = input.setAdminUserActiveState(normalizedEmail, false);
			if (!suspended) {
				return {
					ok: false as const,
					error: "That admin user could not be suspended.",
				};
			}

			input.revokeAdminSessionsForEmail(normalizedEmail);
			input.recordUserAudit({
				actor,
				action: "user.suspend",
				summary: `Suspended ${normalizedEmail}.`,
				targetId: normalizedEmail,
			});
			return { ok: true as const };
		},
		unsuspendAdminUser(email, actor) {
			const normalizedEmail = email.trim().toLowerCase();
			if (!normalizedEmail) {
				return { ok: false as const, error: "Email is required." };
			}

			const restored = input.setAdminUserActiveState(normalizedEmail, true);
			if (!restored) {
				return {
					ok: false as const,
					error: "That admin user could not be restored.",
				};
			}

			input.recordUserAudit({
				actor,
				action: "user.restore",
				summary: `Restored ${normalizedEmail}.`,
				targetId: normalizedEmail,
			});
			return { ok: true as const };
		},
	};
}

src/vite-integration.ts.source:
import {
	type AstropressViteAlias,
	type AstropressVitePlugin,
	type AstropressViteRuntimeAliasOptions,
	createAstropressLocalRuntimeModulePlugin,
	createAstropressPackageResolverPlugin,
	createAstropressViteAliases,
} from "./vite-runtime-alias";

export type AstropressViteIntegration = {
	plugins: AstropressVitePlugin[];
	aliases: AstropressViteAlias[];
};

export function createAstropressViteIntegration(
	options: AstropressViteRuntimeAliasOptions,
): AstropressViteIntegration {
	const plugins: AstropressVitePlugin[] = [
		createAstropressLocalRuntimeModulePlugin(options.localRuntimeModulesPath),
	];
	if (options.astropressPackageRoot) {
		plugins.push(createAstropressPackageResolverPlugin(options.astropressPackageRoot));
	}
	return {
		plugins,
		aliases: createAstropressViteAliases(options),
	};
}

