	"SELECT s.id, s.csrf_token, s.last_active_at, u.email, CASE WHEN u.is_admin = 1 THEN 'admin' ELSE 'editor' END AS role, u.name FROM admin_sessions s JOIN admin_users u ON u.id = s.user_id WHERE s.id = ? AND s.revoked_at IS NULL AND u.active = 1 LIMIT 1";
