	"SELECT i.id, i.user_id, i.token_hash, i.expires_at, i.accepted_at, i.created_at, u.email, u.name, CASE WHEN u.is_admin = 1 THEN 'admin' ELSE 'editor' END AS role, u.active FROM user_invites i JOIN admin_users u ON u.id = i.user_id WHERE i.token_hash = ? LIMIT 1";
