export const SQL_INSERT_RESET_TOKEN =
	"INSERT INTO password_reset_tokens (id, user_id, token_hash, expires_at, requested_by) VALUES (?, ?, ?, ?, ?)";
export const SQL_FIND_RESET_TOKEN =
