import { beforeEach, describe, expect, it, vi } from "vitest";

// ---------------------------------------------------------------------------
// Playwright mock
// ---------------------------------------------------------------------------

type MockPage = {
	goto: ReturnType<typeof vi.fn>;
	fill: ReturnType<typeof vi.fn>;
	click: ReturnType<typeof vi.fn>;
	waitForURL: ReturnType<typeof vi.fn>;
	url: ReturnType<typeof vi.fn>;
	locator: ReturnType<typeof vi.fn>;
	waitForSelector: ReturnType<typeof vi.fn>;
	waitForEvent: ReturnType<typeof vi.fn>;
	content: ReturnType<typeof vi.fn>;
};

const mocks = vi.hoisted(() => {
	const page: MockPage = {
		goto: vi.fn(),
		fill: vi.fn(),
		click: vi.fn(),
		waitForURL: vi.fn(),
		url: vi.fn(),
		locator: vi.fn(),
		waitForSelector: vi.fn(),
		waitForEvent: vi.fn(),
		content: vi.fn(),
	};

	const context = {
		newPage: vi.fn().mockResolvedValue(page),
		close: vi.fn(),
	};

	const browser = {
		newContext: vi.fn().mockResolvedValue(context),
		close: vi.fn(),
	};

	return { page, context, browser };
});

vi.mock("playwright", () => ({
	chromium: {
		launch: vi.fn().mockResolvedValue(mocks.browser),
	},
}));

import { chromium } from "playwright";
import {
	BotDetectionError,
	CaptchaDetectedError,
	fetchWordPressExport,
	InsufficientPermissionsError,
	InvalidCredentialsError,
	NotWordPressSiteError,
	SiteNotReachableError,
	TwoFactorRequiredError,
} from "../../src/import/fetch-wordpress.js";

const BASE_OPTS = {
	siteUrl: "https://mysite.com",
	username: "admin",
	password: "secret",
	downloadDir: "/tmp/wp-downloads",
};

function makeLocator(opts: { count?: number; exists?: boolean } = {}) {
	return {
		count: vi.fn().mockResolvedValue(opts.count ?? 0),
		first: vi.fn().mockReturnThis(),
		click: vi.fn(),
		waitFor: vi.fn(),
	};
}

function setupBrowserChain() {
	vi.mocked(chromium.launch).mockResolvedValue(mocks.browser as never);
	mocks.browser.newContext.mockResolvedValue(mocks.context);
	mocks.context.newPage.mockResolvedValue(mocks.page);
	// Safe defaults — individual tests can override
	mocks.page.content.mockResolvedValue("<html></html>");
	mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
	mocks.page.locator.mockReturnValue(makeLocator({ count: 0 }));
	mocks.page.goto.mockResolvedValue({ status: () => 200 });
}

describe("fetchWordPressExport — success path", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();

		// goto succeeds
		mocks.page.goto.mockResolvedValue({ status: () => 200 });

		// login page looks like WordPress
		mocks.page.content.mockResolvedValue(
			'<html><body><form id="loginform"><input id="user_login" /><input id="user_pass" /></form></body></html>',
		);

		// after login submit, URL changes to dashboard (not still on login page)
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");

		// export page: no 2FA, no CAPTCHA, has export link
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel.includes("two-factor") || sel.includes("mfa") || sel.includes("captcha")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});

		// download event
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "wordpress-export.xml",
			saveAs: vi.fn(),
		});
	});

	it("navigates to wp-login.php, fills credentials, and submits", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.goto).toHaveBeenCalledWith(
			expect.stringContaining("wp-login.php"),
			expect.any(Object),
		);
		expect(mocks.page.fill).toHaveBeenCalledWith("#user_login", "admin");
		expect(mocks.page.fill).toHaveBeenCalledWith("#user_pass", "secret");
		expect(mocks.page.click).toHaveBeenCalledWith("#wp-submit");
	});

	it("returns the path to the downloaded export file with an empty warnings array", async () => {
		const result = await fetchWordPressExport(BASE_OPTS);
		expect(result.exportPath).toContain("wordpress-export.xml");
		expect(result.warnings).toEqual([]);
	});

	it("navigates to wp-admin/export.php with timeout + waitUntil:'domcontentloaded'", async () => {
		await fetchWordPressExport(BASE_OPTS);
		const exportCall = mocks.page.goto.mock.calls.find(
			([url]) => typeof url === "string" && url.endsWith("/wp-admin/export.php"),
		);
		expect(exportCall).toBeDefined();
		expect(exportCall?.[0]).toBe("https://mysite.com/wp-admin/export.php");
		expect(exportCall?.[1]).toMatchObject({
			timeout: expect.any(Number),
			waitUntil: "domcontentloaded",
		});
	});

	it("does NOT click submit when the #submit locator's count is 0 (download still proceeds via waitForEvent)", async () => {
		const submitLocator = makeLocator({ count: 0 });
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel === "#submit") return submitLocator;
			if (sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});
		await fetchWordPressExport(BASE_OPTS);
		expect(submitLocator.click).not.toHaveBeenCalled();
	});

	it("requests the page's #submit locator AND clicks it when the count is > 0", async () => {
		const submitLocator = makeLocator({ count: 1 });
		// Override the locator implementation so we can spy on the #submit locator specifically
		// while still returning count=0 for 2FA selectors.
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel === "#submit") return submitLocator;
			if (sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor")) {
				return makeLocator({ count: 0 });
			}
			return makeLocator({ count: 1 });
		});
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.locator).toHaveBeenCalledWith("#submit");
		expect(submitLocator.click).toHaveBeenCalled();
	});

	it("waits for the 'download' event with a timeout option", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.page.waitForEvent).toHaveBeenCalledWith(
			"download",
			expect.objectContaining({ timeout: expect.any(Number) }),
		);
	});

	it("creates the browser context with acceptDownloads enabled", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.browser.newContext).toHaveBeenCalledWith({ acceptDownloads: true });
	});

	it("closes the browser even on success", async () => {
		await fetchWordPressExport(BASE_OPTS);
		expect(mocks.browser.close).toHaveBeenCalled();
	});
});

describe("fetchWordPressExport — failure modes", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("throws SiteNotReachableError when goto fails with network error", async () => {
		mocks.page.goto.mockRejectedValue(
			Object.assign(new Error("net::ERR_NAME_NOT_RESOLVED"), { name: "Error" }),
		);
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(SiteNotReachableError);
	});

	it("SiteNotReachableError message names the hostname", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED mysite.com"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: DNS lookup failed",
		);
	});

	it("throws NotWordPressSiteError when wp-login.php is not found", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 404 });
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(NotWordPressSiteError);
	});

	it("throws NotWordPressSiteError with clear message", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 404 });
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"does not appear to be a WordPress site",
		);
	});

	it("throws InvalidCredentialsError when still on login page after submit", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<html><body><div id="login_error">Error: The password you entered</div><form id="loginform"></form></body></html>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(InvalidCredentialsError);
	});

	it("InvalidCredentialsError has a clear human-readable message", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<form id="loginform"><div id="login_error">wrong</div></form>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Login failed: username or password was incorrect",
		);
	});

	it("throws TwoFactorRequiredError when 2FA form is detected", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) => {
			if (sel.includes("two-factor") || sel.includes("authcode")) {
				return makeLocator({ count: 1 });
			}
			return makeLocator({ count: 0 });
		});

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(TwoFactorRequiredError);
	});

	it("TwoFactorRequiredError message tells user to use --source instead", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({ count: sel.includes("authcode") ? 1 : 0 }),
		);

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Two-factor authentication is required",
		);
	});

	it("throws CaptchaDetectedError when login page has CAPTCHA", async () => {
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue(
			'<html><form id="loginform"><div class="g-recaptcha"></div></form></html>',
		);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(CaptchaDetectedError);
	});

	it("throws InsufficientPermissionsError when export.php redirects back to login", async () => {
		mocks.page.goto
			.mockResolvedValueOnce({ status: () => 200 }) // wp-login.php
			.mockResolvedValueOnce({ status: () => 200 }); // export.php redirects
		mocks.page.content.mockResolvedValue('<html><form id="loginform"></form></html>');
		mocks.page.url
			.mockReturnValueOnce("https://mysite.com/wp-admin/") // after login
			.mockReturnValueOnce("https://mysite.com/wp-login.php"); // after navigating to export
		mocks.page.locator.mockReturnValue(makeLocator({ count: 0 }));

		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(
			InsufficientPermissionsError,
		);
	});

	it("always closes the browser even when an error is thrown", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow();
		expect(mocks.browser.close).toHaveBeenCalled();
	});
});

// ---------------------------------------------------------------------------
// Exact error-class name and message assertions (kill StringLiteral mutants
// on `override name` and the constructor super(...) messages).
// ---------------------------------------------------------------------------

describe("typed Error classes — exact name and message", () => {
	it("SiteNotReachableError has name='SiteNotReachableError' and the documented hostname:reason format", () => {
		const err = new SiteNotReachableError("example.com", "boom");
		expect(err.name).toBe("SiteNotReachableError");
		expect(err.message).toBe("Cannot reach example.com: boom");
	});

	it("NotWordPressSiteError has name='NotWordPressSiteError' and references the URL with the documented message", () => {
		const err = new NotWordPressSiteError("https://x.test");
		expect(err.name).toBe("NotWordPressSiteError");
		expect(err.message).toBe(
			"The URL does not appear to be a WordPress site — wp-login.php was not found at https://x.test",
		);
	});

	it("InvalidCredentialsError has name='InvalidCredentialsError' and the documented message", () => {
		const err = new InvalidCredentialsError();
		expect(err.name).toBe("InvalidCredentialsError");
		expect(err.message).toBe("Login failed: username or password was incorrect");
	});

	it("TwoFactorRequiredError has name='TwoFactorRequiredError' and the documented message", () => {
		const err = new TwoFactorRequiredError();
		expect(err.name).toBe("TwoFactorRequiredError");
		expect(err.message).toBe(
			"Two-factor authentication is required — export the file manually and use --source",
		);
	});

	it("CaptchaDetectedError has name='CaptchaDetectedError' and both documented lines of guidance", () => {
		const err = new CaptchaDetectedError();
		expect(err.name).toBe("CaptchaDetectedError");
		expect(err.message).toContain("CAPTCHA detected — the site requires human verification.");
		expect(err.message).toContain(
			"Export the file manually via Tools → Export in your WordPress dashboard and use --source.",
		);
	});

	it("BotDetectionError has name='BotDetectionError' and both documented lines of guidance", () => {
		const err = new BotDetectionError();
		expect(err.name).toBe("BotDetectionError");
		expect(err.message).toContain(
			"Bot detection triggered (Cloudflare or similar security layer).",
		);
		expect(err.message).toContain(
			"Export the file manually via Tools → Export in your WordPress dashboard and use --source.",
		);
	});

	it("InsufficientPermissionsError has name='InsufficientPermissionsError' and both documented lines of guidance", () => {
		const err = new InsufficientPermissionsError();
		expect(err.name).toBe("InsufficientPermissionsError");
		expect(err.message).toContain("Insufficient permissions");
		expect(err.message).toContain(
			"Log into WordPress, go to Users → Your Profile, and confirm the role is Administrator.",
		);
	});
});

// ---------------------------------------------------------------------------
// classifyNetworkError — exercised via fetchWordPressExport with goto rejections
// ---------------------------------------------------------------------------

describe("classifyNetworkError (via goto rejection)", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("classifies ERR_CONNECTION_REFUSED as the documented 'connection refused' reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_CONNECTION_REFUSED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: connection refused — is the site running?",
		);
	});

	it("classifies ERR_CERT_* / SSL / certificate errors as the documented SSL reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_CERT_AUTHORITY_INVALID"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: SSL/TLS error — try using http:// instead of https://",
		);
	});

	it("classifies TIMEOUT errors (case-insensitive) as the documented timed-out reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("Navigation TIMEOUT exceeded"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: timed out — the server took too long to respond",
		);
	});

	it("classifies EAI_AGAIN as the documented DNS-lookup-failed reason", async () => {
		mocks.page.goto.mockRejectedValue(new Error("getaddrinfo EAI_AGAIN mysite.com"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: DNS lookup failed — check the site URL is correct",
		);
	});

	it("falls back to the raw error message verbatim when no classifier matches", async () => {
		mocks.page.goto.mockRejectedValue(new Error("strange unknown problem"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: strange unknown problem",
		);
	});

	it("stringifies non-Error rejection values via String(err)", async () => {
		mocks.page.goto.mockRejectedValue("plain-string-rejection");
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toThrow(
			"Cannot reach mysite.com: plain-string-rejection",
		);
	});
});

// ---------------------------------------------------------------------------
// isBotBlocked — every cf-* token triggers BotDetectionError independently
// ---------------------------------------------------------------------------

describe("isBotBlocked (via login-page content)", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.url.mockReturnValue("https://mysite.com/wp-login.php");
	});

	const tokens = [
		"cf-browser-verification",
		"cf-challenge",
		"cf-spinner",
		"window._cf_chl_opt",
		"__cf_chl_jschl_tk__",
	];
	for (const token of tokens) {
		it(`throws BotDetectionError when the login page contains '${token}' (NOT CaptchaDetectedError)`, async () => {
			mocks.page.content.mockResolvedValue(
				`<html><body><form id="loginform"></form><script>${token}</script></body></html>`,
			);
			await expect(fetchWordPressExport({ ...BASE_OPTS, headless: false })).rejects.toBeInstanceOf(
				BotDetectionError,
			);
		});
	}
});

// ---------------------------------------------------------------------------
// Public API — headless retry semantics
// ---------------------------------------------------------------------------

describe("fetchWordPressExport — headless retry on bot detection", () => {
	beforeEach(() => {
		vi.resetAllMocks();
		setupBrowserChain();
	});

	it("with headless=false explicit, skips the headless attempt and runs visible-only", async () => {
		const launch = vi.mocked(chromium.launch);
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		mocks.page.content.mockResolvedValue('<form id="loginform"></form>');
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({
				count:
					sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor") ? 0 : 1,
			}),
		);
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "x.xml",
			saveAs: vi.fn(),
		});

		await fetchWordPressExport({ ...BASE_OPTS, headless: false });
		// Single launch with headless: false — no headless first-pass.
		expect(launch).toHaveBeenCalledTimes(1);
		expect(launch).toHaveBeenCalledWith({ headless: false });
	});

	it("retries with headless=false after a headless BotDetectionError, and writes the documented stderr notice", async () => {
		const launch = vi.mocked(chromium.launch);
		// Both attempts succeed past initial nav; the FIRST attempt's content trips bot detection.
		mocks.page.goto.mockResolvedValue({ status: () => 200 });
		const captchaContent = '<form id="loginform"></form><script>cf-challenge</script>';
		const cleanContent = '<form id="loginform"></form>';
		// First call (headless pass): bot-blocked content
		// Subsequent calls (visible retry): clean content
		mocks.page.content.mockResolvedValueOnce(captchaContent).mockResolvedValue(cleanContent);
		mocks.page.url.mockReturnValue("https://mysite.com/wp-admin/");
		mocks.page.locator.mockImplementation((sel: string) =>
			makeLocator({
				count:
					sel.includes("authcode") || sel.includes("mfa") || sel.includes("two-factor") ? 0 : 1,
			}),
		);
		mocks.page.waitForEvent.mockResolvedValue({
			suggestedFilename: () => "x.xml",
			saveAs: vi.fn(),
		});

		const stderrWrite = vi.spyOn(process.stderr, "write").mockReturnValue(true);
		await fetchWordPressExport(BASE_OPTS);

		expect(launch).toHaveBeenCalledTimes(2);
		expect(launch).toHaveBeenNthCalledWith(1, { headless: true });
		expect(launch).toHaveBeenNthCalledWith(2, { headless: false });

		const allWrites = stderrWrite.mock.calls.map((c) => String(c[0])).join("");
		expect(allWrites).toContain(
			"[astropress] Bot detection or CAPTCHA triggered in headless mode.",
		);
		expect(allWrites).toContain(
			"[astropress] Opening a visible browser — please solve any challenge that appears,",
		);
		expect(allWrites).toContain("[astropress] then the export will continue automatically.");
		stderrWrite.mockRestore();
	});

	it("does NOT retry when the headless attempt throws a non-bot-detection error", async () => {
		const launch = vi.mocked(chromium.launch);
		mocks.page.goto.mockRejectedValue(new Error("net::ERR_NAME_NOT_RESOLVED"));
		await expect(fetchWordPressExport(BASE_OPTS)).rejects.toBeInstanceOf(SiteNotReachableError);
		expect(launch).toHaveBeenCalledTimes(1);
	});
});

tests/integrations/oauth/seal-callback.t.source:
/**
 * Security-critical tests for the OAuth callback persistence half.
 *
 * Two layers are exercised here:
 *
 *   1. {@link sealOAuthCallbackTokens} as a unit — driven against an
 *      in-memory SQLite IntegrationsRepository (the same one production
 *      uses for the local-store path). These tests prove that on the
 *      happy path the *exact* token field set lands in
 *      `integration_secrets` under the verified `(domain, provider)`
 *      context, and that on every failure path no token byte escapes
 *      the helper.
 *
 *   2. The Astro APIRoute `GET` at
 *      `pages/ap-admin/oauth/callback/[provider].ts` driven through a
 *      mocked `loadLocalAdminStore` + mocked `fetch` so we can assert
 *      the route as a whole — including the redirect — never embeds
 *      a token in the response.
 *
 * These tests are deliberately verbose: each negative path is a
 * separate `it` block so a future regression that, say, starts echoing
 * the structured error code with `result.tokens.accessToken`
 * concatenated will be reported as exactly one targeted failure.
 *
 * Plaintext-leak invariants — repeated across every negative-path
 * test — are the core security guarantee. The CANARY strings are
 * wired through `OAuthTokenSet` so a single grep over the response
 * body / redirect URL is sufficient to detect leakage of *any*
 * token field.
 */

import type { DatabaseSync } from "node:sqlite";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

// `vi.mock` is hoisted to the top of the module, so any state it
// captures must come from `vi.hoisted` — that runs first.
const mockState = vi.hoisted(() => ({
	store: { integrations: undefined } as {
		integrations:
			| import("../../../src/sqlite-runtime/integrations").IntegrationsRepository
			| undefined;
	},
}));
vi.mock("../../../src/local-runtime-modules", () => ({
	loadLocalAdminStore: async () => mockState.store,
}));
vi.mock("../../../src/local-runtime-modules.js", () => ({
	loadLocalAdminStore: async () => mockState.store,
}));

import { issueOAuthState } from "../../../index";
// Imported after the mock so the route's transitive imports of
// `local-runtime-modules` resolve to our hoisted stub.
import { GET } from "../../../pages/ap-admin/oauth/callback/[provider].js";
import {
	_resetOAuthRegistryForTests,
	type OAuthProviderDefinition,
	registerOAuthProvider,
} from "../../../src/integrations/oauth/registry";
import {
	type SealOAuthCallbackResult,
	sealOAuthCallbackTokens,
	tokensToSecretFields,
} from "../../../src/integrations/oauth/seal-callback";
import type { OAuthTokenSet } from "../../../src/integrations/oauth/token-exchange";
import {
	createIntegrationsRepository,
	type IntegrationsRepository,
} from "../../../src/sqlite-runtime/integrations";
import { makeDb } from "../../helpers/make-db.js";
import { SqliteBackedD1Database } from "../../helpers/provider-test-fixtures.js";

// -----------------------------------------------------------------------------
// CANARIES — every leak assertion below scans for these literals. Keep them
// distinctive so a future grep-based regression check can find them too.
// -----------------------------------------------------------------------------
const CANARY_ACCESS = "CANARY-access-9f3a2d1c";
const CANARY_REFRESH = "CANARY-refresh-7b8e4f6a";
const CANARY_SCOPE = "CANARY-scope-read:write";
const ROOT = "test-root-current";
const PREV_ROOT = "test-root-previous";
const NOW = "2026-05-18T12:00:00.000Z";
const DOMAIN = "newsletter";
const PROVIDER_ID = "listmonk";

const TOKENS: OAuthTokenSet = {
	accessToken: CANARY_ACCESS,
	tokenType: "Bearer",
	refreshToken: CANARY_REFRESH,
	expiresIn: 3600,
	scope: CANARY_SCOPE,
};

function assertNoTokenLeak(haystack: string): void {
	expect(haystack).not.toContain(CANARY_ACCESS);
	expect(haystack).not.toContain(CANARY_REFRESH);
	expect(haystack).not.toContain(CANARY_SCOPE);
}

const REGISTERED_PROVIDER: OAuthProviderDefinition = {
	id: PROVIDER_ID,
	domain: DOMAIN,
	label: "Listmonk OAuth",
	authorizationUrl: "https://idp.example.test/authorize",
	tokenUrl: "https://idp.example.test/token",
	scopes: ["read:subs"],
	clientIdEnv: "LISTMONK_OAUTH_CLIENT_ID",
	clientSecretEnv: "LISTMONK_OAUTH_CLIENT_SECRET",
	redirectPath: "/ap-admin/oauth/callback/listmonk",
};

let db: DatabaseSync;
let repo: IntegrationsRepository;

beforeEach(() => {
	db = makeDb();
	db.exec("PRAGMA foreign_keys = ON");
	repo = createIntegrationsRepository({
		getDb: () => db as never,
		now: () => NOW,
	});
	mockState.store = { integrations: repo };
	_resetOAuthRegistryForTests();
	registerOAuthProvider(REGISTERED_PROVIDER);
});

afterEach(() => {
	_resetOAuthRegistryForTests();
	vi.unstubAllGlobals();
});

// -----------------------------------------------------------------------------
// Layer 1: helper-level tests
// -----------------------------------------------------------------------------

describe("tokensToSecretFields", () => {
	it("projects every OAuthTokenSet field that is present", () => {
		expect(tokensToSecretFields(TOKENS)).toEqual({
			accessToken: CANARY_ACCESS,
			tokenType: "Bearer",
			refreshToken: CANARY_REFRESH,
			expiresIn: "3600",
			scope: CANARY_SCOPE,
		});
	});

	it("omits optional fields when absent (no 'undefined' literal sealed)", () => {
		const fields = tokensToSecretFields({
			accessToken: CANARY_ACCESS,
			tokenType: "Bearer",
		});
		expect(fields).toEqual({ accessToken: CANARY_ACCESS, tokenType: "Bearer" });
		expect("refreshToken" in fields).toBe(false);
		expect("expiresIn" in fields).toBe(false);
		expect("scope" in fields).toBe(false);
	});

	it("stringifies expiresIn so the secret store sees Record<string,string>", () => {
		const fields = tokensToSecretFields({
			accessToken: CANARY_ACCESS,
			tokenType: "Bearer",
			expiresIn: 0,
		});
		// Even the falsy 0 must be preserved as "0" — a regression that drops
		// expiresIn when it equals zero would silently lose expiry telemetry.
		expect(fields.expiresIn).toBe("0");
	});
});

describe("sealOAuthCallbackTokens — helper-level success", () => {
	it("persists a sealed row that round-trips to the exact token field set", async () => {
		const result = await sealOAuthCallbackTokens(undefined, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		expect(result).toEqual({ ok: true });

		const opened = await repo.findSecret(DOMAIN, PROVIDER_ID, { current: ROOT });
		expect(opened).toEqual({
			accessToken: CANARY_ACCESS,
			tokenType: "Bearer",
			refreshToken: CANARY_REFRESH,
			expiresIn: "3600",
			scope: CANARY_SCOPE,
		});

		const status = repo.findStatus(DOMAIN, PROVIDER_ID);
		expect(status).toMatchObject({
			domain: DOMAIN,
			provider: PROVIDER_ID,
			status: "connected",
			connectedAt: NOW,
			// configJson must be the literal "{}" — the row is OAuth-managed
			// and has no per-host provider config; a regression that wrote
			// e.g. "" would still be valid JSON-ish but break the runtime
			// JSON.parse path on read.
			configJson: "{}",
		});
	});

	it("never writes the plaintext access token into any column", async () => {
		await sealOAuthCallbackTokens(undefined, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		const allRows = [
			...(db.prepare("SELECT * FROM connected_integrations").all() as Record<string, unknown>[]),
			...(db.prepare("SELECT * FROM integration_secrets").all() as Record<string, unknown>[]),
		];
		assertNoTokenLeak(JSON.stringify(allRows));
	});

	it("rotation: a row sealed under PREV_ROOT is opened and resealed under ROOT", async () => {
		// 1. Seal under PREV_ROOT, then flip the row's kid to mimic a
		//    pre-rotation record — matches integrations-repository.test
		//    rotation pattern.
		await sealOAuthCallbackTokens(undefined, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: PREV_ROOT,
			now: NOW,
		});
		db.prepare("UPDATE integration_secrets SET kid='previous' WHERE domain=? AND provider=?").run(
			DOMAIN,
			PROVIDER_ID,
		);

		// 2. findSecret with {current: ROOT, previous: PREV_ROOT}: the
		//    "previous" candidate decrypts and reseal-on-read upgrades.
		const opened = await repo.findSecret(DOMAIN, PROVIDER_ID, {
			current: ROOT,
			previous: PREV_ROOT,
		});
		expect(opened).toMatchObject({ accessToken: CANARY_ACCESS });

		const after = db
			.prepare("SELECT kid FROM integration_secrets WHERE domain=? AND provider=?")
			.get(DOMAIN, PROVIDER_ID) as { kid: string };
		expect(after.kid).toBe("current");
	});
});

describe("sealOAuthCallbackTokens — failure paths never leak tokens", () => {
	it("returns INTEGRATIONS_NOT_AVAILABLE when the local store has no integrations repo", async () => {
		mockState.store = { integrations: undefined };
		const result = await sealOAuthCallbackTokens(undefined, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		expect(result).toEqual({ ok: false, code: "INTEGRATIONS_NOT_AVAILABLE" });
		assertNoTokenLeak(JSON.stringify(result));
	});

	it("returns SEAL_FAILED when repo.connect throws, with no token bytes in the result", async () => {
		const throwingRepo: IntegrationsRepository = {
			...repo,
			connect: async () => {
				// Deliberately include the access-token canary in the
				// thrown message — the helper must NOT surface it.
				throw new Error(`db write failed for token=${CANARY_ACCESS}`);
			},
		};
		mockState.store = { integrations: throwingRepo };

		const result: SealOAuthCallbackResult = await sealOAuthCallbackTokens(undefined, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		expect(result).toEqual({ ok: false, code: "SEAL_FAILED" });
		assertNoTokenLeak(JSON.stringify(result));
	});

	it("D1 path: seal lands in the D1-backed integration_secrets row atomically", async () => {
		// Live D1-shape database (sqlite-backed) so the onD1 branch
		// runs to completion. The batched connect must write both the
		// status row and the sealed-secret row.
		const d1Db = new SqliteBackedD1Database(db);
		const localsWithD1 = { runtime: { env: { DB: d1Db } } } as unknown as App.Locals;
		const result = await sealOAuthCallbackTokens(localsWithD1, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		expect(result).toEqual({ ok: true });
		// Roundtrip via the sqlite repo (same underlying tables) to
		// confirm the D1 write produced an openable envelope.
		const opened = await repo.findSecret(DOMAIN, PROVIDER_ID, { current: ROOT });
		expect(opened).toMatchObject({ accessToken: CANARY_ACCESS });
		// configJson pin (same invariant as the local-store path):
		// OAuth-managed rows have no provider-supplied config, so the
		// status row must hold the literal "{}". A regression that
		// wrote `""` here would corrupt later JSON.parse reads.
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)?.configJson).toBe("{}");
		assertNoTokenLeak(JSON.stringify(result));
	});

	it("D1 path: SEAL_FAILED when the batch fails — no token bytes in the result", async () => {
		const localsWithD1 = {
			runtime: {
				env: {
					DB: {
						prepare: () => ({
							bind: () => ({
								first: async () => null,
								all: async () => ({ success: true, results: [] }),
								run: async () => {
									throw new Error(`d1 batch failed for token=${CANARY_ACCESS}`);
								},
							}),
						}),
						batch: async () => {
							throw new Error(`d1 batch failed for token=${CANARY_ACCESS}`);
						},
					},
				},
			},
		} as unknown as App.Locals;
		const result = await sealOAuthCallbackTokens(localsWithD1, {
			domain: DOMAIN,
			provider: PROVIDER_ID,
			tokens: TOKENS,
			rootSecret: ROOT,
			now: NOW,
		});
		expect(result).toEqual({ ok: false, code: "SEAL_FAILED" });
		assertNoTokenLeak(JSON.stringify(result));
	});
});

// -----------------------------------------------------------------------------
// Layer 2: end-to-end through the Astro APIRoute GET handler
// -----------------------------------------------------------------------------

function makeLocals(overrides?: Partial<Record<string, string>>): App.Locals {
	return {
		runtime: {
			env: {
				ASTROPRESS_ROOT_SECRET: ROOT,
				LISTMONK_OAUTH_CLIENT_ID: "cid-test",
				LISTMONK_OAUTH_CLIENT_SECRET: "csec-test",
				...overrides,
			},
		},
	} as unknown as App.Locals;
}

async function buildContext(opts: {
	stateToken?: string;
	code?: string;
	providerSlug?: string;
	locals?: App.Locals;
}) {
	const url = new URL(
		`https://host.example.test/ap-admin/oauth/callback/${opts.providerSlug ?? "listmonk"}?code=${
			opts.code ?? "code-abc"
		}&state=${opts.stateToken ?? ""}`,
	);
	const redirects: string[] = [];
	const redirect = (path: string) => {
		redirects.push(path);
		return new Response(null, { status: 302, headers: { Location: path } });
	};
	const context = {
		url,
		params: { provider: opts.providerSlug ?? "listmonk" },
		locals: opts.locals ?? makeLocals(),
		redirect,
	};
	return { context, redirects };
}

function mockTokenExchangeFetch(tokens: OAuthTokenSet | "network-error" | { status: number }) {
	const fetchMock = vi.fn(async () => {
		if (tokens === "network-error") {
			throw new Error("ECONNREFUSED");
		}
		if (typeof tokens === "object" && "status" in tokens) {
			return new Response("err", { status: tokens.status });
		}
		const body: Record<string, unknown> = {
			access_token: tokens.accessToken,
			token_type: tokens.tokenType,
		};
		if (tokens.refreshToken) body.refresh_token = tokens.refreshToken;
		if (tokens.expiresIn !== undefined) body.expires_in = tokens.expiresIn;
		if (tokens.scope) body.scope = tokens.scope;
		return new Response(JSON.stringify(body), {
			status: 200,
			headers: { "Content-Type": "application/json" },
		});
	});
	vi.stubGlobal("fetch", fetchMock);
	return fetchMock;
}

async function makeValidState(overrides?: { providerId?: string; domain?: string }) {
	const issued = await issueOAuthState({
		context: {
			domain: overrides?.domain ?? DOMAIN,
			providerId: overrides?.providerId ?? PROVIDER_ID,
			returnTo: "/ap-admin/services",
		},
		rootSecret: ROOT,
		nowMs: Date.now(),
	});
	return issued.token;
}

describe("ap-admin/oauth/callback/[provider] GET — security regression suite", () => {
	it("happy path: persists the sealed row and redirects to returnTo with no token in the URL", async () => {
		mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const { context, redirects } = await buildContext({ stateToken: state });

		const response = await GET(context as never);
		expect(response.status).toBe(302);
		expect(redirects).toHaveLength(1);

		// Redirect target must NOT contain any token field — neither
		// as a query param nor anywhere in the URL.
		assertNoTokenLeak(redirects[0]);
		// The legacy `oauth_pending_seal` query flag must be gone — the
		// issue's acceptance criterion explicitly requires it removed.
		expect(redirects[0]).not.toContain("oauth_pending_seal");
		expect(redirects[0]).toBe("/ap-admin/services");

		// Row in DB matches the token set we mocked back from fetch.
		const opened = await repo.findSecret(DOMAIN, PROVIDER_ID, { current: ROOT });
		expect(opened).toMatchObject({ accessToken: CANARY_ACCESS });
	});

	it("seal failure surfaces 500 with the structured code and zero token bytes in the body", async () => {
		mockState.store = {
			integrations: {
				...repo,
				connect: async () => {
					throw new Error(`db unavailable, token=${CANARY_ACCESS}`);
				},
			},
		};
		mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state });

		const response = await GET(context as never);
		expect(response.status).toBe(500);
		const body = await response.text();
		expect(body).toContain("SEAL_FAILED");
		assertNoTokenLeak(body);
	});

	it("INTEGRATIONS_NOT_AVAILABLE: 500 with code, no token bytes in body, no DB write", async () => {
		mockState.store = { integrations: undefined };
		mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state });

		const response = await GET(context as never);
		expect(response.status).toBe(500);
		const body = await response.text();
		expect(body).toContain("INTEGRATIONS_NOT_AVAILABLE");
		assertNoTokenLeak(body);
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
	});

	it("state token missing → 400, never invokes fetch", async () => {
		const fetchMock = mockTokenExchangeFetch(TOKENS);
		const { context } = await buildContext({ stateToken: "" });
		const response = await GET(context as never);
		expect(response.status).toBe(400);
		expect(fetchMock).not.toHaveBeenCalled();
		assertNoTokenLeak(await response.text());
	});

	it("state token forged (bad signature) → 400, never invokes fetch, never seals", async () => {
		const fetchMock = mockTokenExchangeFetch(TOKENS);
		const forged = Buffer.from(
			JSON.stringify({
				n: "abc",
				c: { domain: DOMAIN, providerId: PROVIDER_ID, returnTo: "/x" },
				e: Date.now() + 60_000,
				s: "deadbeef",
			}),
			"utf-8",
		).toString("hex");
		const { context } = await buildContext({ stateToken: forged });
		const response = await GET(context as never);
		expect(response.status).toBe(400);
		expect(fetchMock).not.toHaveBeenCalled();
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
		assertNoTokenLeak(await response.text());
	});

	it("provider slug mismatch (state says listmonk, URL says github) → 404, never seals", async () => {
		const fetchMock = mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state, providerSlug: "github" });
		const response = await GET(context as never);
		expect(response.status).toBe(404);
		expect(fetchMock).not.toHaveBeenCalled();
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
		assertNoTokenLeak(await response.text());
	});

	it("missing client credentials → 500, never invokes fetch, never seals", async () => {
		const fetchMock = mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const localsNoCreds = {
			runtime: { env: { ASTROPRESS_ROOT_SECRET: ROOT } },
		} as unknown as App.Locals;
		const { context } = await buildContext({ stateToken: state, locals: localsNoCreds });
		const response = await GET(context as never);
		expect(response.status).toBe(500);
		expect(fetchMock).not.toHaveBeenCalled();
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
		assertNoTokenLeak(await response.text());
	});

	it("token-exchange 5xx → 502, never seals (no partial state in DB)", async () => {
		mockTokenExchangeFetch({ status: 502 });
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state });
		const response = await GET(context as never);
		expect(response.status).toBe(502);
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
		assertNoTokenLeak(await response.text());
	});

	it("token-exchange network error → 502, never seals", async () => {
		mockTokenExchangeFetch("network-error");
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state });
		const response = await GET(context as never);
		expect(response.status).toBe(502);
		expect(repo.findStatus(DOMAIN, PROVIDER_ID)).toBeUndefined();
		assertNoTokenLeak(await response.text());
	});

	it("after a successful seal, findSecret roundtrips the access token (no plaintext leak path)", async () => {
		mockTokenExchangeFetch(TOKENS);
		const state = await makeValidState();
		const { context } = await buildContext({ stateToken: state });
		await GET(context as never);

		const opened = await repo.findSecret<Record<string, string>>(DOMAIN, PROVIDER_ID, {
			current: ROOT,
		});
		expect(opened?.accessToken).toBe(CANARY_ACCESS);
		expect(opened?.refreshToken).toBe(CANARY_REFRESH);

		// Belt and braces: a raw row scan must not contain any canary
		// even though decryption succeeded.
		const dump = JSON.stringify(
			db.prepare("SELECT * FROM integration_secrets").all() as Record<string, unknown>[],
		);
		assertNoTokenLeak(dump);
	});
});

