describe("mapContentState", () => {
	it("merges override fields over the page record while preserving non-overridden ones", () => {
		const page: PageRecord = {
			slug: "p",
			legacyUrl: "/p",
			title: "Original",
			sourceHtmlPath: "runtime://content/p",
