	});

	it("returns null when contentType is matched and validation passes", () => {
		registerCms({
			...STANDARD_CMS_CONFIG,
			contentTypes: [
				{
					key: "recipe",
					label: "Recipe",
					fields: [{ name: "servings", label: "Servings", type: "number", required: true }],
