import { readFileSync } from "node:fs";
import path from "node:path";
import type { DatabaseSync } from "node:sqlite";
import { describe, expect, it, vi } from "vitest";
import type { ContentTypeDefinition, FieldDefinition } from "../src/content-modeling.js";
import { validateContentFields } from "../src/content-modeling.js";
import { createSqliteContentStore } from "../src/sqlite-runtime/content.js";
import { makeDb } from "./helpers/make-db.js";

// ─── FieldDefinition new types — structural ───────────────────────────────────

describe("FieldDefinition — new types (structural)", () => {
	it("accepts content-ref type", () => {
		const field: FieldDefinition = {
			name: "relatedPost",
			label: "Related Post",
			type: "content-ref",
			refKind: "post",
		};
		expect(field.type).toBe("content-ref");
		expect(field.refKind).toBe("post");
	});

	it("accepts repeater type with nested fields", () => {
		const field: FieldDefinition = {
			name: "links",
			label: "Links",
			type: "repeater",
			fields: [
				{ name: "href", label: "URL", type: "url", required: true },
				{ name: "label", label: "Label", type: "text" },
			],
		};
		expect(field.type).toBe("repeater");
		expect(field.fields).toHaveLength(2);
	});

	it("accepts conditionalOn visibility rule", () => {
		const field: FieldDefinition = {
			name: "calloutText",
			label: "Callout Text",
			type: "text",
			conditionalOn: { field: "showCallout", equals: true },
		};
		expect(field.conditionalOn?.field).toBe("showCallout");
		expect(field.conditionalOn?.equals).toBe(true);
	});
});

// ─── validateContentFields — content-ref ─────────────────────────────────────

describe("validateContentFields — content-ref type", () => {
	const contentType: ContentTypeDefinition = {
		key: "article",
		label: "Article",
		fields: [{ name: "relatedPost", label: "Related Post", type: "content-ref" }],
	};

	it("passes when value is a string slug", () => {
		expect(validateContentFields(contentType, { relatedPost: "my-post" })).toBeNull();
	});

	it("fails when value is a number (not a slug string)", () => {
		const error = validateContentFields(contentType, { relatedPost: 42 });
		expect(error).toContain("must be a content slug string");
	});

	it("passes when field is not required and empty", () => {
		expect(validateContentFields(contentType, {})).toBeNull();
	});

	it("fails required content-ref when empty", () => {
		const requiredType: ContentTypeDefinition = {
			key: "article",
			label: "Article",
			fields: [
				{
					name: "relatedPost",
					label: "Related Post",
					type: "content-ref",
					required: true,
				},
			],
		};
		const error = validateContentFields(requiredType, {});
		expect(error).toContain("is required");
	});
});

// ─── validateContentFields — repeater type ───────────────────────────────────

describe("validateContentFields — repeater type", () => {
	const contentType: ContentTypeDefinition = {
		key: "event",
		label: "Event",
		fields: [
			{
				name: "speakers",
				label: "Speakers",
				type: "repeater",
				fields: [
					{ name: "name", label: "Name", type: "text", required: true },
					{ name: "bio", label: "Bio", type: "textarea" },
				],
			},
		],
	};

	it("passes when value is a valid array of objects", () => {
		expect(
			validateContentFields(contentType, {
				speakers: [{ name: "Alice", bio: "Engineer" }],
			}),
		).toBeNull();
	});

	it("passes when repeater is empty array", () => {
		expect(validateContentFields(contentType, { speakers: [] })).toBeNull();
	});

	it("fails when value is not an array", () => {
		const error = validateContentFields(contentType, {
			speakers: "not-an-array",
		});
		expect(error).toContain("must be an array");
	});

	it("fails when nested required field is missing", () => {
		const error = validateContentFields(contentType, {
			speakers: [{ bio: "Engineer" }],
		});
		expect(error).toContain("is required");
		expect(error).toContain("speakers[0]");
	});

	it("passes when field is not required and absent", () => {
		expect(validateContentFields(contentType, {})).toBeNull();
	});
});

// ─── SQLite metadata persistence ─────────────────────────────────────────────

describe("SQLite upsertContentOverride — metadata persistence", () => {
	function makeStore(db: DatabaseSync) {
		let id = 0;
		const { sqliteContentRepository } = createSqliteContentStore(
			() => db,
			() => `rec_${++id}`,
		);
		return sqliteContentRepository;
	}

	function getStoredMetadata(db: DatabaseSync, slug: string): Record<string, unknown> | null {
		const row = db
			.prepare("SELECT metadata FROM content_overrides WHERE slug = ? LIMIT 1")
			.get(slug) as { metadata: string | null } | undefined;
		if (!row?.metadata) return null;
		return JSON.parse(row.metadata) as Record<string, unknown>;
	}

	function seedEntry(db: DatabaseSync, slug: string) {
		db.prepare(
			`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
       VALUES (?, ?, ?, 'post', 'content', 'runtime://content/' || ?, CURRENT_TIMESTAMP)`,
		).run(slug, `/${slug}`, `Title for ${slug}`, slug);
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, seo_title, meta_description, updated_at, updated_by)
       VALUES (?, ?, 'draft', ?, '', CURRENT_TIMESTAMP, 'seed@test.com')`,
		).run(slug, `Title for ${slug}`, `Title for ${slug}`);
	}

	it("persists metadata through upsert and returns it on read", () => {
		const db = makeDb();
		seedEntry(db, "test-post");
		const store = makeStore(db);

		const actor = {
			email: "editor@test.com",
			role: "admin" as const,
			name: "Editor",
		};
		store.saveContentState(
			"test-post",
			{
				title: "Test Post",
				status: "draft",
				seoTitle: "Test Post SEO",
				metaDescription: "A test post",
				metadata: { relatedPost: "other-post", speakers: [{ name: "Alice" }] },
			},
			actor,
		);

		const metadata = getStoredMetadata(db, "test-post");
		expect(metadata).not.toBeNull();
		expect(metadata).toEqual({
			relatedPost: "other-post",
			speakers: [{ name: "Alice" }],
		});
	});

	it("stores null metadata when not provided", () => {
		const db = makeDb();
		seedEntry(db, "no-meta-post");
		const store = makeStore(db);

		const actor = {
			email: "editor@test.com",
			role: "admin" as const,
			name: "Editor",
		};
		store.saveContentState(
			"no-meta-post",
			{
				title: "No Meta Post",
				status: "draft",
				seoTitle: "No Meta",
				metaDescription: "desc",
			},
			actor,
		);

		const metadata = getStoredMetadata(db, "no-meta-post");
		expect(metadata).toBeNull();
	});

	it("updates metadata on subsequent upsert", () => {
		const db = makeDb();
		seedEntry(db, "update-meta-post");
		const store = makeStore(db);

		const actor = {
			email: "editor@test.com",
			role: "admin" as const,
			name: "Editor",
		};
		store.saveContentState(
			"update-meta-post",
			{
				title: "Post",
				status: "draft",
				seoTitle: "Post",
				metaDescription: "desc",
				metadata: { version: 1 },
			},
			actor,
		);
		store.saveContentState(
			"update-meta-post",
			{
				title: "Post",
				status: "draft",
				seoTitle: "Post",
				metaDescription: "desc",
				metadata: { version: 2 },
			},
			actor,
		);

		const metadata = getStoredMetadata(db, "update-meta-post");
		expect((metadata as Record<string, unknown>)?.version).toBe(2);
	});
});

// ─── validateContentFields — validate() callback ─────────────────────────────

describe("validateContentFields — validate() callback", () => {
	it("passes when validate returns true", () => {
		const contentType: ContentTypeDefinition = {
			key: "test",
			label: "Test",
			fields: [{ name: "score", label: "Score", type: "number", validate: () => true }],
		};
		expect(validateContentFields(contentType, { score: 42 })).toBeNull();
	});

	it("passes when validate returns empty string (falsy → treated as no error)", () => {
		const contentType: ContentTypeDefinition = {
			key: "test",
			label: "Test",
			fields: [{ name: "score", label: "Score", type: "number", validate: () => "" }],
		};
		expect(validateContentFields(contentType, { score: 42 })).toBeNull();
	});

	it("fails when validate returns a non-empty error string", () => {
		const contentType: ContentTypeDefinition = {
			key: "test",
			label: "Test",
			fields: [
				{
					name: "score",
					label: "Score",
					type: "number",
					validate: () => "Must be positive.",
				},
			],
		};
		expect(validateContentFields(contentType, { score: -1 })).toBe("Must be positive.");
	});

	it("skips validate when value is empty and field is not required", () => {
		const validate = vi.fn(() => "Should not be called");
		const contentType: ContentTypeDefinition = {
			key: "test",
			label: "Test",
			fields: [{ name: "score", label: "Score", type: "number", validate }],
		};
		expect(validateContentFields(contentType, {})).toBeNull();
		expect(validate).not.toHaveBeenCalled();
	});
});

// ─── validateContentFields — repeater null item ───────────────────────────────

describe("validateContentFields — repeater null item check", () => {
	const contentType: ContentTypeDefinition = {
		key: "test",
		label: "Test",
		fields: [
			{
				name: "items",
				label: "Items",
				type: "repeater",
				fields: [{ name: "name", label: "Name", type: "text", required: true }],
			},
		],
	};

	it("fails when a repeater item is null", () => {
		const error = validateContentFields(contentType, { items: [null] });
		expect(error).toContain("item 1 must be an object");
	});

	it("fails when a repeater item is a primitive (string)", () => {
		const error = validateContentFields(contentType, {
			items: ["not-an-object"],
		});
		expect(error).toContain("item 1 must be an object");
	});

	it("uses 1-based index in error message (second item)", () => {
		const error = validateContentFields(contentType, {
			items: [{ name: "ok" }, null],
		});
		expect(error).toContain("item 2 must be an object");
	});

	it("passes repeater with no nested field definitions (fields property absent)", () => {
		const noFieldsType: ContentTypeDefinition = {
			key: "test",
			label: "Test",
			fields: [{ name: "tags", label: "Tags", type: "repeater" }],
		};
		expect(validateContentFields(noFieldsType, { tags: [{ anything: true }] })).toBeNull();
	});
});

// ─── validateContentFields — required + isEmpty boundary ─────────────────────

describe("validateContentFields — required field isEmpty cases", () => {
	function requiredField(name: string): ContentTypeDefinition {
		return {
			key: "test",
			label: "Test",
			fields: [{ name, label: "Field", type: "text", required: true }],
		};
	}

	it("treats undefined as empty", () => {
		expect(validateContentFields(requiredField("x"), {})).toContain("is required");
	});

	it("treats null as empty", () => {
		expect(validateContentFields(requiredField("x"), { x: null })).toContain("is required");
	});

	it("treats empty string as empty", () => {
		expect(validateContentFields(requiredField("x"), { x: "" })).toContain("is required");
	});

	it("accepts zero as non-empty (0 is a valid value)", () => {
		expect(validateContentFields(requiredField("x"), { x: 0 })).toBeNull();
	});

	it("accepts false as non-empty (false is a valid boolean value)", () => {
		expect(validateContentFields(requiredField("x"), { x: false })).toBeNull();
	});
});

// ─── sqlite-runtime/content survivor pins ─────────────────────────────────────

describe("sqlite-runtime/content survivor pins", () => {
	function makeRepo(db: DatabaseSync) {
		let id = 0;
		const { sqliteContentRepository } = createSqliteContentStore(
			() => db,
			() => `rev_${++id}`,
		);
		return sqliteContentRepository;
	}

	it("findPageRecord resolves a slug via legacyUrl when entry.slug does not match (pins L46 ||/=== `/${slug}`)", () => {
		const db = makeDb();
		db.prepare(
			`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
       VALUES (?, ?, ?, 'post', 'content', 'runtime://content/x', CURRENT_TIMESTAMP)`,
		).run("real-slug", "/alias-slug", "Title");
		db.prepare(
			`INSERT INTO content_overrides (slug, title, status, seo_title, meta_description, updated_at, updated_by)
       VALUES ('real-slug', 'Title', 'draft', 'T', '', CURRENT_TIMESTAMP, 'seed@test.com')`,
		).run();
		const repo = makeRepo(db);
		const state = repo.getContentState("alias-slug");
		expect(state).not.toBeNull();
		expect(state?.slug).toBe("real-slug");
	});

	it("saveContentState routes through insertReviewedRevision so a content_revisions row exists (pins L104 body block)", () => {
		const db = makeDb();
		db.prepare(
			`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
       VALUES ('rev-slug', '/rev-slug', 'Title', 'post', 'content', 'runtime://content/x', CURRENT_TIMESTAMP)`,
		).run();
		const repo = makeRepo(db);
		repo.saveContentState(
			"rev-slug",
			{
				title: "T",
				body: "body",
				status: "draft",
				seoTitle: "ST",
				metaDescription: "MD",
				excerpt: "",
				ogTitle: null,
				ogDescription: null,
				ogImage: null,
				canonicalUrlOverride: null,
				robotsDirective: null,
			},
			{ email: "e@x.com", role: "admin", name: "E" },
		);
		const count = (
			db.prepare("SELECT COUNT(*) as n FROM content_revisions WHERE slug = ?").get("rev-slug") as {
				n: number;
			}
		).n;
		expect(count).toBeGreaterThanOrEqual(1);
	});

	it("saveContentState routes through recordContentAudit so an audit_log row with target_type='content' exists (pins L110 body + L111 'content' literal)", () => {
		const db = makeDb();
		db.prepare(
			`INSERT INTO content_entries (slug, legacy_url, title, kind, template_key, source_html_path, updated_at)
       VALUES ('audit-slug', '/audit-slug', 'Title', 'post', 'content', 'runtime://content/x', CURRENT_TIMESTAMP)`,
		).run();
		const repo = makeRepo(db);
		repo.saveContentState(
			"audit-slug",
			{
				title: "T",
				body: "body",
				status: "draft",
				seoTitle: "ST",
				metaDescription: "MD",
				excerpt: "",
				ogTitle: null,
				ogDescription: null,
				ogImage: null,
				canonicalUrlOverride: null,
				robotsDirective: null,
			},
			{ email: "e@x.com", role: "admin", name: "E" },
		);
		const row = db
			.prepare(
				"SELECT resource_type FROM audit_events WHERE resource_type = 'content' ORDER BY id DESC LIMIT 1",
			)
			.get() as { resource_type: string } | undefined;
		expect(row?.resource_type).toBe("content");
	});
});

// ─── content-modeling.ts source structure ────────────────────────────────────

describe("content-modeling.ts — source structure", () => {
	const srcPath = path.resolve(import.meta.dirname, "../src/content-modeling.ts");

	it("exports FieldDefinition with content-ref type", () => {
		const source = readFileSync(srcPath, "utf8");
		expect(source).toContain('"content-ref"');
	});

	it("exports FieldDefinition with repeater type", () => {
		const source = readFileSync(srcPath, "utf8");
		expect(source).toContain('"repeater"');
	});

	it("exports FieldDefinition with conditionalOn property", () => {
		const source = readFileSync(srcPath, "utf8");
		expect(source).toContain("conditionalOn");
	});

	it("exports FieldDefinition with refKind property", () => {
		const source = readFileSync(srcPath, "utf8");
		expect(source).toContain("refKind");
	});

	it("exports FieldDefinition with fields property for repeater", () => {
		const source = readFileSync(srcPath, "utf8");
		expect(source).toContain("fields?: readonly FieldDefinition[]");
	});
});

tests/d1-store-operations-helpers.test.t.source:
import { describe, expect, it, vi } from "vitest";

import {
	type AdminUserRow,
	type AuditEventRow,
	bindTestimonialFilter,
	buildApprovedAtExpr,
	buildCommentBindParams,
	buildModerateSql,
	COMMENT_INSERT_SQL,
	CONTACT_INSERT_SQL,
	type CommentRow,
	deriveUserStatus,
	type MediaRow,
	mapAdminUserRow,
	mapAuditEventRow,
	mapCommentRow,
	mapContactRow,
	mapMediaRow,
	mapRedirectRow,
	mapSettingsRow,
	mapTestimonialRow,
	type SettingsRow,
	SQL_ADMIN_USERS,
	SQL_AUDIT_EVENTS,
	SQL_COMMENTS,
	SQL_CONTACT_SUBMISSIONS,
	SQL_MEDIA_ASSETS,
	SQL_REDIRECT_RULES,
	SQL_SITE_SETTINGS,
	SQL_TESTIMONIALS,
	SQL_TRANSLATION_STATE,
	TESTIMONIAL_INSERT_SQL,
	type TestimonialRow,
	testimonialInputBindParams,
} from "../src/d1-store-operations-helpers";
import {
	SQL_LIST_ADMIN_USERS_WITH_INVITE,
	SQL_LIST_AUDIT_EVENTS,
} from "../src/persistence-commons";

describe("D1 SQL constants", () => {
	it("SQL_AUDIT_EVENTS aliases the persistence-commons single source of truth", () => {
		expect(SQL_AUDIT_EVENTS).toBe(SQL_LIST_AUDIT_EVENTS);
	});

	it("SQL_ADMIN_USERS aliases the persistence-commons single source of truth", () => {
		expect(SQL_ADMIN_USERS).toBe(SQL_LIST_ADMIN_USERS_WITH_INVITE);
	});

	it("SQL_REDIRECT_RULES filters soft-deleted rules and orders by source_path", () => {
		expect(SQL_REDIRECT_RULES).toContain("FROM redirect_rules");
		expect(SQL_REDIRECT_RULES).toContain("deleted_at IS NULL");
		expect(SQL_REDIRECT_RULES).toMatch(/ORDER BY source_path ASC/);
	});

	it("SQL_COMMENTS orders pending → approved → other and then by submitted_at desc", () => {
		expect(SQL_COMMENTS).toContain("FROM comments");
		expect(SQL_COMMENTS).toContain(
			"CASE status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 ELSE 2 END",
		);
		expect(SQL_COMMENTS).toMatch(/datetime\(submitted_at\) DESC/);
	});

	it("SQL_CONTACT_SUBMISSIONS orders by submitted_at desc", () => {
		expect(SQL_CONTACT_SUBMISSIONS).toContain("FROM contact_submissions");
		expect(SQL_CONTACT_SUBMISSIONS).toMatch(/datetime\(submitted_at\) DESC/);
	});

	it("SQL_TESTIMONIALS uses a NULL-safe filter so optional status binds with two slots", () => {
		expect(SQL_TESTIMONIALS).toContain("FROM testimonial_submissions");
		expect(SQL_TESTIMONIALS).toContain("(? IS NULL OR status = ?)");
	});

	it("SQL_TRANSLATION_STATE selects state for a single route with LIMIT 1", () => {
		expect(SQL_TRANSLATION_STATE).toBe(
			"SELECT state FROM translation_overrides WHERE route = ? LIMIT 1",
		);
	});

	it("SQL_SITE_SETTINGS reads the singleton row id = 1", () => {
		expect(SQL_SITE_SETTINGS).toContain("FROM site_settings");
		expect(SQL_SITE_SETTINGS).toContain("WHERE id = 1");
		expect(SQL_SITE_SETTINGS).toContain("LIMIT 1");
	});

	it("SQL_MEDIA_ASSETS filters soft-deleted rows and orders newest first", () => {
		expect(SQL_MEDIA_ASSETS).toContain("FROM media_assets");
		expect(SQL_MEDIA_ASSETS).toContain("deleted_at IS NULL");
		expect(SQL_MEDIA_ASSETS).toMatch(/datetime\(uploaded_at\) DESC/);
	});

	it("TESTIMONIAL_INSERT_SQL hardcodes status='pending' (clients cannot self-approve)", () => {
		expect(TESTIMONIAL_INSERT_SQL).toContain("INSERT INTO testimonial_submissions");
		expect(TESTIMONIAL_INSERT_SQL).toContain("'pending'");
	});

	it("CONTACT_INSERT_SQL writes exactly the five expected columns", () => {
		expect(CONTACT_INSERT_SQL).toBe(
			"INSERT INTO contact_submissions (id, name, email, message, submitted_at)\n   VALUES (?, ?, ?, ?, ?)",
		);
	});

	it("COMMENT_INSERT_SQL writes exactly the eight expected columns", () => {
		expect(COMMENT_INSERT_SQL).toBe(
			"INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)\n   VALUES (?, ?, ?, ?, ?, ?, ?, ?)",
		);
	});
});

describe("mapAuditEventRow", () => {
	const row: AuditEventRow = {
		id: 7,
		user_email: "ada@example.test",
		action: "publish",
		resource_type: "content",
		resource_id: "post-1",
		summary: "Published",
		created_at: "2026-04-25T00:00:00Z",
	};

	it("namespaces id with the d1-audit- prefix to avoid SQLite collisions", () => {
		expect(mapAuditEventRow(row).id).toBe("d1-audit-7");
	});

	it("falls back to 'auth' for unknown resource_type values", () => {
		expect(mapAuditEventRow({ ...row, resource_type: "session" }).targetType).toBe("auth");
	});

	it("uses stringified id when resource_id is null", () => {
		expect(mapAuditEventRow({ ...row, resource_id: null }).targetId).toBe("7");
	});
});

describe("deriveUserStatus + mapAdminUserRow", () => {
	const row: AdminUserRow = {
		id: 3,
		email: "ada@example.test",
		role: "admin",
		name: "Ada",
		active: 1,
		created_at: "2026-04-25T00:00:00Z",
		has_pending_invite: 0,
	};

	it("derives 'active' / 'invited' / 'suspended' correctly", () => {
		expect(deriveUserStatus(1, 0)).toBe("active");
		expect(deriveUserStatus(1, 1)).toBe("invited");
		expect(deriveUserStatus(0, 0)).toBe("suspended");
		expect(deriveUserStatus(0, 1)).toBe("suspended");
	});

	it("maps active=1 to boolean true and surfaces status='active'", () => {
		const mapped = mapAdminUserRow(row);
		expect(mapped.active).toBe(true);
		expect(mapped.status).toBe("active");
	});

	it("maps inactive (active=0) to boolean false and status='suspended'", () => {
		const mapped = mapAdminUserRow({ ...row, active: 0 });
		expect(mapped.active).toBe(false);
		expect(mapped.status).toBe("suspended");
	});
});

describe("mapCommentRow", () => {
	const row: CommentRow = {
		id: "c-1",
		author: "Ada",
		email: "ada@example.test",
		body: "Nice post",
		route: "/hello",
		status: "approved",
		policy: "open-moderated",
		submitted_at: "2026-04-25T00:00:00Z",
	};

	it("preserves required fields and renames submitted_at → submittedAt", () => {
		const mapped = mapCommentRow(row);
		expect(mapped).toEqual({
			id: "c-1",
			author: "Ada",
			email: "ada@example.test",
