		expect(result.ok).toBe(true);
		expect(result.route).toEqual({
			path: "/echo",
			title: "T",
			summary: undefined,
			seoTitle: "T",
			metaDescription: "T",
			canonicalUrlOverride: undefined,
			robotsDirective: undefined,
			ogImage: undefined,
			templateKey: "content",
			alternateLinks: [],
			sections: null,
