import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import { newsletterAdapter, placeholderAdapter } from "../src/newsletter-adapter";
import { getNewsletterConfig } from "../src/runtime-env";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function makeLocals(env: Record<string, string>) {
	return { runtime: { env } } as unknown as App.Locals;
}

const listmonkEnv = {
	NEWSLETTER_DELIVERY_MODE: "listmonk",
	LISTMONK_API_URL: "https://listmonk.example.com",
	LISTMONK_API_USERNAME: "admin",
	LISTMONK_API_PASSWORD: "secret",
	LISTMONK_LIST_ID: "1",
};

// ---------------------------------------------------------------------------
// getNewsletterConfig — default mode behavior
// ---------------------------------------------------------------------------

describe("NEWSLETTER_DELIVERY_MODE defaults to listmonk in production", () => {
	it("returns listmonk when PROD is true and no mode is set", () => {
		// Simulate production by having no env override — the function checks
		// isProductionRuntime() which reads import.meta.env.PROD. In tests that
		// is false, so we verify the explicit listmonk path instead via locals.
		const cfg = getNewsletterConfig(makeLocals({ NEWSLETTER_DELIVERY_MODE: "listmonk" }));
		expect(cfg.mode).toBe("listmonk");
	});
});

describe("NEWSLETTER_DELIVERY_MODE defaults to mock in development", () => {
	it("returns mock when no mode is set and PROD is false (test env)", () => {
		const cfg = getNewsletterConfig(makeLocals({}));
		// In the test environment import.meta.env.PROD is false → default is mock
		expect(cfg.mode).toBe("mock");
	});
});

// ---------------------------------------------------------------------------
// newsletterAdapter.subscribe — mock mode
// ---------------------------------------------------------------------------

describe("mock delivery mode", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("returns ok in mock delivery mode without calling fetch", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "mock" }),
		);
		expect(result).toMatchObject({ ok: true });
		expect(fetchSpy).not.toHaveBeenCalled();
	});

	it("returns ok when no locals are provided (defaults to mock in non-production)", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe("user@example.com", null);
		expect(result).toBeDefined();
		expect(fetchSpy).not.toHaveBeenCalled();
	});
});

describe("Unrecognized delivery mode falls back to mock", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});

	it("returns ok: true for an unknown mode without calling fetch", async () => {
		const fetchSpy = vi.spyOn(globalThis, "fetch");
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "unknown-service" }),
		);
		expect(result).toMatchObject({ ok: true });
		expect(fetchSpy).not.toHaveBeenCalled();
	});
});

// ---------------------------------------------------------------------------
// newsletterAdapter.subscribe — Listmonk mode
// ---------------------------------------------------------------------------

describe("Subscriber endpoint forwards to Listmonk API via newsletterAdapter", () => {
	beforeEach(() => {
		vi.restoreAllMocks();
	});
	afterEach(() => {
		vi.restoreAllMocks();
	});

	it("calls the Listmonk subscribers API and returns ok on 200", async () => {
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("{}", { status: 200 }));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: true });
		expect(fetch).toHaveBeenCalledOnce();
		const [url] = (fetch as ReturnType<typeof vi.fn>).mock.calls[0] as [string];
		expect(url).toContain("/api/subscribers");
	});

	it("uses Basic auth header derived from username:password", async () => {
		let capturedAuth = "";
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, init) => {
			capturedAuth = (init?.headers as Record<string, string>).Authorization ?? "";
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(capturedAuth).toMatch(/^Basic /);
		const decoded = atob(capturedAuth.replace("Basic ", ""));
		expect(decoded).toBe("admin:secret");
	});

	it("sends email, name, status, and lists in the request body", async () => {
		let body: Record<string, unknown> = {};
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, init) => {
			body = JSON.parse(init?.body as string) as Record<string, unknown>;
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("test@example.com", makeLocals(listmonkEnv));
		expect(body.email).toBe("test@example.com");
		expect(body.status).toBe("enabled");
		expect(Array.isArray(body.lists)).toBe(true);
		expect((body.lists as number[])[0]).toBe(1);
	});

	it("returns error on non-200 Listmonk response", async () => {
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("Conflict", { status: 409 }));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});

	it("returns network error when fetch throws for Listmonk", async () => {
		vi.spyOn(globalThis, "fetch").mockRejectedValueOnce(new Error("ECONNREFUSED"));
		const result = await newsletterAdapter.subscribe("user@example.com", makeLocals(listmonkEnv));
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toContain("could not be reached");
	});

	it("sends method:POST + Content-Type: application/json + preconfirm_subscriptions:true (pins L73/L76/L83)", async () => {
		let init: RequestInit = {};
		vi.spyOn(globalThis, "fetch").mockImplementationOnce(async (_url, requestInit) => {
			init = requestInit as RequestInit;
			return new Response("{}", { status: 200 });
		});
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		expect(init.method).toBe("POST");
		const headers = init.headers as Record<string, string>;
		expect(headers["Content-Type"]).toBe("application/json");
		const body = JSON.parse(init.body as string);
		expect(body.preconfirm_subscriptions).toBe(true);
	});

	it("logs 'Listmonk API error' on non-ok response (pins L88 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("body", { status: 500 }));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Listmonk API error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.status).toBe(500);
		expect(meta?.body).toBe("body");
		errorSpy.mockRestore();
	});

	it("logs 'Successfully subscribed to Listmonk' on 200 (pins L94 message + payload)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockResolvedValueOnce(new Response("{}", { status: 200 }));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Successfully subscribed to Listmonk"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.email).toBe("u@x.com");
		logSpy.mockRestore();
	});

	it("logs 'Listmonk subscription error' on fetch throw (pins L97 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		vi.spyOn(globalThis, "fetch").mockRejectedValueOnce(new Error("oops"));
		await newsletterAdapter.subscribe("u@x.com", makeLocals(listmonkEnv));
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Listmonk subscription error"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(String((meta?.error as Error)?.message ?? meta?.error)).toContain("oops");
		errorSpy.mockRestore();
	});

	it("logs 'Newsletter is misconfigured' when config is incomplete (pins L122 message + payload)", async () => {
		const errorSpy = vi.spyOn(console, "error").mockImplementation(() => {});
		await newsletterAdapter.subscribe(
			"u@x.com",
			makeLocals({
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_API_URL: "https://x",
				LISTMONK_API_USERNAME: "u",
				LISTMONK_API_PASSWORD: "p",
				// LISTMONK_LIST_ID missing
			}),
		);
		const matched = errorSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Newsletter is misconfigured"),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.reason).toBeDefined();
		errorSpy.mockRestore();
	});

	it("logs 'Using mock delivery mode.' in mock mode (pins L129 message + payload)", async () => {
		const logSpy = vi.spyOn(console, "log").mockImplementation(() => {});
		await newsletterAdapter.subscribe("u@x.com", makeLocals({ NEWSLETTER_DELIVERY_MODE: "mock" }));
		const matched = logSpy.mock.calls.find((args) =>
			args.some((a) => typeof a === "string" && a === "Using mock delivery mode."),
		);
		expect(matched).toBeDefined();
		const meta = matched?.[2] as Record<string, unknown>;
		expect(meta?.mode).toBe("mock");
		logSpy.mockRestore();
	});
});

describe("Listmonk adapter returns error when configuration is incomplete", () => {
	it("returns ok: false when LISTMONK_API_URL is missing", async () => {
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({ NEWSLETTER_DELIVERY_MODE: "listmonk" }),
		);
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});

	it("returns ok: false when LISTMONK_LIST_ID is missing", async () => {
		const result = await newsletterAdapter.subscribe(
			"user@example.com",
			makeLocals({
				NEWSLETTER_DELIVERY_MODE: "listmonk",
				LISTMONK_API_URL: "https://listmonk.example.com",
				LISTMONK_API_USERNAME: "admin",
				LISTMONK_API_PASSWORD: "secret",
				// LISTMONK_LIST_ID intentionally omitted
			}),
		);
		expect(result).toMatchObject({ ok: false });
		expect(result.error).toBeTruthy();
	});
});

// ---------------------------------------------------------------------------
// placeholderAdapter
// ---------------------------------------------------------------------------

it("placeholderAdapter is the same object as newsletterAdapter", () => {
	expect(placeholderAdapter).toBe(newsletterAdapter);
});

tests/security-headers.test.ts.source:
import { describe, expect, it } from "vitest";

import {
	applyAstropressSecurityHeaders,
	applyCacheHeaders,
	createAstropressSecureRedirect,
	createAstropressSecurityHeaders,
	isTrustedRequestOrigin,
	isTrustedStrictRequestOrigin,
} from "../src/security-headers.js";
import { resolveAstropressSecurityArea } from "../src/security-middleware.js";

describe("security headers", () => {
	it("builds a CSP that forbids inline scripts and framing by default", () => {
		// allowInlineStyles defaults to false — callers that need it must opt in explicitly
		const headers = createAstropressSecurityHeaders({
			area: "admin",
			allowInlineStyles: true,
		});
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain("script-src 'self' https://challenges.cloudflare.com");
		expect(csp).not.toContain("script-src 'self' 'unsafe-inline'");
		expect(csp).toContain("style-src 'self' 'unsafe-inline'");
		expect(csp).toContain("frame-ancestors 'none'");
		expect(headers.get("X-Frame-Options")).toBe("DENY");
		expect(headers.get("X-Content-Type-Options")).toBe("nosniff");
		expect(headers.get("Referrer-Policy")).toBe("strict-origin-when-cross-origin");
	});

	it("defaults allowInlineStyles to false — style-src excludes unsafe-inline without explicit opt-in", () => {
		const headers = createAstropressSecurityHeaders({ area: "admin" });
		const csp = headers.get("Content-Security-Policy") ?? "";
		expect(csp).toContain("style-src 'self'");
		expect(csp).not.toContain("'unsafe-inline'");
	});

	it("sets Cross-Origin-Resource-Policy: same-site for admin, auth, and api areas", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const headers = createAstropressSecurityHeaders({ area });
			expect(headers.get("Cross-Origin-Resource-Policy"), `area: ${area}`).toBe("same-site");
		}
		// Public area does NOT get CORP
		const publicHeaders = createAstropressSecurityHeaders({ area: "public" });
		expect(publicHeaders.has("Cross-Origin-Resource-Policy")).toBe(false);
	});

	it("adds HSTS only when explicitly requested", () => {
		const withoutHsts = createAstropressSecurityHeaders({ area: "auth" });
		const withHsts = createAstropressSecurityHeaders({
			area: "auth",
			forceHsts: true,
		});

		expect(withoutHsts.has("Strict-Transport-Security")).toBe(false);
		expect(withHsts.get("Strict-Transport-Security")).toContain("max-age=31536000");
	});

	it("applies headers onto an existing collection and secures redirects", () => {
		const target = new Headers({ "Cache-Control": "no-store" });
		applyAstropressSecurityHeaders(target, { area: "api" });

		// applyAstropressSecurityHeaders sets Cache-Control to 'private, no-store' for api area
		expect(target.get("Cache-Control")).toBe("private, no-store");
		expect(target.get("Permissions-Policy")).toContain("camera=()");

		const response = createAstropressSecureRedirect("/ap-admin/login", 302);
		expect(response.status).toBe(302);
		expect(response.headers.get("Location")).toBe("/ap-admin/login");
		expect(response.headers.get("Content-Security-Policy")).toContain("default-src 'self'");
		expect(response.headers.get("Cross-Origin-Resource-Policy")).toBe("same-site");
	});

	it("CSP includes all required default directives with proper separators", () => {
		const csp = createAstropressSecurityHeaders().get("Content-Security-Policy") ?? "";
		expect(csp).toContain("base-uri 'self'");
		expect(csp).toContain("img-src 'self' data: https:");
		expect(csp).toContain("font-src 'self' data: https:");
		expect(csp).toContain("connect-src 'self' https:");
		expect(csp).toContain("media-src 'self' data: https:");
		expect(csp).toContain("frame-src 'self' https://challenges.cloudflare.com");
		expect(csp).toContain("worker-src 'self' blob:");
		expect(csp).toContain("manifest-src 'self'");
		expect(csp).toContain("upgrade-insecure-requests");
		expect(csp).toContain("; base-uri 'self'");
	});

	it("default area is public — object-src self and COOP same-origin", () => {
		const headers = createAstropressSecurityHeaders();
		const csp = headers.get("Content-Security-Policy") ?? "";
		expect(csp).toContain("object-src 'self'");
		expect(headers.get("Cross-Origin-Opener-Policy")).toBe("same-origin");
	});

	it("accepts same-origin form posts and rejects cross-origin origins", () => {
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/actions/content-save", {
					method: "POST",
					headers: { origin: "https://example.com" },
				}),
			),
		).toBe(true);

		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/actions/content-save", {
					method: "POST",
					headers: { origin: "https://attacker.example" },
				}),
			),
		).toBe(false);
	});

	it("adds report-uri and Report-To header when reportUri option is set", () => {
		const reportUri = "/ap-admin/actions/csp-report";
		const headers = createAstropressSecurityHeaders({
			area: "admin",
			reportUri,
		});
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain(`report-uri ${reportUri}`);
		expect(csp).toContain("report-to csp-endpoint");
		expect(headers.get("Report-To")).toContain("csp-endpoint");
		expect(headers.get("Report-To")).toContain(reportUri);
	});

	it("omits report-uri and Report-To when reportUri is not set", () => {
		const headers = createAstropressSecurityHeaders({ area: "admin" });
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).not.toContain("report-uri");
		expect(csp).not.toContain("report-to");
		expect(headers.has("Report-To")).toBe(false);
	});

	it("rejects cross-origin requests and handles no-origin/no-referer (returns true)", () => {
		// referer check branch (origin absent, referer present)
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { referer: "https://example.com/ap-admin/page" },
				}),
			),
		).toBe(true); // same-origin referer → truthy

		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { referer: "https://attacker.com/page" },
				}),
			),
		).toBe(false); // cross-origin referer → false

		// Lines 35-36: parseOrigin catch branch — invalid URL string in origin header
		expect(
			isTrustedRequestOrigin(
				new Request("https://example.com/ap-admin/save", {
					method: "POST",
					headers: { origin: "not-a-valid-url" },
				}),
			),
		).toBe(false); // origin header present but unparseable → return false (stricter: no fallback to referer)
	});

	it("uses SAMEORIGIN when frameAncestors option is not 'none'", () => {
		const headers = createAstropressSecurityHeaders({
			frameAncestors: "'self'",
		});
		expect(headers.get("X-Frame-Options")).toBe("SAMEORIGIN");
	});

	it("public area uses object-src self and form-action self https:", () => {
		const headers = createAstropressSecurityHeaders({ area: "public" });
		const csp = headers.get("Content-Security-Policy") ?? "";

		expect(csp).toContain("object-src 'self'");
		expect(csp).toContain("form-action 'self' https:");
	});

	it("admin/auth/api areas use object-src none and restricted form-action", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const csp = createAstropressSecurityHeaders({ area }).get("Content-Security-Policy") ?? "";
			expect(csp).toContain("object-src 'none'");
			expect(csp).toContain("form-action 'self'");
			expect(csp).not.toContain("form-action 'self' https:");
		}
	});

	it("disables inline styles when allowInlineStyles is false", () => {
		const csp =
			createAstropressSecurityHeaders({ allowInlineStyles: false }).get(
				"Content-Security-Policy",
			) ?? "";
		expect(csp).toContain("style-src 'self'");
		expect(csp).not.toContain("'unsafe-inline'");
	});

	it("applyCacheHeaders uses default 300/3600 TTL for public area", () => {
		const headers = new Headers();
		applyCacheHeaders(headers, "public");
		expect(headers.get("Cache-Control")).toBe(
			"public, max-age=300, s-maxage=3600, stale-while-revalidate=86400",
		);
	});

	it("applyCacheHeaders respects publicCacheTtl override for public area", () => {
		const headers = new Headers();
		applyCacheHeaders(headers, "public", 600);
		expect(headers.get("Cache-Control")).toBe(
			"public, max-age=600, s-maxage=7200, stale-while-revalidate=86400",
		);
	});

	it("applyCacheHeaders sets no-store for non-public areas regardless of publicCacheTtl", () => {
		for (const area of ["admin", "auth", "api"] as const) {
			const headers = new Headers();
			applyCacheHeaders(headers, area, 600);
			expect(headers.get("Cache-Control"), `area: ${area}`).toBe("private, no-store");
		}
	});

	it("isTrustedStrictRequestOrigin accepts same-origin origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "https://example.com" },
				}),
			),
		).toBe(true);
	});

	it("isTrustedStrictRequestOrigin rejects cross-origin origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "https://attacker.example" },
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin accepts same-origin referer when origin absent", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/reset-password", {
					method: "POST",
					headers: { referer: "https://example.com/ap-admin/reset-password" },
				}),
			),
		).toBe(true);
	});

	it("isTrustedStrictRequestOrigin rejects cross-origin referer", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/reset-password", {
					method: "POST",
					headers: { referer: "https://attacker.example/page" },
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin rejects requests with neither origin nor referer", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
				}),
			),
		).toBe(false);
	});

	it("isTrustedStrictRequestOrigin rejects invalid URL in origin header", () => {
		expect(
			isTrustedStrictRequestOrigin(
				new Request("https://example.com/ap-admin/actions/accept-invite", {
					method: "POST",
					headers: { origin: "not-a-valid-url" },
				}),
			),
		).toBe(false);
	});

	it("classifies public, auth, admin, and action routes for middleware application", () => {
		expect(resolveAstropressSecurityArea(new URL("https://example.com/"))).toBe("public");
		expect(resolveAstropressSecurityArea(new URL("https://example.com/ap-admin/login"))).toBe(
			"auth",
		);
		expect(resolveAstropressSecurityArea(new URL("https://example.com/ap-admin"))).toBe("admin");
		expect(
			resolveAstropressSecurityArea(
				new URL("https://example.com/ap-admin/actions/comment-moderate"),
			),
		).toBe("api");
	});
});

tests/runtime-page-store.test.ts.source:
/**
 * runtime-page-store mutation pins.
 *
 * Targets survivors in runtime-page-store.ts that aren't covered by the
 * thinner monitoring/content-search suites: getSeededContentRecords' .map
 * callback, the searchRuntimeContentStates config-gate paths,
 * getRuntimeContentStateByPath's normalize-and-find logic, and the
 * getRuntimeTranslationState body.
 */

import { afterEach, describe, expect, it, vi } from "vitest";

import type { SeededContentRecord } from "../src/runtime-page-store-helpers.js";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

function setCmsConfig(extra: Record<string, unknown> = {}) {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = {
		siteName: "Test Site",
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [],
		...extra,
	};
}

function clearCmsConfig() {
	(globalThis as typeof globalThis & { [key: symbol]: unknown })[CMS_CONFIG_KEY] = null;
}

vi.mock("../src/admin-store-dispatch.js", async () => {
	const actual = await vi.importActual<typeof import("../src/admin-store-dispatch.js")>(
		"../src/admin-store-dispatch.js",
	);
	return {
		...actual,
		// Force the static-read-store fallback path so seedPages drives the store.
		safeLoadLocalAdminStore: vi.fn(async () => null),
	};
});

const seededRecord: SeededContentRecord = {
	slug: "about",
	legacyUrl: "/about",
	title: "About",
	status: "published",
	body: "<p>about</p>",
	listingItems: [],
	paginationLinks: [],
	updatedAt: "2026-01-01T00:00:00Z",
	updatedBy: "admin@example.com",
	// audit-boundary: opaque-passthrough -- seeded test fixture; satisfies SeededContentRecord at runtime
} as unknown as SeededContentRecord;

afterEach(() => {
	clearCmsConfig();
	vi.restoreAllMocks();
});

describe("searchRuntimeContentStates — peekCmsConfig safety", () => {
	it("returns [] without throwing when peekCmsConfig() resolves to null (kills L153 OptionalChaining mutants)", async () => {
		clearCmsConfig();
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: peekCmsConfig() === null → null?.search → undefined → falsy → returns [].
		// Mutants removing optional chaining: null.search throws TypeError. This asserts no-throw.
		await expect(searchRuntimeContentStates("anything")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalled();
	});

	it("with search.enabled=true delegates to the local admin store (kills L153:6 ConditionalExpression:true)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const searchSpy = vi.fn(async (q: string) => [
			{ slug: `hit-${q}`, legacyUrl: `/hit/${q}`, title: q } as never,
		]);
		const dispatch = await import("../src/admin-store-dispatch.js");
		(dispatch.safeLoadLocalAdminStore as unknown as ReturnType<typeof vi.fn>).mockResolvedValueOnce(
			{
				searchContentStates: searchSpy,
			} as never,
		);

		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("hello");
		// Mutated `if (true)` short-circuits to [] regardless of config — assertion catches it.
		expect(results).toHaveLength(1);
		expect(searchSpy).toHaveBeenCalledWith("hello");
	});
});

describe("searchRuntimeContentStates — additional pin survivors", () => {
	it("with config missing the entire `search` key falls through gracefully (kills L153:7 OptionalChaining peekCmsConfig()?.search.enabled)", async () => {
		setCmsConfig({}); // no `search` property at all
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: cfg.search is undefined → cfg?.search?.enabled → undefined → falsy →
		//   returns []. Mutant removing the second `?`: cfg.search.enabled throws TypeError on
		//   undefined.enabled. Assertion asserts no-throw.
		await expect(searchRuntimeContentStates("q")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalled();
	});

	it("when search.enabled=true and the admin store is missing entirely, falls through without throwing (kills L160:6 ConditionalExpression:true and OptionalChaining store.searchContentStates)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const dispatch = await import("../src/admin-store-dispatch.js");
		(dispatch.safeLoadLocalAdminStore as unknown as ReturnType<typeof vi.fn>).mockResolvedValueOnce(
			null,
		);
		const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {});
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		// Original: store is null → store?.searchContentStates → undefined → falsy → checks db
		//   (none) → final warn-and-return-[].
		// Mutant L160:6 ConditionalExpression:true: enters the branch unconditionally → null.searchContentStates() throws.
		// Mutant L160:6 OptionalChaining store.searchContentStates: null.searchContentStates throws.
		await expect(searchRuntimeContentStates("q")).resolves.toEqual([]);
		expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("no FTS-capable store"));
	});
});

describe("getRuntimeContentStateByPath — path normalization & lookup", () => {
	it("finds a seeded record by exact /-prefixed pathname (kills L171 BlockStatement, L172:25 endsWith, L174 LogicalOperator/ArrowFunction, L16:3 ArrowFunction)", async () => {
		setCmsConfig({ seedPages: [{ ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		// Original: startsWith("/") true → normalizedPath="/about" → finds record.
		// L172:25 MethodExpression endsWith: "/about".endsWith("/")=false →
		//   normalizedPath="/" + "/about" = "//about" → no match → null.
		// L171 BlockStatement {}: returns undefined → assertion fails.
		// L174 LogicalOperator &&: returns null when record found.
		// L174 ArrowFunction () => undefined: find returns undefined → returns null.
		// L16 ArrowFunction () => undefined: seededContentRecords contains undefined entries →
		//   record.legacyUrl access throws TypeError on .find().
		const found = await getRuntimeContentStateByPath("/about");
		expect(found).not.toBeNull();
		expect(found?.legacyUrl).toBe("/about");
	});

	it("picks the legacyUrl-matching record from a multi-record list (kills L174:34 ConditionalExpression:true)", async () => {
		const other: SeededContentRecord = {
			...seededRecord,
			slug: "other",
			legacyUrl: "/other",
			title: "Other",
		} as SeededContentRecord;
		// Order matters: 'other' first, 'about' second. Mutant find(record => true) returns the first.
		setCmsConfig({ seedPages: [other, { ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		const found = await getRuntimeContentStateByPath("/about");
		// Original predicate filters to legacyUrl="/about" → seededRecord.
		// Mutant `find(() => true)` returns 'other' (index 0).
		expect(found?.legacyUrl).toBe("/about");
		expect(found?.slug).toBe("about");
	});

	it("prepends '/' to a bare pathname before lookup (kills L172:45 StringLiteral)", async () => {
		setCmsConfig({ seedPages: [{ ...seededRecord }] });
		const { getRuntimeContentStateByPath } = await import("../src/runtime-page-store.js");
		// Original: startsWith("/") false → normalizedPath="/about" → finds.
		// L172:45 StringLiteral "": startsWith("") true → normalizedPath="about" (no slash) →
		//   no match against legacyUrl="/about" → null.
		const found = await getRuntimeContentStateByPath("about");
		expect(found?.legacyUrl).toBe("/about");
	});
});

describe("getSeededContentRecords — narrowing ternaries", () => {
	it("propagates string-typed kind/scheduledAt through the narrowing ternaries (kills L19/L23 ConditionalExpression:false, EqualityOperator !==, StringLiteral)", async () => {
		const fullyTyped = {
			...seededRecord,
			kind: "post",
			scheduledAt: "2026-01-01T00:00:00Z",
		} as unknown as SeededContentRecord;
		setCmsConfig({ seedPages: [fullyTyped] });
		const { listRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const records = await listRuntimeContentStates();
		const r = records[0];
		// Original (typeof === "string"): both fields preserved as strings.
		// Mutants ConditionalExpression:false / EqualityOperator !== / StringLiteral "":
		// flip the narrowing to the undefined branch → both fields become undefined.
		expect(r.kind).toBe("post");
		expect(r.scheduledAt).toBe("2026-01-01T00:00:00Z");
	});

	it("non-string kind/scheduledAt are scrubbed to undefined (kills L19/L23 ConditionalExpression:true)", async () => {
		const mistyped = {
			...seededRecord,
			kind: 42 as unknown as string,
			scheduledAt: { not: "a string" } as unknown as string,
		} as unknown as SeededContentRecord;
		setCmsConfig({ seedPages: [mistyped] });
		const { listRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const records = await listRuntimeContentStates();
		const r = records[0];
		// Original: typeof !== "string" → undefined.
		// Mutant ConditionalExpression:true: always returns the raw page.kind / page.scheduledAt →
		//   the non-string values leak through, failing strict-undefined assertion.
		expect(r.kind).toBeUndefined();
		expect(r.scheduledAt).toBeUndefined();
	});
});

describe("searchRuntimeContentStates — D1 search delegation", () => {
	it("delegates to searchD1ContentStates when search is enabled and a D1 binding is present (kills L164:6 ConditionalExpression:false)", async () => {
		setCmsConfig({ search: { enabled: true } });
		const fakeRow = { slug: "d1-hit" } as never;
		const d1 = await import("../src/d1-store-content.js");
		const spy = vi.spyOn(d1, "searchD1ContentStates").mockResolvedValueOnce([fakeRow]);
		const locals = {
			runtime: { env: { DB: { prepare: () => ({}) } } },
		} as unknown as App.Locals;
		const { searchRuntimeContentStates } = await import("../src/runtime-page-store.js");
		const results = await searchRuntimeContentStates("query", locals);
		// Original enters the `if (db)` branch and calls searchD1ContentStates.
		// Mutant L164:6 ConditionalExpression:false skips → warn-and-return-[].
		expect(spy).toHaveBeenCalledWith(expect.anything(), "query");
		expect(results).toEqual([fakeRow]);
	});
});

describe("getRuntimeTranslationState — fallback path body", () => {
	it("returns the fallback string from the static read store (kills L185 BlockStatement)", async () => {
		setCmsConfig();
		const { getRuntimeTranslationState } = await import("../src/runtime-page-store.js");
		// Static read store's getEffectiveTranslationState(route, fallback) returns the
		// `fallback` argument verbatim. L185 mutated body returns undefined → assertion fails.
		const state = await getRuntimeTranslationState("/some/route", "in_progress");
		expect(state).toBe("in_progress");
	});
});

tests/locale-links.test.ts.source:
import {
	canonicalUrlForRoute,
	getAlternateLinksForEnglishRoute,
	getLocaleSwitchTargets,
	registerCms,
	sanitizeCanonicalUrl,
} from "@astropress-diy/astropress";
import { beforeEach, describe, expect, it } from "vitest";

beforeEach(() => {
	registerCms({
		siteUrl: "https://example.com",
		templateKeys: [],
		seedPages: [],
		archives: [],
		translationStatus: [
			{
				route: "/es/impacto",
				locale: "es",
				englishSourceUrl: "/impact",
				translationState: "published",
			},
			{
				route: "/es",
				locale: "es",
				englishSourceUrl: "/",
				translationState: "published",
			},
			{
				route: "/es/paisajes-comestibles",
				locale: "es",
				englishSourceUrl: "/en/edible-landscapes",
				translationState: "published",
			},
			{
				route: "/es/contacto",
				locale: "es",
				englishSourceUrl: "/en/contact",
				translationState: "published",
			},
		],
	});
});

describe("canonicalUrlForRoute()", () => {
	it("returns the full absolute URL for a given route", () => {
		expect(canonicalUrlForRoute("/impact")).toBe("https://example.com/impact/");
	});

	it("handles the root route without double slash", () => {
		expect(canonicalUrlForRoute("/")).toBe("https://example.com/");
	});

	it("appends a trailing slash to non-root routes", () => {
		expect(canonicalUrlForRoute("/en/education")).toBe("https://example.com/en/education/");
	});
});

describe("getAlternateLinksForEnglishRoute()", () => {
	it("returns EN + ES alternates for a known translated route (/impact → /es/impacto)", () => {
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(2);
		const hreflangs = links.map((l) => l.hreflang);
		expect(hreflangs).toContain("en");
		expect(hreflangs).toContain("es");
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/impacto");
	});

	it("returns EN + ES alternates for the root route (/ → /es)", () => {
		const links = getAlternateLinksForEnglishRoute("/");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es");
	});

	it("returns EN + ES alternates for a core service route", () => {
		const links = getAlternateLinksForEnglishRoute("/en/edible-landscapes");
		expect(links).toHaveLength(2);
		const esLink = links.find((l) => l.hreflang === "es");
		expect(esLink?.href).toContain("/es/paisajes-comestibles");
	});

	it("returns empty array for an unknown route", () => {
		const links = getAlternateLinksForEnglishRoute("/non-existent-page");
		expect(links).toHaveLength(0);
	});

	it("filters out non-'es' locale entries (pins L21 locale === 'es' check)", () => {
		registerCms({
			siteUrl: "https://example.com",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [
				{
					route: "/fr/impact",
					locale: "fr",
					englishSourceUrl: "/impact",
					translationState: "published",
				},
			],
		});
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(0);
	});

	it("filters out non-published translation states (pins L22 isPublished check)", () => {
		registerCms({
			siteUrl: "https://example.com",
			templateKeys: [],
			seedPages: [],
			archives: [],
			translationStatus: [
				{
					route: "/es/impacto-draft",
					locale: "es",
					englishSourceUrl: "/impact",
					translationState: "draft",
				},
			],
		});
		const links = getAlternateLinksForEnglishRoute("/impact");
		expect(links).toHaveLength(0);
	});
});

describe("sanitizeCanonicalUrl()", () => {
	it("returns absolute URL for a known route when no override is provided", () => {
		const url = sanitizeCanonicalUrl(undefined, "/en/impact");
		expect(url).toBe("https://example.com/en/impact/");
	});

	it("strips query string and hash from an override URL", () => {
		const url = sanitizeCanonicalUrl(
			"https://example.com/en/impact?utm_source=test#section",
			"/en/impact",
		);
		expect(url).not.toContain("utm_source");
		expect(url).not.toContain("#section");
		expect(url).toContain("example.com/en/impact");
	});

	it("normalizes trailing slash on override URL", () => {
		const url = sanitizeCanonicalUrl("https://example.com/en/impact", "/en/impact");
		expect(url).toMatch(/\/en\/impact\/$/);
	});

	it("preserves '/' without adding extra slash when override URL is the site root", () => {
		// Covers the `parsed.pathname === "/"` ternary true branch on line 46
		const url = sanitizeCanonicalUrl("https://example.com/", "/");
		expect(url).toBe("https://example.com/");
	});

	it("returns fallback canonical when value is undefined (pins L42 !value check)", () => {
		const url = sanitizeCanonicalUrl(undefined, "/fallback-route");
		expect(url).toContain("/fallback-route");
	});

	it("returns fallback canonical when value is empty string (pins L42 !value check)", () => {
		const url = sanitizeCanonicalUrl("", "/fallback-route");
		expect(url).toContain("/fallback-route");
	});
});

describe("getLocaleSwitchTargets isLocalePath survivors", () => {
	it("uses currentPath when lang='es' and path is exactly '/es' (pins L66 path === '/es')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es",
		});
		expect(targets.es).toBe("/es");
	});

	it("uses currentPath when lang='es' and path starts with '/es/' (pins L66 startsWith)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/sobre/",
		});
		expect(targets.es).toBe("/es/sobre/");
	});

	it("does NOT use currentPath when lang='es' but path is in EN-space (e.g. '/about')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/about",
		});
		// Default fallback to /es because /about is not an es-prefixed path.
		expect(targets.es).toBe("/es");
	});

	it("does NOT use currentPath when lang='es' and path is '/es-mx' (similar prefix but not '/es' or '/es/')", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es-mx/about",
		});
		expect(targets.es).toBe("/es");
	});
});

describe("getLocaleSwitchTargets()", () => {
	it("uses explicit alternate links for reviewed EN/ES route pairs", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/contact",
			alternateLinks: [
				{ hreflang: "en", href: "https://example.com/en/contact/" },
				{ hreflang: "es", href: "https://example.com/es/contacto/" },
			],
		});

		expect(targets).toEqual({
			en: "/en/contact/",
			es: "/es/contacto/",
		});
	});

	it("falls back to locale homes when no reviewed alternate exists", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [],
		});

		expect(targets).toEqual({
			en: "/en/about",
			es: "/es",
		});
	});

	it("sets the current path for the es locale when on an es route (isLocalePath es branch)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/impacto",
			alternateLinks: [],
		});
		expect(targets.es).toBe("/es/impacto");
		expect(targets.en).toBe("/en");
	});

	it("uses empty array fallback when alternateLinks is omitted (?? [] branch)", () => {
		const targets = getLocaleSwitchTargets({ lang: "en" });
		expect(targets).toEqual({ en: "/en", es: "/es" });
	});

	it("redirects root path '/' to '/en' when viewed from es locale", () => {
		const targets = getLocaleSwitchTargets({
			lang: "es",
			currentPath: "/es/inicio",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/" }],
		});
		expect(targets.en).toBe("/en");
	});

	it("skips alternate links with non-standard hreflang (fr is ignored)", () => {
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [
				{ hreflang: "fr", href: "https://example.com/fr/about/" },
				{ hreflang: "es", href: "https://example.com/es/sobre/" },
			],
		});
		// fr link ignored; es link used
		expect(targets.es).toBe("/es/sobre/");
		expect(targets).not.toHaveProperty("fr");
	});

	it("preserves a non-empty override URL distinct from the fallback (pins L42 !value → true)", () => {
		// Mutating `if (!value)` to `if (true)` would discard the override URL
		// and always return the fallback canonical. With value="/override" and
		// fallback="/fallback", the original keeps the override.
		const url = sanitizeCanonicalUrl("https://example.com/override", "/fallback");
		expect(url).toContain("/override");
		expect(url).not.toContain("/fallback");
	});

	it("keeps targets.en at /en when lang='en' and currentPath is an es-prefixed path (pins L69 startsWith→endsWith)", () => {
		// For path "/es/foo": startsWith("/es/") is true → isLocalePath("/es/foo", "en")
		// returns false → currentPath is NOT used for targets.en. Mutating
		// startsWith to endsWith inverts the check ("/es/foo" doesn't end with "/es/")
		// so isLocalePath would wrongly return true and assign /es/foo to targets.en.
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/es/foo",
		});
		expect(targets.en).toBe("/en");
	});

	it("does not rewrite targets.en to /en when hreflang='en' but path is not '/' (pins L93 path === '/' clause)", () => {
		// path === "/" replaced with `true` would make any en alternate href rewrite
		// to "/en" regardless of path. The original keeps the actual path "/en/contact/".
		const targets = getLocaleSwitchTargets({
			lang: "es",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/en/contact/" }],
		});
		expect(targets.en).toBe("/en/contact/");
	});

	it("does not rewrite targets.en to /en when lang='en' (pins L93 input.lang === 'es' clause)", () => {
		// input.lang === "es" replaced with `true` would fire the rewrite even on
		// an EN page viewing root. Original keeps targets.en as the raw path "/".
		const targets = getLocaleSwitchTargets({
			lang: "en",
			alternateLinks: [{ hreflang: "en", href: "https://example.com/" }],
		});
		expect(targets.en).toBe("/");
	});

	it("does not rewrite targets.es to /en when hreflang='es' and lang='es' (pins L93 hreflang === 'en' clause + first &&)", () => {
		// Mutating `hreflang === "en"` to `true` would fire the /en rewrite even
		// for an ES alternate link, and mutating the first `&&` to `||` would
		// short-circuit to /en when hreflang is "en" regardless of path/lang.
		// With hreflang="es", path="/", lang="es": original target.es is "/"; the
		// mutants would set target.es to "/en".
		const targets = getLocaleSwitchTargets({
			lang: "es",
			alternateLinks: [{ hreflang: "es", href: "https://example.com/" }],
		});
		expect(targets.es).toBe("/");
	});

	it("falls back to returning href as-is when URL parse fails (pathFromHref catch branch)", () => {
		const badHref = "http://[invalid-host]/path/";
		const targets = getLocaleSwitchTargets({
			lang: "en",
			currentPath: "/en/about",
			alternateLinks: [{ hreflang: "es", href: badHref }],
		});
		// The catch branch returns the raw href string as the path
		expect(targets.es).toBe(badHref);
	});
});

