import type { DatabaseSync } from "node:sqlite";
import { afterAll, beforeAll, beforeEach, describe, expect, it, vi } from "vitest";

import { registerCms } from "../src/config";
import type { AstropressWordPressImportReport } from "../src/platform-contracts.js";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { makeDb } from "./helpers/make-db.js";

// ─── Hoisted mock functions ────────────────────────────────────────────────────

const mocks = vi.hoisted(() => ({
	loadLocalAdminStore: vi.fn(),
	importWordPress: vi.fn(),
}));

vi.mock("@astropress-diy/astropress/local-runtime-modules", () => ({
	loadLocalAdminStore: mocks.loadLocalAdminStore,
}));

vi.mock("@astropress-diy/astropress/import/wordpress", () => ({
	createAstropressWordPressImportSource: () => ({
		importWordPress: mocks.importWordPress,
	}),
}));

// ─── Page handler import (after mocks) ───────────────────────────────────────

import { POST } from "../pages/ap-api/v1/import/wordpress.js";

// ─── Test fixtures ────────────────────────────────────────────────────────────

const BASE = "http://localhost";

let db: DatabaseSync;
let importWriteToken: string;
let contentReadToken: string;

const MOCK_REPORT: AstropressWordPressImportReport = {
	status: "completed",
	importedRecords: 3,
	importedMedia: 1,
	importedComments: 0,
	importedUsers: 1,
	importedRedirects: 2,
	downloadedMedia: 0,
	failedMedia: [],
	reviewRequired: false,
	manualTasks: [],
	warnings: [],
	plan: {
		exportFile: "/tmp/export.xml",
		includeComments: true,
		includeUsers: true,
		includeMedia: true,
		downloadMedia: false,
		applyLocal: true,
		permalinkStrategy: "preserve-wordpress-links",
		resumeSupported: true,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		reviewRequired: false,
		manualTasks: [],
	},
	inventory: {
		exportFile: "/tmp/export.xml",
		detectedRecords: 4,
		detectedMedia: 1,
		detectedComments: 0,
		detectedUsers: 1,
		detectedShortcodes: 0,
		detectedBuilderMarkers: 0,
		entityCounts: {
			posts: 2,
			pages: 1,
			attachments: 1,
			redirects: 2,
			comments: 0,
			users: 1,
			categories: 0,
			tags: 0,
		},
		unsupportedPatterns: [],
		remediationCandidates: [],
		warnings: [],
	},
};

beforeAll(async () => {
	db = makeDb();
	registerCms({
		templateKeys: ["content"],
		siteUrl: "https://example.com",
		seedPages: [],
		archives: [],
		translationStatus: [],
		api: { enabled: true },
	});

	const store = createApiTokenStore(db);
	importWriteToken = (await store.create({ label: "import", scopes: ["import:write"] })).rawToken;
	contentReadToken = (await store.create({ label: "read", scopes: ["content:read"] })).rawToken;
});

afterAll(() => {
	db.close();
});

beforeEach(() => {
	const apiTokens = createApiTokenStore(db);
	mocks.loadLocalAdminStore.mockResolvedValue({
		apiTokens,
		checkRateLimit: () => true,
	});
	mocks.importWordPress.mockResolvedValue(MOCK_REPORT);
});

// ─── Context builder ──────────────────────────────────────────────────────────

type AnyAPIContext = Parameters<typeof POST>[0];

function ctx(request: Request): AnyAPIContext {
	return { request, params: {}, locals: {} } as unknown as AnyAPIContext;
}

function req(opts: { token?: string; body?: unknown } = {}): Request {
	const headers: Record<string, string> = {
		"Content-Type": "application/json",
	};
	if (opts.token) headers.Authorization = `Bearer ${opts.token}`;
	return new Request(`${BASE}/ap-api/v1/import/wordpress`, {
		method: "POST",
		headers,
		body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
	});
}

// ─── POST /ap-api/v1/import/wordpress ────────────────────────────────────────

describe("POST /ap-api/v1/import/wordpress — auth and scope", () => {
	it("returns 401 without Authorization header", async () => {
		const res = await POST(ctx(req({ body: { exportFile: "/tmp/export.xml" } })));
		expect(res.status).toBe(401);
	});

	it("returns 403 when token lacks import:write scope", async () => {
		const res = await POST(
			ctx(
				req({
					token: contentReadToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(403);
	});

	it("returns 404 when API is disabled", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: false },
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(404);
		// Restore
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
			api: { enabled: true },
		});
	});
});

describe("POST /ap-api/v1/import/wordpress — request validation", () => {
	it("returns 422 when exportFile is missing from body", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: {} })));
		expect(res.status).toBe(422);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.code).toBe("validation_error");
	});

	it("returns 422 when exportFile is empty string", async () => {
		const res = await POST(ctx(req({ token: importWriteToken, body: { exportFile: "  " } })));
		expect(res.status).toBe(422);
	});
});

describe("POST /ap-api/v1/import/wordpress — success path", () => {
	it("returns 200 with AstropressWordPressImportReport shape", async () => {
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as Record<string, unknown>;
		expect(body.status).toBe("completed");
		expect(typeof body.importedRecords).toBe("number");
		expect(typeof body.importedMedia).toBe("number");
		expect(Array.isArray(body.failedMedia)).toBe(true);
		expect(typeof body.reviewRequired).toBe("boolean");
	});

	it("calls importWordPress with the provided exportFile and applyLocal: true", async () => {
		await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(mocks.importWordPress).toHaveBeenCalledWith(
			expect.objectContaining({
				exportFile: "/tmp/export.xml",
				applyLocal: true,
			}),
		);
	});

	it("returns completed_with_warnings status when import has warnings", async () => {
		mocks.importWordPress.mockResolvedValueOnce({
			...MOCK_REPORT,
			status: "completed_with_warnings",
			reviewRequired: true,
			warnings: ["Review remediation-candidates.json"],
		});
		const res = await POST(
			ctx(
				req({
					token: importWriteToken,
					body: { exportFile: "/tmp/export.xml" },
				}),
			),
		);
		expect(res.status).toBe(200);
		const body = (await res.json()) as { status: string; warnings: string[] };
		expect(body.status).toBe("completed_with_warnings");
		expect(body.warnings.length).toBeGreaterThan(0);
	});
});

tests/build-time-content-loader.test.ts.source:
import {
	type AstropressPlatformAdapter,
	assertProviderContract,
	type ContentListOptions,
	type ContentStoreRecord,
	normalizeProviderCapabilities,
} from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { createAstropressBuildTimeLoader } from "../src/build-time-content-loader";

function makeTestRecord(
	overrides: Partial<ContentStoreRecord> &
		Pick<ContentStoreRecord, "id" | "kind" | "slug" | "status">,
): ContentStoreRecord {
	return {
		title: overrides.title ?? `Title for ${overrides.slug}`,
		body: null,
		locale: null,
		metadata: {},
		...overrides,
	};
}

function createFilteringAdapter(records: ContentStoreRecord[]): AstropressPlatformAdapter {
	return assertProviderContract({
		capabilities: normalizeProviderCapabilities({ name: "test-filtering" }),
		content: {
			async list(kind, options?: ContentListOptions) {
				let results = [...records];

				if (kind) {
					results = results.filter((r) => r.kind === kind);
				}

				if (options?.status && options.status !== "all") {
					results = results.filter((r) => r.status === options.status);
				}

				if (options?.locale) {
					results = results.filter((r) => !r.locale || r.locale === options.locale);
				}

				if (options?.offset) {
					results = results.slice(options.offset);
				}

				if (options?.limit !== undefined) {
					results = results.slice(0, options.limit);
				}

				return results;
			},
			async get(id) {
				return records.find((r) => r.id === id) ?? null;
			},
			async save(record) {
				return record;
			},
			async delete() {},
		},
		media: {
			async put(a) {
				return a;
			},
			async get() {
				return null;
			},
			async delete() {},
		},
		revisions: {
			async list() {
				return [];
			},
			async append(r) {
				return r;
			},
		},
		auth: {
			async signIn() {
				return null;
			},
			async signOut() {},
			async getSession() {
				return null;
			},
		},
	});
}

describe("ContentListOptions", () => {
	it("list accepts status filter and returns only published records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "unpublished",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const published = await adapter.content.list("post", {
			status: "published",
		});
		expect(published.map((r) => r.slug)).toEqual(["hello-world"]);
	});

	it("list with no status filter returns all records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "hello-world",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const all = await adapter.content.list("post");
		expect(all).toHaveLength(2);
	});

	it("list with kind and status filter returns only matching records", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "post-1",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "page-1",
				status: "published",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "post-draft",
				status: "draft",
			}),
		];
		const adapter = createFilteringAdapter(records);

		const posts = await adapter.content.list("post", { status: "published" });
		expect(posts.map((r) => r.kind)).toEqual(["post"]);
		expect(posts.map((r) => r.slug)).toEqual(["post-1"]);
	});

	it("list respects limit and offset", async () => {
		const records: ContentStoreRecord[] = Array.from({ length: 10 }, (_, i) =>
			makeTestRecord({
				id: `post-${i}`,
				kind: "post",
				slug: `post-${i}`,
				status: "published",
			}),
		);
		const adapter = createFilteringAdapter(records);

		const page1 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 0,
		});
		expect(page1).toHaveLength(3);

		const page2 = await adapter.content.list("post", {
			status: "published",
			limit: 3,
			offset: 3,
		});
		expect(page2).toHaveLength(3);
		expect(page2[0].slug).toBe("post-3");
	});
});

describe("createAstropressBuildTimeLoader", () => {
	it("returns a loader with posts() and pages() factories", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(typeof loader.posts).toBe("function");
		expect(typeof loader.pages).toBe("function");
	});

	it("posts loader fetches only published posts", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "live-post",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "draft-post",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "page",
				slug: "a-page",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("live-post");
		expect(posts[0].kind).toBe("post");
	});

	it("pages loader fetches only published pages", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "page",
				slug: "about",
				status: "published",
			}),
			makeTestRecord({
				id: "b",
				kind: "page",
				slug: "draft-page",
				status: "draft",
			}),
			makeTestRecord({
				id: "c",
				kind: "post",
				slug: "a-post",
				status: "published",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const pages = await loader.pages().load();
		expect(pages).toHaveLength(1);
		expect(pages[0].slug).toBe("about");
		expect(pages[0].kind).toBe("page");
	});

	it("each returned record has the required ContentStoreRecord shape", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "post-1",
				kind: "post",
				slug: "post-1",
				status: "published",
				title: "Hello World",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter);

		const posts = await loader.posts().load();
		const record = posts[0];

		expect(record).toHaveProperty("id");
		expect(record).toHaveProperty("kind");
		expect(record).toHaveProperty("slug");
		expect(record).toHaveProperty("status");
		expect(record).toHaveProperty("title");
	});

	it("loader kind property matches the content kind", () => {
		const adapter = createFilteringAdapter([]);
		const loader = createAstropressBuildTimeLoader(adapter);

		expect(loader.posts().kind).toBe("post");
		expect(loader.pages().kind).toBe("page");
	});

	it("respects locale option when provided", async () => {
		const records: ContentStoreRecord[] = [
			makeTestRecord({
				id: "a",
				kind: "post",
				slug: "en-post",
				status: "published",
				locale: "en",
			}),
			makeTestRecord({
				id: "b",
				kind: "post",
				slug: "fr-post",
				status: "published",
				locale: "fr",
			}),
		];
		const adapter = createFilteringAdapter(records);
		const loader = createAstropressBuildTimeLoader(adapter, { locale: "en" });

		const posts = await loader.posts().load();
		expect(posts).toHaveLength(1);
		expect(posts[0].slug).toBe("en-post");
	});
});

tests/api-token-store.test.ts.source:
import { describe, expect, it } from "vitest";

import type { ApiScope, ApiTokenRecord, ApiTokenStore } from "../src/platform-contracts";
import { createApiTokenStore } from "../src/sqlite-runtime/api-tokens.js";
import { hashOpaqueToken } from "../src/sqlite-runtime/utils.js";
import { makeDb } from "./helpers/make-db.js";

// ─── ApiTokenRecord shape ─────────────────────────────────────────────────────

describe("ApiTokenRecord shape", () => {
	it("has all required fields", () => {
		const record: ApiTokenRecord = {
			id: "tok_01",
			label: "AI assistant",
			scopes: ["content:read"],
			createdAt: new Date().toISOString(),
		};

		expect(record.id).toBe("tok_01");
		expect(record.label).toBe("AI assistant");
		expect(record.scopes).toContain("content:read");
		expect(record.revokedAt).toBeUndefined();
	});

	it("supports all defined scopes", () => {
		const allScopes: ApiScope[] = [
			"content:read",
			"content:write",
			"media:read",
			"media:write",
			"settings:read",
			"webhooks:manage",
			"import:write",
		];
		const record: ApiTokenRecord = {
			id: "tok_02",
			label: "Full access",
			scopes: allScopes,
			createdAt: new Date().toISOString(),
		};
		expect(record.scopes).toHaveLength(7);
	});

	it("optional fields are truly optional", () => {
		const minimal: ApiTokenRecord = {
			id: "tok_03",
			label: "Minimal",
			scopes: ["settings:read"],
			createdAt: "2026-01-01T00:00:00Z",
		};
		expect(minimal.expiresAt).toBeUndefined();
		expect(minimal.lastUsedAt).toBeUndefined();
		expect(minimal.revokedAt).toBeUndefined();
	});
});

describe("ApiTokenStore SQLite implementation", () => {
	it("create: stores hashed token and returns raw token once", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);

		const { record, rawToken } = await store.create({
			label: "test",
			scopes: ["content:read"],
		});

		expect(rawToken.length).toBeGreaterThanOrEqual(32);
		expect(record.label).toBe("test");
		expect(record.scopes).toEqual(["content:read"]);
		expect(record.revokedAt).toBeNull();

		// Hash stored, not raw token
		const row = db.prepare("SELECT token_hash FROM api_tokens WHERE id = ?").get(record.id) as {
			token_hash: string;
		};
		expect(row.token_hash).toBe(hashOpaqueToken(rawToken));
		expect(row.token_hash).not.toBe(rawToken);
	});

	it("list: returns tokens without token_hash", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		await store.create({ label: "alpha", scopes: ["content:read"] });
		await store.create({ label: "beta", scopes: ["media:read"] });

		const tokens = await store.list();
		expect(tokens).toHaveLength(2);
		const labels = tokens.map((t) => t.label);
		expect(labels).toContain("alpha");
		expect(labels).toContain("beta");
		// No hash exposed
		for (const token of tokens) {
			expect((token as Record<string, unknown>).token_hash).toBeUndefined();
		}
	});

	it("verify: valid unrevoked token succeeds and updates lastUsedAt", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { rawToken } = await store.create({
			label: "agent",
			scopes: ["content:read"],
		});

		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");

		expect(result.record.label).toBe("agent");
		expect(result.record.lastUsedAt).not.toBeNull();
	});

	it("verify: revoked token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "short-lived",
			scopes: ["settings:read"],
		});

		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
	});

	it("verify: unknown token returns { valid: false }", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("completely-unknown-token");
		expect(result.valid).toBe(false);
	});

	it("revoke: sets revokedAt timestamp", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revoke-me",
			scopes: ["content:write"],
		});

		await store.revoke(record.id);
		const tokens = await store.list();
		const revoked = tokens.find((t) => t.id === record.id);
		expect(revoked?.revokedAt).not.toBeNull();
	});

	it("verify: expired token returns { valid: false } with 'expired' reason", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const past = new Date(Date.now() - 60_000).toISOString();
		const { rawToken } = await store.create({
			label: "expired",
			scopes: ["content:read"],
			expiresAt: past,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(false);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/expired/i);
	});

	it("verify: future-expiry token still verifies (pins < boundary on expires_at)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const future = new Date(Date.now() + 60_000).toISOString();
		const { rawToken, record } = await store.create({
			label: "future",
			scopes: ["content:read"],
			expiresAt: future,
		});
		const result = await store.verify(rawToken);
		expect(result.valid).toBe(true);
		if (!result.valid) throw new Error("expected valid");
		expect(result.record.expiresAt).toBe(future);
		expect(record.expiresAt).toBe(future);
	});

	it("create: persists expiresAt in the returned record (pins ?? null fallback)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "no-expiry",
			scopes: ["content:read"],
		});
		expect(record.expiresAt).toBeNull();
	});

	it("verify: revoked token reason mentions 'revoked' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record, rawToken } = await store.create({
			label: "revoke-reason",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);
		const result = await store.verify(rawToken);
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/revoked/i);
	});

	it("verify: unknown token reason mentions 'not found' (pins reason literal)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const result = await store.verify("nonexistent-token");
		if (result.valid) throw new Error("expected invalid");
		expect(result.reason).toMatch(/not found/i);
	});

	it("list: revoked tokens still appear in list (for admin display)", async () => {
		const db = makeDb();
		const store = createApiTokenStore(db);
		const { record } = await store.create({
			label: "revocable",
			scopes: ["content:read"],
		});
		await store.revoke(record.id);

		const tokens = await store.list();
		expect(tokens.some((t) => t.id === record.id)).toBe(true);
	});
});

// Type-level smoke test: ensure the interface is structurally correct
function assertApiTokenStoreShape(store: ApiTokenStore) {
	const _create = store.create;
	const _list = store.list;
	const _verify = store.verify;
	const _revoke = store.revoke;
	return { _create, _list, _verify, _revoke };
}

// Unused reference satisfies TypeScript without needing a real implementation
void assertApiTokenStoreShape;

tests/cloudflare-provider.integration.te.source:
import { createAstropressCloudflareAdapter, registerCms } from "@astropress-diy/astropress";
import { describe, expect, it } from "vitest";
import { makeDb } from "./helpers/make-db.js";
import {
	createSeededCloudflareDatabase,
	SqliteBackedD1Database,
} from "./helpers/provider-test-fixtures.js";

describe("cloudflare provider integration", () => {
	it("creates a D1-backed Cloudflare adapter surface", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		expect(cloudflare.capabilities.name).toBe("cloudflare");
		expect(cloudflare.capabilities.database).toBe(true);
		expect(cloudflare.capabilities.objectStorage).toBe(true);
		expect(cloudflare.capabilities.staticPublishing).toBe(true);
		expect(cloudflare.capabilities.hostedAdmin).toBe(true);
		expect(cloudflare.capabilities.previewEnvironments).toBe(true);
		expect(cloudflare.capabilities.serverRuntime).toBe(true);
		expect(cloudflare.capabilities.gitSync).toBe(true);

		const user = await cloudflare.auth.signIn("admin@example.com", "password");
		expect(user?.isAdmin).toBe(true);
		expect(user?.id).toHaveLength(36);
		const storedSession = db.prepare("SELECT id FROM admin_sessions LIMIT 1").get() as {
			id: string;
		};
		expect(storedSession.id).not.toBe(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toMatchObject({
			email: "admin@example.com",
			isAdmin: true,
		});
		expect(await cloudflare.content.get("cloudflare-post")).toMatchObject({
			slug: "cloudflare-post",
			kind: "post",
			title: "Cloudflare post",
		});
		expect(await cloudflare.media.get("cloudflare-media-1")).toMatchObject({
			id: "cloudflare-media-1",
			mimeType: "image/png",
		});
		expect(await cloudflare.revisions.list("cloudflare-post")).toMatchObject([
			{
				id: "revision-cloudflare-1",
				recordId: "cloudflare-post",
			},
		]);
		await cloudflare.auth.signOut(user?.id);
		expect(await cloudflare.auth.getSession(user?.id)).toBeNull();

		db.close();
	});

	it("persists writable records through the D1-backed Cloudflare adapter", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		const savedPost = await cloudflare.content.save({
			id: "cloudflare-write-post",
			kind: "post",
			slug: "cloudflare-write-post",
			status: "published",
			title: "Cloudflare write post",
			body: "<p>Writable Cloudflare body</p>",
			metadata: {
				metaDescription: "Writable Cloudflare record",
				seoTitle: "Cloudflare write post",
				legacyUrl: "/cloudflare-write-post",
			},
		});
		expect(savedPost.slug).toBe("cloudflare-write-post");
		expect(await cloudflare.content.get("cloudflare-write-post")).toMatchObject({
			slug: "cloudflare-write-post",
			kind: "post",
			title: "Cloudflare write post",
		});

		const translation = await cloudflare.content.save({
			id: "/es/cloudflare-write-post",
			kind: "translation",
			slug: "/es/cloudflare-write-post",
			status: "draft",
			metadata: {
				state: "translated",
			},
		});
		expect(translation.metadata).toMatchObject({
			state: "translated",
		});

		const redirect = await cloudflare.content.save({
			id: "/legacy-cloudflare-write-post",
			kind: "redirect",
			slug: "/legacy-cloudflare-write-post",
			status: "published",
			metadata: {
				targetPath: "/cloudflare-write-post",
				statusCode: 301,
			},
		});
		expect(redirect.metadata).toMatchObject({
			targetPath: "/cloudflare-write-post",
			statusCode: 301,
		});

		const settings = await cloudflare.content.save({
			id: "site-settings",
			kind: "settings",
			slug: "site-settings",
			status: "published",
			metadata: {
				siteTitle: "Cloudflare Writable Site",
			},
		});
		expect(settings.title).toBe("Cloudflare Writable Site");

		await cloudflare.media.put({
			id: "cloudflare-upload",
			filename: "cloudflare-upload.png",
			mimeType: "image/png",
			publicUrl: "https://cdn.example.com/cloudflare-upload.png",
			metadata: {
				altText: "Cloudflare upload",
				title: "cloudflare-upload.png",
			},
		});
		expect(await cloudflare.media.get("cloudflare-upload")).toMatchObject({
			id: "cloudflare-upload",
			mimeType: "image/png",
		});

		await cloudflare.revisions.append({
			id: "cloudflare-write-revision",
			recordId: "cloudflare-write-post",
			createdAt: "2026-01-01T00:00:00.000Z",
			actorId: "admin@example.com",
			summary: "Cloudflare write revision",
			snapshot: {
				title: "Cloudflare write post",
				status: "published",
				body: "<p>Writable Cloudflare body</p>",
				seoTitle: "Cloudflare write post",
				metaDescription: "Writable Cloudflare record",
			},
		});
		expect(await cloudflare.revisions.list("cloudflare-write-post")).toEqual(
			expect.arrayContaining([
				expect.objectContaining({
					id: "cloudflare-write-revision",
					recordId: "cloudflare-write-post",
				}),
			]),
		);

		await cloudflare.content.delete("/legacy-cloudflare-write-post");
		await cloudflare.media.delete("cloudflare-upload");

		expect(await cloudflare.content.get("/legacy-cloudflare-write-post")).toBeNull();
		expect(await cloudflare.media.get("cloudflare-upload")).toBeNull();

		db.close();
	});

	it("throws when saving an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = makeDb();
		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		await expect(
			cloudflare.content.save({
				id: "comment-1",
				kind: "comment",
				slug: "comment-1",
				status: "published",
				metadata: {},
			} as Parameters<typeof cloudflare.content.save>[0]),
		).rejects.toThrow("does not support saving comment records yet");

		db.close();
	});

	it("returns without throwing when deleting an unsupported record kind", async () => {
		registerCms({
			templateKeys: ["content"],
			siteUrl: "https://example.com",
			seedPages: [],
			archives: [],
			translationStatus: [],
		});

		const db = await createSeededCloudflareDatabase();

		// Insert a comment record — the Cloudflare adapter lists comments via readStore
		// and surfaces them through content.get(). The delete path now degrades gracefully.
		db.prepare(
			`INSERT INTO comments (id, author, email, body, route, status, policy, submitted_at)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?)`,
		).run(
			"comment-del-1",
			"Test Author",
			"test@example.com",
			"Test comment",
			"/blog",
			"pending",
			"open-moderated",
			"2026-01-01T00:00:00.000Z",
		);

		const cloudflare = createAstropressCloudflareAdapter({
			db: new SqliteBackedD1Database(db),
		});

		// Unsupported record kind — adapter degrades gracefully (no-op) rather than throwing
		await expect(cloudflare.content.delete("comment-del-1")).resolves.toBeUndefined();

		db.close();
	});
});

