import { describe, expect, it } from "vitest";
import { createAstropressHostedPlatformAdapter } from "../src/hosted-platform-adapter.js";
import type { AuthStore, ContentStore, MediaStore, RevisionStore } from "../src/platform-contracts";

describe("hosted platform adapter", () => {
	it("assembles a hosted provider from explicit store modules", async () => {
		const records = new Map<string, string>();
		const content: ContentStore = {
			async list() {
				return [...records.entries()].map(([id, title]) => ({
					id,
					kind: "post" as const,
					slug: id,
					status: "published" as const,
					title,
				}));
			},
			async get(id) {
				const title = records.get(id);
				return title
					? {
							id,
							kind: "post",
							slug: id,
							status: "published",
							title,
						}
					: null;
			},
			async save(record) {
				records.set(record.id, String(record.title ?? record.id));
				return record;
			},
			async delete(id) {
				records.delete(id);
			},
		};

		const media: MediaStore = {
			async put(asset) {
				return asset;
			},
			async get() {
				return null;
			},
			async delete() {},
		};

		const revisions: RevisionStore = {
			async list() {
				return [];
			},
			async append(revision) {
				return revision;
			},
		};

		const auth: AuthStore = {
			async signIn(email) {
				return { id: "supabase-session-1", email, role: "admin" };
			},
			async signOut() {},
			async getSession(sessionId) {
				return { id: sessionId, email: "admin@example.com", role: "admin" };
			},
		};

		const adapter = createAstropressHostedPlatformAdapter({
			providerName: "supabase",
			content,
			media,
			revisions,
			auth,
			defaultCapabilities: {
				staticPublishing: false,
			},
		});

		expect(adapter.capabilities.name).toBe("supabase");
		expect(adapter.capabilities.hostedAdmin).toBe(true);

		await adapter.content.save({
			id: "remote-post",
			kind: "post",
			slug: "remote-post",
			status: "published",
			title: "Remote post",
		});

		expect(await adapter.content.get("remote-post")).toMatchObject({
			slug: "remote-post",
			title: "Remote post",
		});
		expect(await adapter.auth.signIn("admin@example.com", "password")).toMatchObject({
			email: "admin@example.com",
			role: "admin",
		});
	});

	it("defaults capabilities (hostedAdmin/serverRuntime/etc) to true when no overrides", () => {
		const adapter = createAstropressHostedPlatformAdapter({
			providerName: "supabase",
		});
		expect(adapter.capabilities.name).toBe("supabase");
		expect(adapter.capabilities.hostedAdmin).toBe(true);
		expect(adapter.capabilities.previewEnvironments).toBe(true);
		expect(adapter.capabilities.serverRuntime).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
		expect(adapter.capabilities.objectStorage).toBe(true);
		expect(adapter.capabilities.gitSync).toBe(true);
	});

	it("defaultCapabilities overrides shadow the built-in defaults", () => {
		const adapter = createAstropressHostedPlatformAdapter({
			providerName: "supabase",
			defaultCapabilities: {
				database: false,
				objectStorage: false,
			},
		});
		expect(adapter.capabilities.database).toBe(false);
		expect(adapter.capabilities.objectStorage).toBe(false);
		// Non-overridden fields keep the built-in defaults.
		expect(adapter.capabilities.hostedAdmin).toBe(true);
	});

	it("uses backingAdapter when provided (skips in-memory factory)", async () => {
		// Marker fields on the backingAdapter must surface in the result.
		const backingAdapter = {
			capabilities: {
				name: "marker-provider",
				database: true,
				hostedAdmin: false,
			},
			content: {
				async list() {
					return ["from-backing"] as never;
				},
				async get() {
					return null;
				},
				async save(r: never) {
					return r;
				},
				async delete() {},
			},
			media: {
				async put(a: never) {
					return a;
				},
				async get() {
					return null;
				},
				async delete() {},
			},
			revisions: {
				async list() {
					return [];
				},
				async append(r: never) {
					return r;
				},
			},
			auth: {
				async signIn() {
					return { id: "backing-session", email: "x", role: "admin" } as never;
				},
				async signOut() {},
				async getSession() {
					return null;
				},
			},
		} as never;
		const adapter = createAstropressHostedPlatformAdapter({
			providerName: "supabase",
			backingAdapter,
		});
		// content list must come from backing, not from an in-memory store.
		expect(await adapter.content.list()).toEqual(["from-backing"]);
		// signIn comes from backing too.
		const session = await adapter.auth.signIn("x", "p");
		expect(session).toMatchObject({ id: "backing-session" });
	});

	it("merges backing capabilities under the hosted defaults (hosted defaults win)", () => {
		const backingAdapter = {
			capabilities: {
				name: "ignored-by-merge",
				hostedAdmin: false,
				database: false,
			},
			content: {
				async list() {
					return [];
				},
				async get() {
					return null;
				},
				async save(r: never) {
					return r;
				},
				async delete() {},
			},
			media: {
				async put(a: never) {
					return a;
				},
				async get() {
					return null;
				},
				async delete() {},
			},
			revisions: {
				async list() {
					return [];
				},
				async append(r: never) {
					return r;
				},
			},
			auth: {
				async signIn() {
					return null;
				},
				async signOut() {},
				async getSession() {
					return null;
				},
			},
		} as never;
		const adapter = createAstropressHostedPlatformAdapter({
			providerName: "supabase",
			backingAdapter,
		});
		// providerName from options wins over the backing's name.
		expect(adapter.capabilities.name).toBe("supabase");
		// hosted defaults override backing's `false`.
		expect(adapter.capabilities.hostedAdmin).toBe(true);
		expect(adapter.capabilities.database).toBe(true);
	});
});

tests/runtime-route-registry-dispatch.te.source:
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("../src/local-runtime-modules", () => ({
	loadLocalCmsRegistry: vi.fn(),
}));

import { registerCms } from "../src/config";
import { loadLocalCmsRegistry } from "../src/local-runtime-modules";
import {
	loadSafeLocalCmsRegistry,
	localeFromPath,
	parseSettings,
	withSafeRouteRegistryFallback,
} from "../src/runtime-route-registry-dispatch";

const CMS_CONFIG_KEY = Symbol.for("astropress.cms-config");

afterEach(() => {
	(globalThis as typeof globalThis & { [CMS_CONFIG_KEY]?: unknown })[CMS_CONFIG_KEY] = null;
	vi.restoreAllMocks();
});

describe("loadSafeLocalCmsRegistry", () => {
	it("returns the registry when load succeeds", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "ok",
		});
		expect(await loadSafeLocalCmsRegistry()).toEqual({ marker: "ok" });
	});

	it("returns null when load throws", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(new Error("nope"));
		expect(await loadSafeLocalCmsRegistry()).toBeNull();
	});
});

describe("withSafeRouteRegistryFallback", () => {
	it("returns the operation result on success (no fallback invoked)", async () => {
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => "ok");
		expect(result).toBe("ok");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("invokes fallback with the local registry when operation throws and registry loads", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce({
			marker: "local",
		});
		const fallback = vi.fn(async (local: { marker: string }) => `fb-${local.marker}`);
		const result = await withSafeRouteRegistryFallback(fallback, "default", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("fb-local");
		expect(fallback).toHaveBeenCalledWith({ marker: "local" });
	});

	it("returns defaultValue when operation throws AND registry load fails", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockRejectedValueOnce(
			new Error("registry-also-broken"),
		);
		const fallback = vi.fn();
		const result = await withSafeRouteRegistryFallback(fallback, "default-value", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("default-value");
		expect(fallback).not.toHaveBeenCalled();
	});

	it("returns defaultValue when operation throws AND registry load returns null/undefined", async () => {
		(loadLocalCmsRegistry as ReturnType<typeof vi.fn>).mockResolvedValueOnce(null);
		const result = await withSafeRouteRegistryFallback(vi.fn(), "def", async () => {
			throw new Error("boom");
		});
		expect(result).toBe("def");
	});
});

describe("parseSettings", () => {
	it("returns null for null input", () => {
		expect(parseSettings(null)).toBeNull();
	});

	it("returns null for empty string", () => {
		expect(parseSettings("")).toBeNull();
	});

	it("returns null when JSON.parse throws", () => {
		expect(parseSettings("{not-json}")).toBeNull();
	});

	it("returns null when parsed value is not an object (number)", () => {
		expect(parseSettings("42")).toBeNull();
	});

	it("returns null when parsed value is not an object (string)", () => {
		expect(parseSettings('"hello"')).toBeNull();
	});

	it("returns null when parsed value is JSON null", () => {
		expect(parseSettings("null")).toBeNull();
	});

	it("returns the object when parse succeeds", () => {
		expect(parseSettings('{"a":1}')).toEqual({ a: 1 });
	});

	it("returns arrays as objects too (typeof [] === 'object')", () => {
		expect(parseSettings("[1,2,3]")).toEqual([1, 2, 3]);
	});
});

describe("localeFromPath", () => {
	it("returns the matching locale when pathname has /es/ prefix", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/es/about")).toBe("es");
	});

	it("returns the first locale ('en') when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es"],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when getCmsConfig throws (config not registered)", () => {
		// CMS config is unset → getCmsConfig throws → catch falls back to ['en','es'].
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("falls back to ['en','es'] when locales is missing on the config", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
		} as never);
		expect(localeFromPath("/es/x")).toBe("es");
		expect(localeFromPath("/about")).toBe("en");
	});

	it("matches strictly on `/locale/` (not on suffix or substring)", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["en", "es", "fr"],
		} as never);
		// "/escape" must not match "es" — leading-slash + trailing-slash anchored.
		expect(localeFromPath("/escape")).toBe("en");
	});

	it("returns 'en' fallback when locales array is empty", () => {
		// Pins `locales[0] ?? "en"`.
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: [],
		} as never);
		expect(localeFromPath("/about")).toBe("en");
	});

	it("returns the first custom locale when no prefix matches", () => {
		registerCms({
			siteUrl: "https://example.org",
			templateKeys: ["content"],
			seedPages: [],
			archives: [],
			locales: ["fr", "de"],
		} as never);
		expect(localeFromPath("/about")).toBe("fr");
	});
});

