import { afterEach, beforeEach, describe, expect, test, vi } from "vitest";

import { isTurnstileEnabled, verifyTurnstileToken } from "../src/turnstile";

const originalFetch = globalThis.fetch;
const originalEnv = { ...process.env };

beforeEach(() => {
	for (const key of Object.keys(process.env)) {
		if (key.startsWith("TURNSTILE_") || key.startsWith("PUBLIC_TURNSTILE_") || key === "NODE_ENV") {
			delete process.env[key];
		}
	}
});

afterEach(() => {
	globalThis.fetch = originalFetch;
	for (const k of Object.keys(process.env)) delete process.env[k];
	for (const [k, v] of Object.entries(originalEnv)) process.env[k] = v as string;
});

describe("isTurnstileEnabled", () => {
	test("returns false when TURNSTILE_SECRET_KEY is unset", () => {
		expect(isTurnstileEnabled()).toBe(false);
	});

	test("returns true when TURNSTILE_SECRET_KEY is configured", () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		expect(isTurnstileEnabled()).toBe(true);
	});
});

describe("verifyTurnstileToken", () => {
	test("returns ok when no secret is configured (dev/test mode)", async () => {
		const result = await verifyTurnstileToken({ token: "anything" });
		expect(result).toEqual({ ok: true });
	});

	test("returns error when requireConfigured + production but no secret", async () => {
		process.env.PROD = "1";
		const result = await verifyTurnstileToken({
			token: "anything",
			requireConfigured: true,
		});
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/not configured/);
	});

	test("returns error when token is missing", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		const result = await verifyTurnstileToken({ token: null });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/required/);
	});

	test("returns error when token is whitespace-only", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		const result = await verifyTurnstileToken({ token: "   " });
		expect(result.ok).toBe(false);
	});

	test("returns ok when Cloudflare verifies the token", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({ success: true }),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({
			token: "valid-token",
			ipAddress: "203.0.113.5",
		});
		expect(result).toEqual({ ok: true });
		const call = (globalThis.fetch as ReturnType<typeof vi.fn>).mock.calls[0];
		expect(call[0]).toBe("https://challenges.cloudflare.com/turnstile/v0/siteverify");
		const body = call[1].body as URLSearchParams;
		expect(body.get("secret")).toBe("secret-1");
		expect(body.get("response")).toBe("valid-token");
		expect(body.get("remoteip")).toBe("203.0.113.5");
	});

	test("returns error when Cloudflare rejects the token", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({
				success: false,
				"error-codes": ["invalid-input-response"],
			}),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "bad-token" });
		expect(result.ok).toBe(false);
		expect(result.error).toContain("invalid-input-response");
	});

	test("returns generic error when Cloudflare rejects with no error-codes", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: true,
			json: async () => ({ success: false }),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "bad" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/failed/);
	});

	test("returns error when Cloudflare returns a non-OK response", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi.fn().mockResolvedValue({
			ok: false,
			json: async () => ({}),
		}) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "any" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be verified/);
	});

	test("returns error when fetch throws", async () => {
		process.env.TURNSTILE_SECRET_KEY = "secret-1";
		globalThis.fetch = vi
			.fn()
			.mockRejectedValue(new Error("network down")) as unknown as typeof fetch;
		const result = await verifyTurnstileToken({ token: "any" });
		expect(result.ok).toBe(false);
		expect(result.error).toMatch(/could not be verified/);
	});
});

tests/sqlite-runtime/content-submissions.source:
import { describe, expect, it } from "vitest";

import { createSqliteSubmissionStore } from "../../src/sqlite-runtime/content-submissions.js";
import { makeDb } from "../helpers/make-db.js";

describe("createSqliteSubmissionStore", () => {
	it("submitContact persists a row that getContactSubmissions reads back", () => {
		const db = makeDb();
		const { sqliteSubmissionRepository } = createSqliteSubmissionStore(() => db);

		const submitted = sqliteSubmissionRepository.submitContact({
			name: "Alice",
			email: "alice@example.com",
			message: "Hello",
			submittedAt: "2026-05-03T10:00:00.000Z",
		});
		expect(submitted.ok).toBe(true);

		const rows = sqliteSubmissionRepository.getContactSubmissions();
		expect(rows).toHaveLength(1);
		expect(rows[0]?.email).toBe("alice@example.com");
		expect(rows[0]?.name).toBe("Alice");
		expect(rows[0]?.message).toBe("Hello");
	});

	it("getContactSubmissions returns rows ordered by submitted_at DESC then id DESC", () => {
		const db = makeDb();
		const { sqliteSubmissionRepository } = createSqliteSubmissionStore(() => db);

		sqliteSubmissionRepository.submitContact({
			name: "First",
			email: "first@x",
			message: "1",
			submittedAt: "2026-05-01T10:00:00.000Z",
		});
		sqliteSubmissionRepository.submitContact({
			name: "Second",
			email: "second@x",
			message: "2",
			submittedAt: "2026-05-03T10:00:00.000Z",
		});

		const rows = sqliteSubmissionRepository.getContactSubmissions();
		expect(rows.map((r) => r.email)).toEqual(["second@x", "first@x"]);
	});

	it("schedulePublish + listScheduled returns the future scheduled row", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		// Seed an existing entry so the schedulePublish UPDATE can find a row
		// to set scheduled_at on.
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("hello-world", "/hello-world", "Hello World");

		const future = new Date(Date.now() + 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("hello-world", future);

		const scheduled = sqliteSchedulingRepository.listScheduled();
		expect(scheduled).toHaveLength(1);
		expect(scheduled[0]?.slug).toBe("hello-world");
		expect(scheduled[0]?.scheduledAt).toBe(future);
	});

	it("cancelScheduledPublish clears scheduled_at and listScheduled drops the row", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("a", "/a", "A");

		const future = new Date(Date.now() + 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("a", future);
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(1);

		sqliteSchedulingRepository.cancelScheduledPublish("a");
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(0);
	});

	it("runScheduledPublishes promotes due entries to published and returns the row count", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("due", "/due", "Due");

		const past = new Date(Date.now() - 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("due", past);

		const changed = sqliteSchedulingRepository.runScheduledPublishes();
		expect(changed).toBe(1);
		// scheduled_at cleared after promotion.
		const row = db
			.prepare("SELECT status, scheduled_at FROM content_overrides WHERE slug = ?")
			.get("due") as { status: string; scheduled_at: string | null };
		expect(row.status).toBe("published");
		expect(row.scheduled_at).toBeNull();
	});

	it("listScheduled excludes entries whose scheduled_at is in the past", () => {
		const db = makeDb();
		const { sqliteSchedulingRepository } = createSqliteSubmissionStore(() => db);
		db.prepare(
			"INSERT INTO content_entries (slug, legacy_url, title, kind, body) VALUES (?, ?, ?, 'page', '')",
		).run("past", "/past", "P");

		const past = new Date(Date.now() - 60_000).toISOString();
		sqliteSchedulingRepository.schedulePublish("past", past);

		// Past entries don't appear in listScheduled (>now filter).
		expect(sqliteSchedulingRepository.listScheduled()).toHaveLength(0);
	});
});

tests/content-locking.test.ts.source:
import type { DatabaseSync } from "node:sqlite";
import { beforeEach, describe, expect, it } from "vitest";

import { createSqliteLocksOps } from "../src/sqlite-runtime/locks.js";
import { makeDb } from "./helpers/make-db.js";

describe("createSqliteLocksOps — pessimistic content locking", () => {
	let db: DatabaseSync;
	let locks: ReturnType<typeof createSqliteLocksOps>;

	beforeEach(() => {
		db = makeDb();
		locks = createSqliteLocksOps(() => db);
	});

	it("acquire succeeds for first requester", () => {
		const result = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(result.ok).toBe(true);
		if (result.ok) {
			expect(result.lockToken).toBeTruthy();
			expect(result.expiresAt).toBeTruthy();
		}
	});

	it("acquire returns conflict when another user holds the lock", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const conflict = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(conflict.ok).toBe(false);
		if (!conflict.ok) {
			// Pins L53 BooleanLiteral `conflict: true` — without an explicit
			// assertion the field could flip to false and the existing
			// destructuring branch would silently skip.
			expect(conflict.conflict).toBe(true);
			expect(conflict.lockedByEmail).toBe("alice@test.com");
			expect(conflict.lockedByName).toBe("Alice");
			expect(conflict.expiresAt).toBeTruthy();
		}
	});

	it("rolls back the open transaction on conflict so the same connection can acquire again (pins L50 ROLLBACK)", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const conflict = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(conflict.ok).toBe(false);
		// L50 mutates `db.exec("ROLLBACK")` → `db.exec("")`. Without the rollback
		// the BEGIN IMMEDIATE transaction stays open on this shared connection;
		// the next acquireLock would throw "cannot start a transaction within
		// a transaction". Alice re-acquiring her own lock must just work.
		const aliceAgain = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(aliceAgain.ok).toBe(true);
	});

	it("releaseLock returns true when a matching row is deleted (pins L91 boundary)", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;
		const released = locks.releaseLock("my-post", acquired.lockToken);
		expect(released).toBe(true);
	});

	it("releaseLock returns false for unknown token (pins L91 boundary)", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const released = locks.releaseLock("my-post", "wrong-token");
		expect(released).toBe(false);
	});

	it("same user re-acquiring refreshes the lock", () => {
		const first = locks.acquireLock("my-post", "alice@test.com", "Alice");
		const second = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(first.ok).toBe(true);
		expect(second.ok).toBe(true);
		if (first.ok && second.ok) {
			expect(second.lockToken).not.toBe(first.lockToken);
		}
	});

	it("heartbeat (refreshLock) extends expiry and returns true", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;

		const refreshed = locks.refreshLock("my-post", acquired.lockToken);
		expect(refreshed).toBe(true);
	});

	it("refreshLock returns false for unknown token", () => {
		locks.acquireLock("my-post", "alice@test.com", "Alice");
		const refreshed = locks.refreshLock("my-post", "bad-token");
		expect(refreshed).toBe(false);
	});

	it("release enables immediate re-acquire by another user", () => {
		const acquired = locks.acquireLock("my-post", "alice@test.com", "Alice");
		expect(acquired.ok).toBe(true);
		if (!acquired.ok) return;

		locks.releaseLock("my-post", acquired.lockToken);

		const bob = locks.acquireLock("my-post", "bob@test.com", "Bob");
		expect(bob.ok).toBe(true);
	});

	it("expired lock allows re-acquire by another user", () => {
		// Insert an expired lock row directly
		const pastExpiry = new Date(Date.now() - 1000).toISOString();
		db.prepare(
			`INSERT INTO content_locks (slug, locked_by_email, locked_by_name, lock_token, expires_at)
       VALUES (?, ?, ?, ?, ?)`,
		).run("stale-post", "alice@test.com", "Alice", "old-token", pastExpiry);

		const bob = locks.acquireLock("stale-post", "bob@test.com", "Bob");
		expect(bob.ok).toBe(true);
	});
});

tests/admin-slug-cache.test.ts.source:
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

vi.mock("../src/runtime-page-store", () => ({
	getRuntimeSettings: vi.fn(),
}));

import {
	invalidateAstropressAdminSlugCache,
	resolveAstropressAdminSlug,
} from "../src/admin-slug-cache";
import { getRuntimeSettings } from "../src/runtime-page-store";

const mockedGetRuntimeSettings = vi.mocked(getRuntimeSettings);

beforeEach(() => {
	invalidateAstropressAdminSlugCache();
	mockedGetRuntimeSettings.mockReset();
});

afterEach(() => {
	invalidateAstropressAdminSlugCache();
});

const FAKE_LOCALS = {} as never;

describe("resolveAstropressAdminSlug", () => {
	it("returns the configured adminSlug from settings", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "custom-admin",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("custom-admin");
	});

	it("falls back to ap-admin when adminSlug is empty string", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({ adminSlug: "" } as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("falls back to ap-admin when adminSlug is undefined", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("returns ap-admin when getRuntimeSettings throws", async () => {
		mockedGetRuntimeSettings.mockRejectedValueOnce(new Error("boom"));
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("ap-admin");
	});

	it("caches the resolved slug across calls within TTL", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "first",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
		// Second call: settings would return "second" but cache should win.
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "second",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
		expect(mockedGetRuntimeSettings).toHaveBeenCalledOnce();
	});

	it("re-fetches after the cache TTL elapses", async () => {
		vi.useFakeTimers();
		try {
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "first",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");

			// Advance just past the 60s TTL.
			vi.advanceTimersByTime(60_001);

			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "second",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});

	// Boundary: at EXACTLY TTL_MS the cache expires (strict <, not <=).
	// Pins the EqualityOperator mutation: now - cachedAt < TTL → <= TTL.
	// With the mutation, at exactly TTL the cache would still be served.
	it("re-fetches at exactly the TTL boundary (strict-less-than semantics)", async () => {
		vi.useFakeTimers();
		try {
			// Cache "first" at t=0.
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "first",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
			// Within TTL: cache wins, no extra fetch.
			vi.advanceTimersByTime(59_999);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("first");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledOnce();

			// Advance to exactly TTL: with strict-less-than, the cache is
			// stale and we re-fetch. With the < → <= mutation, the cache
			// would still be served and "second" would never be reached.
			vi.advanceTimersByTime(1);
			mockedGetRuntimeSettings.mockResolvedValueOnce({
				adminSlug: "second",
			} as never);
			expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
			expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
		} finally {
			vi.useRealTimers();
		}
	});

	it("invalidate forces the next call to refetch", async () => {
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "first",
		} as never);
		await resolveAstropressAdminSlug(FAKE_LOCALS);
		invalidateAstropressAdminSlugCache();
		mockedGetRuntimeSettings.mockResolvedValueOnce({
			adminSlug: "second",
		} as never);
		expect(await resolveAstropressAdminSlug(FAKE_LOCALS)).toBe("second");
		expect(mockedGetRuntimeSettings).toHaveBeenCalledTimes(2);
	});
});

