import { describe, expect, it } from "vitest";
import { parseSections } from "../../src/sections/schema";
import {
	buildTemplate,
	isTemplateKey,
	TEMPLATE_CATALOG,
	TEMPLATE_KEYS,
} from "../../src/sections/templates";

describe("page templates", () => {
	it("blank produces no sections", () => {
		expect(buildTemplate("blank")).toEqual([]);
	});

	it("landing produces hero, feature-grid, testimonials, cta-banner", () => {
		const sections = buildTemplate("landing");
		expect(sections.map((s) => s.kind)).toEqual([
			"hero",
			"feature-grid",
			"testimonials",
			"cta-banner",
		]);
	});

	it("about includes hero, image-text, feature-grid, cta-banner", () => {
		expect(buildTemplate("about").map((s) => s.kind)).toEqual([
			"hero",
			"image-text",
			"feature-grid",
			"cta-banner",
		]);
	});

	it("contact includes hero, image-text, faq, cta-banner", () => {
		expect(buildTemplate("contact").map((s) => s.kind)).toEqual([
			"hero",
			"image-text",
			"faq",
			"cta-banner",
		]);
	});

	it("each template's output round-trips through parseSections", () => {
		for (const key of TEMPLATE_KEYS) {
			const sections = buildTemplate(key);
			const parsed = parseSections(sections);
			expect(parsed.ok, `${key} must validate`).toBe(true);
		}
	});

	it("uses unique ids within a single template invocation", () => {
		const sections = buildTemplate("landing");
		const ids = sections.map((s) => s.id);
		expect(new Set(ids).size).toBe(ids.length);
	});

	it("isTemplateKey rejects unknown keys", () => {
		expect(isTemplateKey("landing")).toBe(true);
		expect(isTemplateKey("nope")).toBe(false);
	});

	it("TEMPLATE_CATALOG covers all template keys", () => {
		const catalogKeys = TEMPLATE_CATALOG.map((e) => e.key).sort();
		expect(catalogKeys).toEqual([...TEMPLATE_KEYS].sort());
	});

	it("each catalog entry's sectionKinds matches the built sections", () => {
		for (const entry of TEMPLATE_CATALOG) {
			const built = buildTemplate(entry.key).map((s) => s.kind);
			expect(built).toEqual(entry.sectionKinds);
		}
	});
});

tests/publish-audit.test.ts.source:
import { describe, expect, it, vi } from "vitest";
import { recordPublishAudit } from "../src/admin-action-publish";

const actor = {
	email: "admin@example.com",
	role: "admin" as const,
	name: "Admin",
};

function buildD1Locals() {
	const run = vi.fn().mockResolvedValue(undefined);
	const bind = vi.fn().mockReturnValue({ run });
	const prepare = vi.fn().mockReturnValue({ bind });
	const locals = {
		runtime: { env: { DB: { prepare } } },
	} as unknown as App.Locals;
	return { locals, prepare, bind, run };
}

describe("recordPublishAudit", () => {
	it("writes a deployment.trigger event for a successful build", async () => {
		const { locals, bind } = buildD1Locals();

		await recordPublishAudit(locals, actor, {
			hookType: "cloudflare-pages",
			result: { ok: true, buildId: "build-123" },
		});

		expect(bind).toHaveBeenCalledWith(
			"admin@example.com",
			"deployment.trigger",
			"deployment",
			"build-123",
			"Triggered cloudflare-pages publish (build build-123).",
		);
	});

	it("writes a deployment.failure event with the error message when the hook fails", async () => {
		const { locals, bind } = buildD1Locals();

		await recordPublishAudit(locals, actor, {
			hookType: "vercel",
			result: { ok: false, error: "deploy hook returned 503" },
		});

		expect(bind).toHaveBeenCalledWith(
			"admin@example.com",
			"deployment.failure",
			"deployment",
			"vercel",
			"vercel publish failed: deploy hook returned 503",
		);
	});

	it("falls back to the hook type as resourceId when buildId is absent", async () => {
		const { locals, bind } = buildD1Locals();

		await recordPublishAudit(locals, actor, {
			hookType: "github-actions",
			result: { ok: true },
		});

		expect(bind).toHaveBeenCalledWith(
			"admin@example.com",
			"deployment.trigger",
			"deployment",
			"github-actions",
			"Triggered github-actions publish.",
		);
	});
});

